pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "usable slots"
    // for common small-item classes (multiples of 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 22.0; }
        else if pr % 25 == 0 { bonus += 14.0; }
        else if pr % 20 == 0 { bonus += 12.0; }
        else if pr % 10 == 0 { bonus += 8.0; }
        // small dead space is worse than large usable space
        if pr < 10 { bonus -= 18.0; }
        score -= bonus;

        // Integer-division thresholds: residual bucket quality
        let bucket = pr / 10; // 0..10
        score += (bucket as f64 - 5.0) * -0.5; // mildly favor mid/large residuals
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact or near-exact chaining is excellent
            if pr == next_item_size { score -= 45.0; }
            else if pr - next_item_size < 10 { score -= 25.0; }
            else { score -= 10.0; }
        } else {
            score += 8.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current item leaves awkward residue or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = if post_residual < 10 { 1.0 } else { 0.0 };
        score = 40.0 + 20.0 * progress + 25.0 * awkward - 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // fresh bin can chain large items
        }
    }

    // Fragmentation penalty relative to mean residual across open bins
    if bin_residual != bin_capacity {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    // Reward strongly when the NEXT item exactly fills the post_residual (perfect chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match (gap 0) gets a big bonus; decays quadratically with gap.
        let match_bonus = 60.0 * (1.0 - gap / post_residual as f64).powi(2);
        score -= match_bonus;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize, more so for large wasted tails.
        let dead = post_residual as f64;
        let next_fits_elsewhere_hint = (next_item_size as f64) / bin_capacity as f64;
        score += 8.0 * dead * (0.5 + 0.5 * next_fits_elsewhere_hint) * (1.0 + progress);
    }

    // Penalize tiny unusable residuals (< 10, minimum item size) harder as stream progresses.
    if post_residual < 10 {
        score += 25.0 + 20.0 * progress;
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 6.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: discourage opening yet another bin; encourage consolidation.
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate: keep it attractive only when no open bin offers a good fit
    // (i.e., post_residual of this fresh bin is large and next item may chain into it).
    if bin_residual == bin_capacity {
        let fresh_bonus = 20.0
            + (next_item_size as f64) * 0.15
            + 15.0 * progress
            + if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 };
        score -= fresh_bonus;
        // But if a last-chance bin exists, prefer using it instead of a fresh bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items (1..=10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range unusable gaps (too small for medium items) get a soft penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (post residual near zero but not creating a tiny gap).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual >= 20 && post_residual <= 40 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits the post residual, this placement
    // chains nicely; reward it. If it nearly fits, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual + 5 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; favor consolidation and new-bin avoidance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Prefer bins whose residual is already below average (consolidate
    // fragmented bins), mildly.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate calibration: an empty bin has zero dead-space risk
    // but incurs the open-bin pressure cost; ensure it loses against
    // reasonable fits but wins against terrible fits (already handled by
    // the dead-space penalties above).
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small post_residual gaps are "unusable" if smaller
    // than the smallest plausible item (1..100 unknown dist -> treat <20 as dead).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 * 2.0;
    score += open_pressure * 0.5;

    // Lookahead: if next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would NOT fit here, slight penalty (this bin is a dead end).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: bins with residual near mean are neutral;
    // prefer placing into bins with larger residual (keep small-residual bins tight).
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = 70.0 + 10.0 * (fitting_bins_count as f64).recip();
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strong penalty for leaving gaps that can't fit the next item when lookahead exists
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Pressure from number of open bins: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mild preference for fuller bins relative to mean residual
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 60.0 - 3.0 * item_size as f64;
    }

    // Stream progression: slightly more conservative early, willing to open bins later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains into this bin: excellent.
            let chain_waste = post_residual - next_item_size;
            score -= 150.0 - (chain_waste as f64) * 1.5;
            // Perfect two-item packing bonus.
            if chain_waste == 0 {
                score -= 250.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap just below next_item_size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 300.0;
    }

    // Prefer bins below mean residual (use up loose space first),
    // penalize eating into bins that are already tight.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + (post_residual <= 20) as i32 as f64 * 60.0;
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // New bin: score = leftover space; add penalty that shrinks with item size
        // and with stream progress (early on, keep bins open; later, consolidate).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * (1.0 - progress) + (item_size as f64) * 0.1;
        // If many bins are open, discourage opening yet another one.
        score += open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: bonus proportional to fill ratio.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 20.0 * fill * fill;

    // Penalize dead space: residual too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap; // next item won't fit here
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Global state: if mean residual is high, bins are loose; prefer reusing them.
    score -= 0.05 * mean_residual;

    // Time horizon: early in stream, be more willing to open new bins (flexibility);
    // late in stream, consolidate tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - t) * (post / cap);

    // New-bin candidate: make it competitive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin scores by its full residual; adjust with state.
        score = cap - 15.0 * (1.0 - t) - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        // Small post-residual is likely dead space for items >= 10.
        score += 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // enabling a two-item chain; penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin when decent fits exist,
    // but allow it when open bins would leave large dead space or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Opening a new bin is attractive when the item is large (few will stack anyway)
        // or when open bins are congested (low mean residual) and many exist.
        score = 45.0
            - 30.0 * pressure
            - 10.0 * progress
            + 0.8 * mean_residual
            - 2.0 * open_bins_count as f64;
        // A large item that leaves a reusable gap (~50) is fine in a fresh bin.
        if post_residual >= 50 {
            score -= 15.0;
        }
    }

    // Mild global congestion coupling: when many bins are open and mean residual is low,
    // prefer consolidating into existing bins (already reflected); when mean residual is high,
    // slightly discourage wasting it on small items.
    if bin_residual != bin_capacity {
        score += 0.05 * mean_residual * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: leaving no dead space is ideal.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize small unusable residuals (dead space below typical minimum item size).
        let min_item = 1.0;
        if (post_residual as f64) < min_item * 2.0 {
            score += 100.0;
        }
        // Exponential penalty for tiny-but-nonzero dead space.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += (1.0 - tightness) * 30.0;
    }

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can also fit here: strong reward for chained placement.
            let chain_fit = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 120.0 + 80.0 * chain_fit;
            // Extra reward if the chain nearly exhausts the bin.
            if post_residual - next_item_size <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit after this placement; mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            // If the next item could fit in mean residual, prefer bins keeping that option.
            if mean_residual >= next_item_size as f64 && post_residual < next_item_size {
                score += 25.0;
            }
        }
        // If the current bin could have chained but we'd waste a large residual, penalize.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 40.0 * (1.0 - progress);
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score -= 200.0;
    }

    // ---- Relative-to-mean coupling ----
    // Bins with residual below mean are already tight; placing here (good fit) is favored.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin if fit is decent.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 90.0;
        } else {
            score -= 30.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is worthwhile when existing fits are poor (large post_residual
        // spread across fitting bins) or the item is small relative to residual.
        let poor_fits = if fitting_bins_count > 0 {
            let avg_post = mean_residual - item_size as f64;
