}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post-residual

    // Smooth polynomial coupling of post-residual with stream progress.
    let poly = x * (1.0 - x) * (1.0 - progress) * 8.0;

    // Penalize leaving residual close to but above typical small item sizes.
    let dead = if next_item_size > 0 {
