    let last_chance = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // Slight preference to fill bins tightly relative to mean residual.
    let mean_coupling = -(x - mean_residual / cap) * (x - mean_residual / cap) * 0.3;

    // Mild pressure toward opening new bins late in the stream if residual is large.
    let progress_coupling = x * progress * 1.5;

