    } else if post_residual <= 10 {
        score += 25.0; // likely dead space
    } else {
        // Usable residual: reward proportionally to band, with harmonic decay.
        score -= (band as f64).powf(0.5) * 3.0;
    }

    // Lookahead: does post_residual exactly or nearly fit the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chained perfect fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (10.0 - slack.min(10.0)) * 2.0; // reward tight lookahead fits
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // and the item is large (better to start fresh for big items).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let tight_fit = post_residual <= 10 && post_residual > 0;
        // Opening a new bin is good only if this placement elsewhere would
        // leave a tight unusable gap AND item is big.
        if tight_fit && fill > 0.6 {
            score -= 20.0;
        } else {
            score += 15.0 + 20.0 * (1.0 - fill);
        }
    }

    // Fractional capacity coupling: reward fill ratio non-linearly.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * fill_ratio * 20.0;

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it's a "cramped" bin — prefer filling cramped bins first.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.2;

    // Stream progression: early on, be conservative about tight gaps;
    // late in stream, squeeze aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 - t); // tolerate slivers early, punish late
    }

    // Modulo harmonic: post_residual divisible by 5 keeps future pairing options.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (min item size 1, but small gaps rarely match future items). Penalize
    // hard any post_residual in the "dead zone" (1..=9).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when the item is large relative to residual or fits are bad.
    if bin_residual == bin_capacity {
        // Mild inherent cost for opening a new bin, scaled by how many are open.
        score += 10.0 + open_bins_count as f64 * 0.5;
        // But if the item is big, a new bin is natural (large item in empty bin
        // leaves a predictable residual).
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Open-bins pressure: when many bins are open, consolidate into them
    // (penalize new bins implicitly, reward using existing ones).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill_ratio);

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving a gap it can't use.
            score += 5.0;
        }
    }

    // Stream progression: late in the stream, be more aggressive at closing
    // bins tightly (dead space matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already tight — finishing it off is good.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.1 * (bin_res_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    // Strong bonus if the NEXT item exactly fills the residual left behind (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step chain: this bin will be exactly filled by the next item.
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item can also go here: good chaining, reward proportionally.
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // Next item cannot use the leftover: penalize dead space, scaled by how
            // useless the leftover is (small leftovers < 10 are dead weight).
            if post_residual < 10 {
                score += 60.0;
            }
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" bins;
    // placing into them is efficient, so reward slightly; bins far above mean are loose.
    let dev = mean_residual - post_residual as f64;
    score -= 0.2 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only prefer it when the item is huge or no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; the lookahead bonus above can override
        // it if a perfect 2-step chain exists (fresh bin leaves exactly next_item_size).
        score += 25.0;
        // If next item would perfectly fill the fresh bin's leftover, big reward already applied.
        // Extra nudge when many bins are open (consolidate instead of proliferating).
        if open_bins_count > 3 {
            score += 10.0 * open_bins_count as f64;
        }
    }

    // Slight preference for bins that become "closed" (post_residual == 0).
    if post_residual == 0 {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tightness reward: fraction of bin used
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Lookahead: reward if next item can fit in the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless they're bad
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if all open bins are fragmented (high mean residual spread), opening fresh is fine
        if mean_residual < 20.0 {
            score -= 8.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor filling bins well);
    // late in stream, prioritize closing bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Penalize bins whose residual is far below the mean (fragmented outliers)
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fills; late in stream, dead space matters more.
    let w = 0.5 + 0.5 * progress; // smooth weight in [0.5, 1.0]
    score += w * norm_pr * norm_pr * cap * 0.4;

    // Non-linear fit-quality term: reward near-perfect fits via smooth decay.
    let fit = 1.0 - norm_pr;
    score -= (fit * fit * 4.0 - fit * fit * fit * fit) * cap * 0.3;

    // Lookahead coupling: smooth quadratic interaction between post-residual
    // and next item size — reward if next item fits the post-residual.
    let gap = norm_pr - norm_next;
    let gap_norm = gap.abs();
    score += (gap_norm * gap_norm) * cap * 0.25;
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - gap_norm);
    }

    // Last-chance bonus: smoothly stronger when few fitting bins.
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= scarcity * 12.0 * (1.0 + progress);

    // Mild penalty for spreading across many open bins (smooth saturation).
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Pull toward mean residual state: smooth quadratic deviation penalty.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.2;

    // New-bin candidate handling: make empty bins mildly attractive only
    // when the fit into open bins would be poor.
    if bin_residual == bin_capacity {
        score += 4.0 - 30.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Bands: (0..=12], (12..=25], (25..=50], (50..=75], (75..100)
    let frac = post_residual as f64 / bin_capacity as f64;
    let band: f64 = if post_residual == 0 {
        -40.0 // perfect fill: strongest reward
    } else if post_residual <= bin_capacity / 8 {
        12.0 // tiny dead space: bad, penalize
    } else if post_residual <= bin_capacity / 4 {
        4.0
    } else if post_residual <= bin_capacity / 2 {
        -6.0
    } else if post_residual <= 3 * bin_capacity / 4 {
        -10.0
    } else {
        -14.0 // nearly empty after placement: roomy bin, good
    };
    score += band;

    // Modulo arithmetic on post_residual: residuals divisible by small harmonics
    // (e.g. multiples of 5, 10) are more likely to be exactly filled by future items.
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }
    if post_residual % 3 == 0 {
        score -= 1.0;
    }

    // Integer-division threshold: post_residual / item_size ratio
    // (how many copies of the current item would still fit) — high reuse potential.
    if item_size > 0 {
        let copies = post_residual / item_size;
        score -= copies as f64 * 2.0;
    }

    // Lookahead harmony: if the next item exactly fills the post residual,
    // this is a golden chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: bonus scaled by how snugly
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize wasted compatibility
            score += 3.0;
            // harmonic mismatch penalty: next item leaves awkward class
            if (post_residual + next_item_size) % 10 != 0 && (post_residual + next_item_size) > bin_capacity {
                score += 2.0;
            }
        }
    } else {
        // last item: prefer zero residual above all
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= bin_capacity / 8 && post_residual > 0 {
            score += 8.0; // but not if it creates a tiny unusable hole
        }
    }

    // New-bin candidate handling: an empty bin has full residual; make it
    // attractive only when open bins are crowded or residual mean is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
        let poor_mean = mean_residual < item_size as f64 * 1.2;
        if crowded || poor_mean || post_residual >= item_size {
            score -= 6.0 + 4.0 * progress;
        } else {
            score += 10.0; // keep consolidating into open bins early
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Mild preference for tighter bins overall (best-fit flavor) as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += bin_residual as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, zero waste
    } else if post_residual < 10 {
        // unusable dead space (below minimum item size domain 1..100 practical floor)
        score += 40.0 + 6.0 * (10 - post_residual) as f64;
    } else {
        // graded penalty: quadratic in wasted capacity, normalized to capacity
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste_frac * waste_frac;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 8.0 * (item_size as f64 / (item_size + post_residual) as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading (favor filling
    // existing bins); when few bins are open, tolerate opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress) * 0.35;

    // New-bin candidate handling: empty bin gets a baseline cost so it only wins
    // when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.05;
        // late in the stream, closing out is cheap: reduce new-bin penalty
        score -= 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement strongly (chain fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild alignment with mean residual: prefer bins close to the average fill state.
    score += (mean_residual - bin_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            // Next item fits here afterwards: reward tight two-item packing.
            let two_step_slack = post_residual as f64 - n;
            score -= 60.0 * (1.0 - two_step_slack / bin_capacity as f64);
            // Extra bonus if next item fills the bin almost perfectly after this one.
            if two_step_slack <= 5.0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap that matches nothing.
            score += 25.0;
            // If the gap is small (dead space), penalize more.
            if (post_residual as f64) < n && post_residual > 0 {
                score += 15.0 * (1.0 - post_residual as f64 / n);
            }
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current fit is bad and lookahead is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 50.0;
        let bad_lookahead = next_item_size == 0 || (post_residual as f64) < next_item_size as f64;
        if poor_fit && bad_lookahead {
            score -= 20.0;
        } else {
            score += 35.0;
        }
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, normalized by capacity
    let pr = post_residual as f64;
    score += 0.6 * (pr * pr) / cap;

    // Reward tight fits (small post residual) especially when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count <= 3 {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 15.0;
        } else if nxt <= pr {
            score -= 6.0 * (1.0 - pr / cap);
        } else {
            // next item won't fit here; penalize leaving medium dead space
            score += 3.0 * (pr / cap) * (pr / cap);
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual < item_size as f64 + 5.0 {
        score -= 5.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / cap) < 0.35 * (1.0 + progress);
        if crowded && open_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 10.0 + 20.0 * progress;
        }
    }

    // Slight preference for bins tighter than average
    score -= 2.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr as f64
        - 12.0 * (1.0 - x) * (1.0 - x)          // reward tight fits more than linearly
        + 30.0 * x * x * x;                      // penalize large dead space super-linearly

    // Smooth interaction: tight fits matter more early, dead space matters more late
    score += 20.0 * (1.0 - progress) * x * (1.0 - x) * 4.0;
    score -= 25.0 * progress * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let gap = (pr - nx) / cap;
            score -= 15.0 * (1.0 - gap * gap); // smooth reward for chainable fit
        } else {
            score += 10.0 * ((nx - pr) / cap); // penalize near-miss dead space
        }
    }

    // Mild pressure toward consolidation when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    // Deviation from mean residual: prefer bins whose residual differs usefully
    score += 3.0 * (pr as f64 - mean_residual).abs() / cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let is_new = bin_residual == bin_capacity;
    let mut score;

    // Harmonic class decomposition of post_residual:
    // coarse class (width 10) dominates, remainder breaks ties inside a class.
    let class = (pr / 10) as f64;
    let rem = (pr % 10) as f64;
    score = class * 12.0 + rem * 0.6;

    // Perfect fit: harmonic class 0, strongly rewarded.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling (k=2): reward bins whose residual can host the next item,
    // penalize bins whose leftover becomes dead space.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
        } else if !is_new {
            // dead space penalty scaled by unusable leftover
            score += pr as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new {
        score -= 15.0;
    }

    // New-bin candidate: pay an opening tax, refunded when the item nearly
    // fills a fresh bin (high fill fraction => low future dead space).
    if is_new {
        score += 30.0;
        let fill = item_size as f64 / bin_capacity as f64;
        score -= (fill - 0.5).max(0.0) * 40.0;
        // A fresh bin with small residual also pairs well with a small next item.
        if next_item_size > 0 && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Mild stream-progress term: later in the stream, consolidate more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 10)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 20.0;
    } else if post_residual < 20 {
        // Small gaps that only fit tiny items: moderate penalty.
        score += (20.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits (residual close to zero but usable).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is excellent; encourages consolidation when bins are numerous.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.35 + 0.25 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, this
    // placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual - next_item_size < 10 {
            score -= 6.0; // chain leaves a dead gap -> extra reward
        }
    }
    // If next item would be blocked by this placement's dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (large mean residual spread vs. item) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        score += 15.0; // base cost of opening a bin
        if fitting_bins_count <= 2 {
            score -= 20.0; // opening is reasonable when options are scarce
        }
        if poor_fits > 0.5 {
            score -= 10.0;
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 4.0; // fresh bin accommodates the lookahead too
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual
    // (larger-than-average gaps absorb items with less waste).
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: post_residual just above next item size creates dead space -> penalize.
    else if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score += 3.0 * gap;
    }
    // post_residual smaller than next item: bin becomes unusable for the next item,
    // mildly penalize unless it is small dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward bins whose residual is already below the mean (tight bins get used first),
    // penalize bins far above mean residual (loose bins should stay for bigger items).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when plenty of open bins exist (encourage consolidation),
    // scaled by stream progress (early on, opening bins is cheaper).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 60.0 + 80.0 * progress;
        // A new bin is acceptable if this item is huge and nothing tight fits.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Slight preference for leaving round-ish residuals (multiples of 10) usable later.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.05 * (post_residual - next_item_size) as f64;
    }
    // Penalize lookahead mismatch: next item almost fits but not quite (dead space risk).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 2.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Dead-space penalty for very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 8.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it costly, but cheaper for large items late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 0.25 * item_size as f64 - 10.0 * progress
            + 2.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste after placement, smoothly warped by progress
    let norm_post = post / cap;
    let warp = 1.0 + 0.9 * progress * progress; // later items: dead space penalized more
    let mut score = post * warp;

    // Non-linear polynomial coupling of fill fraction with progress
    let fill = item_size as f64 / cap;
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;
    let coupling = fill3 * (1.0 - progress) * 120.0 - fill2 * progress * 60.0;
    score -= coupling;

    // Lookahead: reward leaving room for the next item (smooth quadratic overlap)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        let overlap = (gap * gap) * 45.0 - gap * 30.0;
        score += overlap;
    } else {
        score -= 5.0; // last item: no future, slight reward for any placement
    }

    // Last-chance bin: strong smooth reward, scaled by how tight the fit is
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.25 * (post as f64);
    }

    // Crowding penalty: many open bins with high mean residual -> discourage spreading
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 0.6 * crowd * (1.0 - norm_post);

    // Mean-residual alignment: prefer bins whose residual is near the mean (smooth)
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: mild bias so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * progress * cap * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/2, 1/3, 1/4 of C)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 1000.0; // perfect fit, always best
    } else if pr <= cap / 4.0 {
        score -= 60.0; // tiny dead space, very usable
    } else if pr <= cap / 3.0 {
        score -= 25.0;
    } else if pr <= cap / 2.0 {
        score -= 8.0;
    } else {
        score += 5.0; // large residual left = item was small, wasteful
    }

    // Integer division thresholds on post_residual vs next_item_size classes
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // lookahead item can fit here afterwards -> reward
            score -= 15.0 + 20.0 * (nxt / cap);
            // exact modulo harmony: post_residual divisible into next item sizes
            if (post_residual as u32) % (next_item_size.max(1)) == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here -> penalize leaving this bin behind
            score += 10.0 + 15.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer tightest packing relative to mean residual
    score += 0.3 * (pr - mean_residual);

    // Early in stream: allow more bins; late in stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - pr / cap);

    // Slight preference against opening new bins when decent options exist
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..=12) are wasted space -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 - (post_residual as f64) * 2.0; // dead space: worst at 1..2
    } else if post_residual > 12 && post_residual <= 25 {
        score += 10.0; // marginal zone
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward filling bins deeply (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and the next item would waste space in a tight residual.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        score += 20.0 + pressure;
        // Exception: if this is the only fitting bin and next item is huge,
        // opening a fresh bin is acceptable.
        if fitting_bins_count <= 1 && next_item_size > bin_residual - item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the post-residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (perfect chaining), penalize mismatch.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff < 0.5 {
            score -= 60.0; // exact match: place next item perfectly
        } else if post_residual as f64 >= next {
            // next item fits after this one: mild reward proportional to tightness
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover dead space
            score += 8.0 * (1.0 - post_residual as f64 / next);
        }
    }

    // Tight fit reward: item fills most of the bin now
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual deviates far below mean (wasted large space)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer denser bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): keep it attractive only when it beats
    // poor fits; slight penalty so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // narrow window
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // post-residual too small for next item: mild penalty scaled by waste.
            score += 0.1 * (post_residual as f64);
        }
        // If next item exactly matches post_residual, big bonus.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is low (bins nearly full)
        // and there are few alternatives; penalize otherwise.
        score += 40.0;
        score -= 35.0 * (1.0 - crowding).powi(2);
        score -= 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0; // opening a bin beats a last-chance squeeze only if tight
        }
        if item_size > 70 {
            score -= 8.0; // big items like fresh space
        }
    }

    // Mild preference for bins below mean residual (balance spreading).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.5;
    }

    // Slight aversion to many open bins: encourage consolidation early.
    score += 0.05 * open_bins_count as f64;

    // Time-varying greediness: become more picky (favor tight fits) late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild preference for tight fits (quadratic in post).
    // Late stream: stronger pressure to minimize post_residual (cubic coupling).
    let early_term = 2.0 * norm_post * norm_post * (1.0 - progress);
    let late_term = 4.0 * norm_post * norm_post * norm_post * progress;
    score += early_term + late_term;

    // Smooth interaction: waste penalty grows as mean residual deviates from this bin's post residual.
    let spread = (mean_residual - post) / cap;
    score += 1.5 * spread * spread * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it (subtract).
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_post);
    }

    // Lookahead: penalize if post_residual cannot fit the next item smoothly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            score += 2.0 * (next - post) / cap * (0.5 + progress);
        } else {
            score -= 1.0 * (post - next) / cap;
        }
    }

    // Slight preference for reusing bins over opening new ones as stream advances.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are prized (tight fits), large residues penalized.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic bucket (0..10)
    let class_bonus = match class {
        0 => 18.0,   // near-perfect fit
        1 => 10.0,
        2 => 5.0,
        3 => 1.0,
        4 => -1.0,
        5 => -3.0,   // half-full leftover: awkward
        6 => -2.0,
        7 => -4.0,
        8 => -6.0,
        _ => -8.0,   // large dead space
    };
    score -= class_bonus;

    // Modulo-structure coupling: residues divisible by small integers pair
    // well with future items from typical modular streams.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 4.0;
    }
    // Odd/prime-ish residues are less reusable.
    if pr % 2 == 1 && pr > 20 {
        score += 2.0;
    }

    // Lookahead: does next_item_size fit exactly or nearly in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 14.0; // perfect chain
            } else if gap <= 10 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item would NOT fit here: this bin becomes dead after placement
            score += (next_item_size - pr) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or this would be a terrible fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 > 6.0 + 10.0 * progress;
        let poor_fit = post_residual > 0 && (post_residual as f64) < 0.15 * cap;
        if poor_fit {
            // prefer new bin over wrecking an open bin
            score -= 20.0;
        } else if crowded {
            score += 6.0;
        } else {
            score += 15.0; // default: prefer existing bins
        }
    }

    // Mean-residual coupling: if the fleet is tight on average, waste less.
    if (post_residual as f64) > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Late-stream tightening: near the end, prefer tightest possible fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residual gaps that are too small
    // to be useful for typical items (unusable dead space).
    if post_residual > 0 {
        if post_residual < 10 {
            // Completely dead gap: severe penalty.
            score += 40.0;
        } else if post_residual <= 20 {
            // Hard to fill: strong penalty, scaled by how close to dead it is.
            score += (20 - post_residual) as f64 * 2.0;
        } else if post_residual <= 35 {
            // Moderately awkward gap.
            score += 8.0;
        }
    } else {
        // Perfect fit: big reward.
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bins pressure: with many open bins, discourage spreading; but if
    // this is the LAST bin that fits, strongly favor using it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure proportional to number of open bins: penalize opening new bins
    // when consolidation is possible.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly with open bins count.
        score += 5.0 + (open_bins_count as f64) * 3.0;
        // If the next item is large, a fresh bin may still be attractive.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Lookahead coupling: if next item fits exactly into the post_residual,
    // reward heavily; if next item cannot use the gap, penalize mildly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Late in the stream, consolidation matters more (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight preference for bins below mean residual (balance residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (2-step lookahead style)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small post_residual is good
        score -= 200.0 / (post_residual as f64).powf(0.7);
    }

    // Lookahead: reward when post_residual matches next item size well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack); // next item also fits, reward tightness
            // Penalize leftover after next item if it becomes dead space
            if post_residual - next_item_size < 10 {
                score -= 80.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current item is large and no tight fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size > 60;
        if large_item || fitting_bins_count <= 1 {
            score -= 60.0 + 40.0 * progress;
        } else {
            score += 50.0; // prefer existing bins for small/medium items
        }
    }

    // Mild preference for consolidating among many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current fit is bad
    // or many bins are open with fragmented residuals.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // cheaper to open early in the stream when uncertainty is high? slightly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // if open bins are already fragmented (low mean residual relative to item), opening is more acceptable
        if (mean_residual < item_size as f64) && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    // Mild penalty for accumulating many open bins when this bin's fit is mediocre.
    if open_bins_count > 6 && fit_ratio < 0.7 {
        score += 2.0 * (open_bins_count as f64).ln().max(1.0);
    }

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    // in the direction of tighter packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post residual, shaped by a smooth polynomial in normalized residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - progress));

    // Smooth non-linear coupling of residual with stream progress:
    // late in the stream, tight fits matter more.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 40.0 * tightness * (0.3 + 0.7 * progress);

    // Reward when the leftover residual exactly matches the next item (smooth kernel).
    if nxt > 0.0 {
        let diff = (pr - nxt) / cap;
        score -= 25.0 * (-20.0 * diff * diff).exp();
    } else {
        // Last item: strongly prefer minimal waste.
        score += 5.0 * norm_pr;
    }

    // Penalize bins whose residual deviates from the mean (fragmentation signal),
    // smoothly scaled by progress.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + 0.5 * progress);

    // Last-chance bin: smooth bonus when only this bin fits.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many bins, smoothed by progress.
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // New-bin candidate: quadratic penalty unless residual savings justify it.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) * (1.0 - progress);
        // Encourage new bin when no open bin leaves a good fit for the next item.
        if nxt > 0.0 && pr >= nxt {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "usable" classes (multiples of common item denominators) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 12.0,
            5 => 6.0,
            1 | 2 | 3 | 4 => 2.0,
            _ => 0.0,
        };
        score -= class_bonus;
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Penalize large dead space that no future item (min size 1, but typical
    // sizes are chunky) can use: dead space in (0, small threshold) is worst.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Fraction-of-capacity coupling: leftover as fraction of capacity.
    let frac = post_residual as f64 / cap;
    score -= frac * 10.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // Next item fits: leftover after that would be pr - next_item_size.
            let second = pr - next_item_size;
            if second % 10 == 0 {
                score -= 10.0;
            }
            score -= 4.0;
        } else {
            // Next item won't fit here: mild penalty if this bin was "reserved".
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // or the fit into open bins would leave bad residue.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // and mean residual is fragmented.
        let mut new_bin_score = cap * 0.55;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= progress * 8.0;
        new_bin_score -= (open_bins_count as f64).min(20.0) * 0.5;
        if mean_residual < 25.0 {
            new_bin_score -= 10.0;
        }
        // Large items justify fresh bins.
        if item_size >= 50 {
            new_bin_score -= 12.0;
        }
        return new_bin_score;
    }

    // Tight fit reward: item filling most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual below ~10 is nearly unusable
    // (min item size 1, but typical items leave small gaps wasted forever).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Penalize tiny unusable gaps heavily.
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = (bin_residual as f64 - item_size as f64) / bin_residual as f64;
        score -= tightness * 8.0;
    }

    // Pressure from open bin count: discourage opening/keeping too many bins
    // when a good fit exists in an existing bin.
    if bin_residual != bin_capacity {
        // Using an existing bin relieves pressure.
        score -= 2.0 + (open_bins_count as f64) * 0.05;
    } else {
        // Opening a new bin: penalize more when many bins are already open.
        score += (open_bins_count as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: the residual may become dead space; mild penalty.
        score += (next_item_size as f64 - post_residual as f64) * 0.1;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's closer to being closed out — favor filling it now.
    let residual_gap = mean_residual - post_residual as f64;
    score -= residual_gap * 0.05;

    // Stream progression: later in the stream, prefer closing bins tightly
    // over spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * use_ratio;
        } else {
            // next item cannot fit here: penalize leaving a gap that next item almost fits
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 150.0 - 10.0 * gap as f64; // near-miss gap is wasteful
            }
        }
    }

    // Penalize unusable dead space (below minimum item size assumption of 1..100,
    // tiny residuals are still usable, but small residuals relative to capacity are risky).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0);
    } else {
        score += (res - mean_residual) * 0.5;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only chosen when
    // open bins would waste a lot (handled by penalties above).
    if bin_residual == bin_capacity {
        score = 60.0 + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // slight bonus if next item is large too (batch big items)
        }
    }

    // Early in the stream, be more willing to consolidate (favor tight fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0 - post_residual as f64;
    }

    // Penalize dead space scaled by how unusable it is for the next item.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += (post_residual as f64) * 0.5;
        } else {
            score -= 8.0; // leftover still usable for next item
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: open a new bin only when existing fits are bad.
    if bin_residual == bin_capacity {
        let badness = if fitting_bins_count == 0 {
            -200.0
        } else {
            let min_waste = post_residual.min(100) as f64;
            if fitting_bins_count == 1 { 40.0 } else { 25.0 + mean_residual * 0.3 }
        };
        score += badness;
        // Late in stream, prefer consolidating into open bins.
        score += progress * 30.0;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 2.0;
    }

    // Prefer fuller bins in general.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Slight preference for bins with residual close to mean (balance).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit = item_size as f64 / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    score += 12.0 * (pr / cap).powi(3) * (1.0 - progress);
    score -= 9.0 * (pr / cap).powi(2) * progress;
    // reward tight fits with a smooth saturating term
    score -= 18.0 * (1.0 - (pr / cap)) * (fit * (1.0 - fit) * 4.0).sqrt();
    // lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 7.0 * (nx - pr) / cap * (0.5 + 0.5 * progress);
        } else {
            score -= 5.0 * (pr - nx) / cap * (1.0 - progress);
        }
    }
    // last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).ln();
    }
    // penalize deviation from mean residual (keep pool balanced)
    score += 3.0 * ((pr - mean_residual) / cap).abs();
    // discourage opening new bins when many are open but lightly used
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 4.0 * (open_bins_count as f64).ln();
        if pr >= 0.0 && fitting_bins_count > 0 {
            score += 6.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more valuable to preserve.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Quadratic waste penalty: dead space hurts super-linearly.
    score += 40.0 * frac * frac;

    // Modulo-class reward: residuals that are multiples of common size
    // classes (10/20/25/50) are reusable, reward them (subtract).
    let res = post_residual;
    if res > 0 {
        if res % 10 == 0 { score -= 6.0; }
        if res % 20 == 0 { score -= 4.0; }
        if res % 25 == 0 { score -= 3.0; }
        if res == 50 { score -= 5.0; }
        if res == 0 { score -= 25.0; } // perfect fill is best
    } else {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent; if next item is close, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // next item cannot fit here: leftover likely dead space
            score += 8.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item fits poorly everywhere. New bin has bin_residual == capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin.
        score += 55.0;
        // Late in the stream, prefer reusing bins even more.
        score += 25.0 * progress;
        // If many bins are open with slack, opening new is worse.
        score += (open_bins_count as f64).sqrt() * 4.0;
        // But if item is large relative to capacity, a fresh bin is fine.
        score -= 20.0 * (item_size as f64 / cap);
        // If mean residual across open bins is small, opening new bin is
        // more acceptable.
        score -= (mean_residual / cap).min(1.0) * 30.0;
    }

    // Tight-fit bonus: item nearly fills the bin.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1..100 unknown dist; use 10 as soft floor)
    // is pure waste, so punish it super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else {
        // Larger leftovers are more reusable; mild reward proportional to size.
        score -= 0.15 * post_residual as f64;
    }

    // Exact match with lookahead: leaving exactly next_item_size is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If leftover can't fit the lookahead item, penalize slightly (dead space until later).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.5 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Prefer new bin when item fits badly everywhere else.
        let bad_fit = (bin_residual as i32 - item_size as i32) as f64;
        score += 15.0 + bad_fit * 0.1 - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward when next item fits
    // snugly into the post-residual of this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Next item fits here: reward proportional to how snug the fit is.
            let snug = 1.0 - (post - next) / bin_capacity as f64;
            score -= 12.0 * snug + 8.0;
        } else {
            // Next item does NOT fit after this placement: penalize leaving
            // residual that is too small to be useful.
            let gap = (next - post) / bin_capacity as f64;
            score += 10.0 * gap;
        }
        // Dead-space penalty: residual too small for the smallest item (1)
        // is only penalized mildly since sizes go down to 1.
        if post_residual < next_item_size && post_residual > 0 {
            score += 4.0 * (1.0 - post as f64 / next);
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual below mean wastes bin space elsewhere.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post - mean_residual) / mean_residual;
        score += 3.0 * rel.max(-1.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize wasteful placements into nearly-full bins where a better
    // arrangement may exist (mild).
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * fill * fill;

    // Slight preference to consolidate early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * (1.0 - progress);

    // New-bin candidate: baseline penalty so it is chosen only when
    // no open bin scores better.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But if next item is large and current item is small, opening a
        // fresh bin keeps big residual for big items.
        if next_item_size > 0 && (next_item_size as f64) > post + 1.0 && item_size <= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Dead-space penalty for leaving awkward slivers (1..10 units).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 30.0 * chain_quality;
    }
    // If next item would NOT fit in the leftover, mild penalty proportional to leftover.
    else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> consolidate into existing bins.
    let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
    score += 0.35 * crowd;

    // New-bin candidate handling: empty bin gets a base handicap that shrinks
    // late in the stream or when open bins are nearly full on average.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 70.0
            - 30.0 * progress
            - 20.0 * (mean_residual / bin_capacity as f64);
    }

    // Late-stream tightening: prefer closing bins near the end.
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post-residual

    // Smooth polynomial coupling of post-residual with stream progress.
    let poly = x * (1.0 - x) * (1.0 - progress) * 8.0;

    // Penalize leaving residual close to but above typical small item sizes.
    let dead = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        -gap / cap * 0.5
    } else {
        0.0
    };

    // Reward using a bin when it is the only fitting option (avoid new bin).
    let last_chance = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // Slight preference to fill bins tightly relative to mean residual.
    let mean_coupling = -(x - mean_residual / cap) * (x - mean_residual / cap) * 0.3;

    // Mild pressure toward opening new bins late in the stream if residual is large.
    let progress_coupling = x * progress * 1.5;

    let mut score = pr - poly * pr + dead + last_chance + mean_coupling + progress_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> huge reward
    // Class 1: post_residual in [1..10] (near-perfect, tiny dead space)
    // Class 2: post_residual in [11..30] (medium, fits small items)
    // Class 3: post_residual > 30 (large residual, still flexible)
    let pr = post_residual;
    let harmonic_penalty: f64 = if pr == 0 {
        -50.0
    } else if pr <= 10 {
        -10.0 + pr as f64 * 0.5
    } else if pr <= 30 {
        // mod-10 classes: residuals that are multiples of 5 or 10 pair better
        // with typical item sizes
        let m = pr % 10;
        let alignment = if m == 0 { 6.0 } else if m == 5 { 3.0 } else { 0.0 };
        5.0 + (pr as f64) * 0.15 - alignment
    } else {
        // large residual: penalize slightly, but mod-20 harmonics help
        let m = pr % 20;
        let alignment = if m == 0 { 4.0 } else if m == 10 { 2.0 } else { 0.0 };
        12.0 + (pr as f64 - 30.0) * 0.05 - alignment
    };
    score += harmonic_penalty;

    // Lookahead coupling: reward residuals that can host next_item_size exactly or closely
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 25.0; // chain perfect fit
            } else if slack <= 10 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: residual becomes dead space for lookahead
            score += 6.0 + (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it moderately attractive only when
    // current item is large and open bins would be badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_capacity - item_size) as f64).abs();
        let base = 20.0 + item_size as f64 * 0.3;
        // open a new bin when open bins are fragmented and item is large
        score = base + fragmentation * 0.2 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items in fresh bins
        }
        // integer-division threshold: fresh bin guarantees residual class of item_size
        if item_size % 10 == 0 {
            score -= 4.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is closest to mean (balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Small penalty per open bin to discourage hoarding many bins late in stream
    score += (open_bins_count as f64) * 0.01 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 200.0; // hard penalty for creating a dead bin
    } else if post_residual < 20 {
        score += 60.0;  // near-dead zone
    } else if post_residual < 30 {
        score += 25.0;
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // this placement leaves a useful gap; reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
            // extra reward for a snug lookahead fit
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // next item cannot use the leftover: mild penalty scaled by waste
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> consolidate; few open bins
    // -> opening a new bin is relatively cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or item is large;
        // penalized when open-bin count is high (fragmentation risk).
        score += 30.0 + 15.0 * pressure - 0.2 * (item_size as f64);
        // Opening a new bin is good if current bins have little room on average.
        score -= (mean_residual - 50.0).max(0.0) * 0.5;
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= 2.0 * pressure;
    }

    // Mild preference to fill bins tighter than the current mean residual
    // (keeps the fleet of open bins homogeneous and packable).
    score += 0.2 * ((post_residual as f64) - mean_residual).max(0.0);

    // Slight tightening over the stream: later items should pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled non-linearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score = post * post / cap; // quadratic waste penalty

    // 2-step lookahead: strong reward if the NEXT item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // next item fits: reward exact match heavily
            score -= 40.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 60.0; // perfect two-item packing
            }
        } else {
            // next item does NOT fit: penalize leaving a residual smaller than next item
            // (dead space that likely can't be used by the lookahead item)
            score += 12.0 * (1.0 - post / cap);
        }
    }

    // Compare against mean residual: placing into a bin with residual far below mean
    // preserves larger residuals elsewhere; slight reward for using low-residual bins.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-costly so it is
    // chosen only when all open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is fine if next item is large (may pair with item_size)
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score -= 15.0; // new bin can host a perfect pair
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Many open bins: encourage consolidation into fewer bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-exact fits strongly (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powf(8.0);

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover: mild penalty proportional to waste
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer fuller bins relative to global mean residual.
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (late in stream, fewer future items, less value in consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 20.0 * progress;

        // If next item is large, a fresh bin is more attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If only one fitting bin exists, discourage opening a new one.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Mild consolidation pressure: fewer open bins -> keep using them.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    // Time horizon: early on, be picky about poor fits (long future to regret waste);
    // late, accept anything that avoids a new bin.
    let horizon = 1.0 - step_index as f64 / total_items.max(1) as f64;
    score += horizon * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize residuals into [0,1] scale.
    let cap = bin_capacity as f64;
    let post_n = post_residual as f64 / cap;
    let item_n = item_size as f64 / cap;
    let resid_n = bin_residual as f64 / cap;

    // Reward tight fits: smooth quadratic decay of the fit quality.
    let tightness = 1.0 - post_n; // 1.0 when the bin is exactly filled
    score -= 12.0 * tightness * tightness;

    // Non-linear coupling of tightness with stream progress: prefer tight packing
    // increasingly as the stream advances (exploit vs. explore trade-off).
    score -= 8.0 * tightness * tightness * (progress * (1.0 - progress) * 4.0);

    // Penalize large dead space super-linearly (unusable slivers are costly).
    score += 6.0 * post_n * post_n;

    // Penalize opening a new bin when other bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_scale = (open_bins_count as f64).sqrt();
        score += 10.0 + 3.0 * open_scale + 20.0 * (1.0 - progress);
        // If the next item is small enough to fit into residual left here, soften penalty.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Favor bins whose residual is below the mean (consolidate emptier space),
    // with a smooth saturating term.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= 4.0 * mean_gap / (1.0 + mean_gap.abs());

    // Lookahead: if next item fits the post-residual, reward this placement (chain packing).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            let chain = 1.0 - gap / cap;
            score -= 5.0 * chain * chain;
        } else {
            // Slight penalty if the next item cannot follow into this bin.
            score += 2.0 * (-gap / cap);
        }
    }

    // Mild preference for using existing bins over creating new ones as stream progresses.
    score += 2.0 * (1.0 - progress) * (resid_n - item_n).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by large classes are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        60.0
    } else if pr % 25 == 0 {
        25.0
    } else if pr % 10 == 0 {
        15.0
    } else if pr % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 20.0 - 0.4 * slack;
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item won't fit here anyway; mildly penalize wasting space.
        score += 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Penalize very small unusable leftovers (dead space).
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or it's early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 10.0 };
        score += 35.0 + 40.0 * (1.0 - progress) + scarcity;
        if post_residual >= 50 {
            score -= 10.0; // a fresh bin keeps half capacity, decent
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..=100 interface)
    // are "dead" if no plausible future item can use them. Penalize small unusable gaps hard.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_residual as f64 - post_residual as f64).powi(2) * 0.01;

    // Open-bin pressure: prefer using existing bins; the more bins open, the stronger the pull.
    if bin_residual != bin_capacity {
        score -= 5.0 + open_bins_count as f64 * 1.5;
    } else {
        // New-bin candidate: only attractive when nothing fits well.
        score += 8.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    } else if next_item_size > 0 {
        // Next item cannot use this gap: penalize proportional dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Mean residual coupling: bins far below mean residual are "loose" targets; slightly
    // discourage placing into a bin whose residual is much larger than needed.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Progress: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains into this bin: excellent.
            let chain_waste = post_residual - next_item_size;
            score -= 150.0 - (chain_waste as f64) * 1.5;
            // Perfect two-item packing bonus.
            if chain_waste == 0 {
                score -= 250.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap just below next_item_size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 300.0;
    }

    // Prefer bins below mean residual (use up loose space first),
    // penalize eating into bins that are already tight.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + (post_residual <= 20) as i32 as f64 * 60.0;
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // New bin: score = leftover space; add penalty that shrinks with item size
        // and with stream progress (early on, keep bins open; later, consolidate).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * (1.0 - progress) + (item_size as f64) * 0.1;
        // If many bins are open, discourage opening yet another one.
        score += open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is much larger than the item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize large post-residuals that can't fit a typical next item.
    if post_residual > 0 {
        let usable = if (next_item_size as u32) <= post_residual { 1.0 } else { 0.0 };
        score += 8.0 * (1.0 - usable) * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: strongly reward bins whose post-residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    } else {
        // Last item: fill bins as tightly as possible.
        score -= 15.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: open a new bin only when existing fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = item_size as f64 / mean_residual.max(1.0);
        // Early in stream or when mean residual is small relative to item, opening is attractive.
        score = 45.0 + 40.0 * progress - 25.0 * (poor_fit - 1.0).clamp(0.0, 3.0);
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Time-dependent tie-breaker: later in stream, prefer tighter packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;

    // Base: prefer small post residual, normalized
    let mut score = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in stream, waste penalized more strongly (superlinear).
    let progress_coupling = (pr / cap).powi(2) * (0.5 + 2.0 * progress * progress);
    score += progress_coupling;

    // Reward tight fits via smooth sigmoid-like term on fit_ratio
    score -= 1.5 * fit_ratio * fit_ratio * (1.0 - fit_ratio);

    // Lookahead: if next item fits the post residual, reward this bin smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx_fit = nx / (pr / cap + 1e-9);
        score -= 0.8 * nx_fit * (1.0 - nx_fit * nx_fit);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to leftover
        score += 0.4 * nx * (pr / cap);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - progress);
    }

    // Penalize when this bin's residual deviates far below mean residual
    // (keeping bins balanced leaves more usable space overall)
    let dev = (mean_residual - pr) / cap;
    score += 0.3 * dev * dev.abs();

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 0.6 + 0.15 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;

    // ---- Harmonic class logic on post_residual ----
    // Residuals that are multiples of common item sizes (or near-halves/quarters
    // of capacity) are "reusable classes"; odd crumbs are dead space.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 10 == 0 {
        -12.0 // multiple of 10: highly reusable
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 {
        -2.0
    } else {
        15.0 // sub-10 crumb: dead space penalty
    };
    score += class_bonus;

    // ---- Integer-division thresholds on post_residual ----
    // Quarter classes of capacity: residual in [25,50) pairs with mid items,
    // residual in [50,75) is flexible, >=75 is loose.
    let quarter = pr / 25;
    score -= match quarter {
        0 => 0.0,
        1 => 3.0,
        2 => 5.0,
        _ => 7.0,
    } as f64;

    // ---- Lookahead coupling: does next_item_size land exactly in post_residual? ----
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // guaranteed perfect follow-up
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic match classes: gap divisible by 10 or 5 is good
            if gap % 10 == 0 {
                score -= 8.0;
            } else if gap % 5 == 0 {
                score -= 4.0;
            } else if gap < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot follow here; slight penalty proportional to overflow class
            score += 3.0 + ((next_item_size - pr) % 10) as f64 * 0.3;
        }
    }

    // ---- New-bin candidate arbitration ----
    if is_new_bin {
        // Base reluctance to open a new bin.
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If no open bin fits, new bin is mandatory: relieve the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item exactly fills the residual of the new bin
        // (capacity - item), opening fresh is harmonically attractive.
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 10.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly reward using it to avoid a new bin.
        score -= 20.0;
    }

    // ---- Mean residual steering ----
    // If this bin's residual is far below the mean, it's tight; favor it.
    let tightness = mean_residual - post_residual as f64;
    score -= tightness * 0.15;

    // Mild progress-dependent waste pressure: waste matters more early.
    score *= 1.0 + 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..100)
    // are pure waste. Penalize gaps in the "dead zone" (1..=9) very heavily,
    // and mildly penalize gaps that only fit tiny items (10..=19).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 19 {
        score += 12.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: with many bins open, discourage spreading; prefer
    // filling existing bins (new-bin candidate gets residual == capacity,
    // which is large, so adding pressure makes it less attractive when many
    // bins are already open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 3.0 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting an almost-full bin entirely).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement; if post_residual is too small for the next item,
    // the dead-space penalty above already applies.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (tighter bins), pushing toward compacting fills.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate calibration: empty bin gets a fixed handicap so it is
    // only chosen when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strong reward if the next item exactly fills the leftover space.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: big bonus; near match: scaled bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.9;
        }
        // If next item would fit in the post-residual, mild reward for chain packing.
        if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Penalize residuals far above the mean (wasteful bins left open).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tight fit reward: small post-residual is good, but avoid unusable slivers (< next min size).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead-space penalty for tiny unusable slivers
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score = bin_capacity as f64 * 0.5 + pressure
            + (post_residual as f64 - mean_residual).max(0.0) * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening a fresh bin helps a large follow-up item
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual close to 0 gets heavily discounted
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize leaving residuals that are too small to ever be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (-slack / 15.0).exp();
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the bin where waste is minimized relative to others
        score += 2.0 * fitting_bins_count as f64;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            (1.0 - fill).min(1.0) * (progress * 0.5 + 0.5)
        };
        score += 40.0 - 30.0 * desperation;
    }

    // Global state coupling: high mean residual means open bins have room; prefer consolidating
    score += 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, prefer filling existing bins tightly rather than spreading
    score += 20.0 * progress * (1.0 - fill);

    // Mild preference for keeping the number of open bins low early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear shrinkage
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_term * (norm_pr * cap * 0.3);

    // Reward tight fits increasingly with progress
    score -= prog_term * (item_size as f64 / cap) * 10.0;

    // Penalize dead space relative to mean residual
    score += 0.2 * (pr - mean_residual).abs() * (1.0 + prog_term);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * prog_term;
    }

    // Lookahead: penalize if next item fits poorly in post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr as f64 {
            score += 0.5 * (ns - pr) * (1.0 + prog_term);
        } else {
            score -= 0.3 * (pr - ns) * (1.0 - prog_term);
        }
    }

    // Mild penalty for bin proliferation late in stream
    score += 0.05 * open_bins_count as f64 * prog_term;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo buckets.
    // Residuals divisible by 10 (harmonic with capacity C=100) are reusable;
    // odd/prime-ish residuals are likely dead space -> penalize.
    let harmonic = post_residual % 10 == 0;
    let semi_harmonic = post_residual % 5 == 0;
    if harmonic {
        score -= 6.0;
    } else if semi_harmonic {
        score += 1.5;
    } else {
        score += 4.0;
    }

    // Exact fit is always perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny unusable slivers are worse than medium residuals: quadratic penalty
    // on very small post-residuals that are not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chains two perfect placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a new residual: mild reward scaled
            // by how harmonic the resulting residual would be.
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 15.0;
            } else if nr % 5 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize by the gap.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item; avoid
    // opening a new bin if the fit is decent.
    if fitting_bins_count == 1 {
        score -= 25.0;
        // Extra reward if post_residual stays harmonic.
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open a new bin early in the stream (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins fit, opening new is wasteful.
        score += 8.0 * fitting_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Lookahead: if next item is large, fresh bin keeps flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a "tight" way:
    // filling below-average-residual bins keeps a pool of large residuals.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        if dev < 0.0 {
            score -= 0.05 * (-dev);
        } else {
            score += 0.05 * dev;
        }
    }

    // Integer-division threshold: reward placements leaving >= 2 harmonic
    // slots of 10 (post_residual / 10 >= 2).
    if post_residual / 10 >= 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // minimum item size (1..100 unknown distribution -> use item_size itself
    // as a proxy for the smallest relevant future item) are pure waste.
    if post_residual > 0 {
        // Dead space = residual smaller than the current item can never be
        // reused for an item of comparable size.
        if post_residual < item_size {
            score += 25.0 + 0.5 * (item_size - post_residual) as f64;
        }
        // Very tight fits are excellent: reward heavily.
        if post_residual <= 5 {
            score -= 40.0;
        } else if post_residual <= 10 {
            score -= 20.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward.
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: penalize proportional to gap waste.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early consolidation).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // plus a base cost so it only wins when fits are truly bad.
        score += 45.0 + 8.0 * open_bins_count as f64;
        // Early in the stream, opening fresh bins is cheaper (better packing
        // freedom later); late in the stream, squeeze into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (tighter bins get filled first, keeping large residuals flexible).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward if next item fits into post residual
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 - (post_residual - next_item_size) as f64 * 0.3;
    }
    // Penalize if next item cannot fit in post residual (dead space for lookahead)
    else if next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Bonus for tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving small unusable residuals (below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline, slight penalty so open bins are preferred
    // unless the fit is very poor (handled by above terms making open bins worse).
    if bin_residual == bin_capacity {
        score += 12.0;
        // If mean residual across open bins is small, opening fresh may be better
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    }

    // Mild preference to consolidate bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.5;

    // Tie-break: prefer bins with residuals close to mean (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely: reward proportional to how well it fills.
            let chained = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.5 * chained.min(40.0);
        } else {
            // Post-residual becomes dead space the next item cannot use.
            let dead = (post_residual as f64) - (next_item_size as f64) * 0.3;
            score += dead.max(0.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating small unusable slivers relative to mean residual state.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 0.8;
    }

    // Time horizon: early in the stream, be conservative with tight fits
    // (keep flexible space); late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness_bias = progress * 12.0;
    score -= tightness_bias * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Prefer filling bins that already have low residual (consolidate waste).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Many open bins: encourage closing them out (favor existing bins over new).
    if open_bins_count > 3 {
        score -= 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else {
            // Existing bins exist: new bin is costly unless their residuals are huge.
            score += 15.0 + mean_residual * 0.2;
            if post_residual > 60 {
                score -= 10.0; // large item in fresh bin leaves useful space
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: tight fits (small post_residual) rewarded more as stream progresses.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 60.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space quadratically when it can't fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * pr * pr / cap;
        score += 20.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Reward leaving exactly usable space for the lookahead item.
        let gap = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap * gap);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild penalty on new-bin candidate proportional to open bins (encourage filling open bins).
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
        // But late in the stream, opening a fresh bin can be fine if mean residual is small.
        score -= 20.0 * progress * (mean_residual / cap);
    }

    // Polynomial interaction between post_residual and progress.
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual (integer division thresholds) ----
    // Residuals partitioned into harmonic buckets: 0, tiny (1..=5), small (6..=15),
    // medium (16..=35), large (36..=60), huge (>60). Smaller class = better reuse.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit: strongly reward
    } else if pr <= 5 {
        -2.0
    } else if pr <= 15 {
        0.0
    } else if pr <= 35 {
        4.0
    } else if pr <= 60 {
        9.0
    } else {
        14.0
    };
    score += class;

    // Exact divisibility couplings (modulo arithmetic on capacity fractions)
    if pr % 10 == 0 && pr > 0 {
        score -= 1.5; // residual aligned with decimal classes is more reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 1.0;
    }

    // ---- Lookahead: can next item exactly consume the post-residual? ----
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0; // chain fit: this bin becomes perfect next step
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.08; // next item fits too
        } else {
            score += 1.2; // next item cannot use this residual
        }
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 {
        score -= 3.0; // avoid forcing a new bin when only this one fits
    } else if fitting_bins_count > 3 {
        score += 0.5 * (fitting_bins_count as f64 - 3.0).min(3.0);
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: penalize mildly so it's chosen only when no good open bin exists.
        score += 6.0;
        // But if the item is huge (would leave little residual anyway) or nothing
        // else fits well, opening fresh is fine.
        if item_size >= 60 {
            score -= 4.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 2.5; // big pair: fresh bin better than fragmenting
        }
    }

    // ---- Waste normalization against mean residual state ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64 - mean_residual).abs() * 0.03 * (1.0 - progress);

    // Mild pressure to consolidate into few bins late in the stream
    score += open_bins_count as f64 * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // tiny unusable gap: heavy penalty proportional to how "stuck" the space is
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Favor bins whose residual is tightly consumed (tight fit bonus).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let lookahead_waste = if next_item_size > 0 && post_residual < next_item_size { 20.0 } else { 0.0 };
        // Base cost of opening a new bin, reduced when the resulting gap is small
        // or unusable for the next item anyway.
        score += 15.0 + 30.0 * poor_fit - lookahead_waste;
        // With few open bins, opening a bin is cheaper.
        score -= 4.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Slight preference for bins whose residual is close to the item (best-fit flavor).
        score += 0.15 * ((bin_residual - item_size) as f64 - mean_residual).abs();
    }

    // Dead-space that cannot host the next item is extra waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 4.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches next item size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item can't fit here; slight penalty scaled by how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.05 * miss;
    }

    // Perfect chain fit: post_residual == next_item_size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let low_fill = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score += 3.0 + crowded * 0.5 - low_fill * 4.0;
    }

    // Mild pressure toward consolidating into bins with below-average residual.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.02 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize post-placement waste, with a mild convexity push toward
    // leaving either very small or very large usable chunks.
    let mut score = post;

    // Tightness reward: fraction of the bin's residual consumed by this item.
    let fill_ratio = if resid > 0.0 { item / resid } else { 1.0 };
    score -= 0.35 * fill_ratio * resid;

    // Reward near-exact fits (post residual close to zero).
    if post < 5.0 {
        score -= 12.0 + (5.0 - post) * 2.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 unknown,
    // assume >= 10 typical) are likely wasted forever.
    let dead_threshold = 10.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 3.0;
    }

    // Lookahead coupling: if the next item can fit exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_gap = post - nxt;
            score -= 8.0 * (1.0 - chain_gap / cap);
        } else {
            // Next item cannot follow here: slight penalty proportional to overflow.
            score += 0.05 * (nxt - post).min(cap);
        }
    } else {
        // Last item: any bin that fits is fine; prefer the emptiest fit.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * fill_ratio;
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized mildly; more so late in the stream
        // (consolidation phase) and when many bins are already open.
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 3.0 * open_pressure + 10.0 * progress;
        // But if no open bin leaves a workable residual, opening is fine:
        // approximate via mean residual vs item size.
        if mean_residual < item {
            score -= 20.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (good packing).
        let gap = resid - item;
        score -= 0.08 * (cap - gap);
    }

    // Global-state coupling: when mean residual across open bins is large,
    // prefer consuming from existing bins (anti-bin-proliferation).
    score -= 0.03 * mean_residual * (1.0 - progress);

    // Small deterministic tie-breaker scaled by stream position to vary behavior
    // across the horizon without randomness.
    score -= ((step_index as f64 * 0.6180339887) % 1.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild penalty on large residuals; later: stronger,
    // since remaining items have fewer chances to fill large dead space.
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += poly * cap * 0.35;

    // Lookahead: reward bins whose post-residual can host the next item,
    // with a smooth quadratic interaction in progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack * slack) * (2.5 - 1.5 * progress);
        } else {
            // post-residual too small for lookahead: penalize proportionally to shortfall
            let gap = (nxt - pr) / cap;
            score += gap * gap * cap * (0.6 + 1.2 * progress);
        }
    }

    // Last-chance bin: strong smooth reward, decaying with progress
    // (late in the stream, spreading items is less costly).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 - progress * 0.7);
    }

    // Scarcity of fitting bins: smooth crowding term.
    if fitting_bins_count > 0 {
        score -= 1.0 / (fitting_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced fills),
    // weighted by a smooth progress-activated factor.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * (0.2 + 0.6 * progress);

    // New-bin candidate: penalize slightly more as progress grows (prefer filling existing bins late),
    // but allow early opening with a mild bonus.
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * progress - 0.5 * (1.0 - progress);
    }

    // Tight fit reward: quadratic bonus for near-perfect packing.
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (3.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // modulo buckets of the capacity. Small classes are "tight fits" (good),
    // large classes are dead space (bad).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0;
    }

    // Integer-division thresholds on post_residual: leftover space is only
    // "reusable" if a plausible future item (>=1, typically >=10) fits.
    let usable_class = post_residual / 10; // how many 10-sized units remain
    score += (10 - usable_class.min(10)) as f64 * 3.0;

    // Modulo arithmetic: residuals that are exact multiples of common item
    // sizes are more likely to be filled later. Reward divisibility.
    for m in [10u32, 20, 25, 40, 50].iter() {
        if post_residual > 0 && post_residual % m == 0 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this bin becomes a perfect two-item chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            score -= 20.0 - (chain_left as f64) * 0.5;
        } else {
            // Next item cannot follow here; penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Fraction-of-capacity coupling: prefer bins whose post residual is a
    // small fraction of capacity.
    let frac = pr / cap;
    score += frac * frac * 30.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual low) or we are late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64;
        let penalty = if crowded || progress > 0.7 { 60.0 } else { 25.0 };
        score += penalty;
        // A fresh bin wastes capacity equal to (C - item); discourage early.
        score += pr * 0.2;
    } else {
        // Mild preference for using existing bins, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 + progress * 10.0;
    }

    // Prefer filling bins with the smallest residual among ties (best-fit).
    score += (bin_residual as f64) * 0.05;

    // Slight penalty for proliferating bins when many are already open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1..=10
    // under the base regime, but treat anything <= 12 as "dead") are nearly worthless.
    // Penalize them heavily so we prefer either perfect fits or large usable remainders.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fills (post_residual very small but bin was well used).
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) <= 3.0 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already tight relative to capacity (good packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new empty bin has bin_residual == bin_capacity, so this indirectly
    // penalizes the new-bin candidate as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 15.0 + 6.0 * open_bins_count as f64;
        // But if this item is a last-chance fit in exactly one bin, opening a new
        // bin may still be better than wasting that bin's unique residual.
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin before it is "wasted".
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: the leftover is likely dead space.
            score += (post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Mean-residual coupling: if average residual is high, be pickier about waste.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Slight preference early in the stream to consolidate (fewer bins overall).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits after this placement: strong reward scaled by fit tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0) * 0.5;
    }
    // Next item won't fit: penalize wasted residual relative to next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Dead space penalty: tiny post_residual that is nonzero and unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Zero residual (perfect fill) is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Compare against mean residual: prefer bins that end near the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;
    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Too many open bins: discourage keeping many bins alive unless good fit.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }
    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize large dead space nonlinearly, but only if it's truly unusable
    // (smaller than the smallest plausible item ~1, always usable, so scale mildly).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here after placement: slight penalty proportional to gap.
            let gap = next_item_size - post_residual;
            score += 0.08 * gap as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * fill_ratio * 100.0;
    }

    // New-bin candidate handling: opening a bin is attractive when the item is large
    // (would leave tiny residual anyway) or when global residuals are high and fragmented.
    if bin_residual == bin_capacity {
        // Empty bin baseline: prefer it when item is large (good packing start).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(3) * 45.0;
        score -= large_item_bonus;
        // Penalize opening new bins when existing bins are already spacious on average.
        score += 0.6 * mean_residual;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // Many open bins already: discourage proliferation.
        score += 2.5 * open_bins_count as f64;
    } else {
        // Real bin: slight global pressure toward consolidating into low-residual bins.
        let rel_res = bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - rel_res);
        // Favor bins whose residual is below the mean (denser bins get packed first).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Mild time-horizon shaping: late in the stream, urgency to close bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Stream-progress coupling: later in the stream, tighten fits more aggressively
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Reward near-perfect fits smoothly (quadratic dip around x ~ 0)
    score -= 20.0 * (1.0 - x) * (1.0 - x) * progress;

    // Penalize leaving residuals close to the mean residual (redundant slack)
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 8.0 * (1.0 - (nx / pr.max(1.0) as f64));
        } else {
            score += 4.0 * ((nx - pr as f64) / cap);
        }
    }

    // Last-chance bonus: only bin that fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open: encourage consolidation early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with progress-dependent cost
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes (0..=10) are nearly perfect; reward them strongly.
    let small_class = post_residual <= 10;
    if small_class {
        score -= 25.0 + 0.5 * (10 - post_residual) as f64;
    }

    // Dead-space penalty grows superlinearly for mid-range leftovers
    // (11..=30) which are hard to fill later.
    if post_residual > 10 && post_residual <= 30 {
        score += 0.8 * (30 - post_residual) as f64;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual,
    // this is a harmonic pair — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let frac = nxt / pr.max(1.0);
            // reward high fill ratio of the leftover by next item
            score -= 15.0 * frac * frac;
            // modulo harmonic: leftover after next item small?
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize slightly more if this bin
            // would end with awkward leftover
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bins get a baseline cost so we only
    // open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.05 * open_bins_count as f64;
        if post_residual as u32 >= 60 {
            // opening fresh bin for a tiny item wastes capacity
            score += 15.0;
        }
        // early stream: allow new bins more readily
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    let res_frac = bin_residual as f64 / cap;
    score += 10.0 * (res_frac - mean_residual / cap).abs() * (if bin_residual > mean_residual as u32 { 1.0 } else { -1.0 });

    // Integer-division threshold: leftover in (cap/4, cap/2) is worst zone.
    let q = post_residual / 25;
    if q == 1 {
        score += 8.0;
    } else if q == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable future item are pure waste -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 8.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 12.0 - (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize leaving this residual.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize, scaled by open bins count.
        score += 15.0 + open_bins_count as f64 * 4.0;
        // Exception: if no open bin fits well, allow a new bin when mean
        // residual is fragmented (high mean residual but poor fits).
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item need (avoids unbalancing the bin pool).
    score += ((bin_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 6.0;

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * (4.0 + 6.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that is hard to reuse (waste trap)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: reward bins whose leftover can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    } else {
        // last item: strongly prefer fullest packing
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = mean_residual / bin_capacity as f64;
        // open new bin if existing residuals are large (poor fits) and many bins open
        let poor_fit = (mean_residual - item_size as f64).max(0.0);
        score = 25.0 + poor_fit * 0.3 + open_bins_count as f64 * 0.5 - 20.0 * progress * (1.0 - avg_pressure);
        // but if this bin is the only fitter, never open new
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    }

    // Mild bonus for using bins with residual close to mean (balance preservation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late-stream consolidation: prefer filling existing bins harder as stream ends
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * horizon * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: tightness of fit, non-linearly amplified by stream progress
    let mut score = post * (1.0 + 2.5 * progress * progress);

    // Non-linear coupling: squared post-residual scaled by item fraction
    score += 0.9 * post * post / cap * (0.5 + fit_frac);

    // Reward bins whose residual matches the item well (smooth interaction)
    let residual_frac = bin_residual as f64 / cap;
    score -= 20.0 * (1.0 - residual_frac) * fit_frac * (1.0 + progress);

    // Lookahead: penalize if post-residual cannot fit next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 6.0 * (1.0 - post / cap) * (1.0 - next / cap);
        } else {
            score += 4.0 * (next - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when open bins are roomy
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * mean_residual / cap * (1.0 - progress) + 4.0 * progress;
        if fitting_bins_count >= 1 {
            score += 5.0;
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress * (1.0 - fit_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: residues that pair well with
    // typical item sizes (multiples of 10) are worth keeping.
    let r = (post_residual % 10) as f64;
    score += r * 0.6; // non-multiple-of-10 residue => dead space penalty

    // Integer-division thresholds on post_residual: classify leftover space.
    let q = post_residual / 10;
    if q == 0 {
        score += 2.0; // tiny leftover, bin essentially sealed: good
    } else if q <= 2 {
        score -= 1.5; // leftover 10..29 is highly reusable
    } else if q <= 5 {
        score -= 0.5;
    }

    // Capacity-fraction coupling: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 4.0;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 6.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 * (next_item_size as f64 / cap);
        } else {
            score += 1.0; // next item won't fit here: slight penalty
        }
        // Harmonic class match between next item and post residual
        if (post_residual % 10) == (next_item_size % 10) && next_item_size <= post_residual {
            score -= 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: only prefer it when all open bins would leave
    // very large unusable residuals or mean residual is already low.
    if bin_residual == bin_capacity {
        let base = cap * 0.5 + 4.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).max(0.0) * 0.15
        };
        score = base - pressure
            + (open_bins_count as f64) * 0.05
            + (step_index as f64 / total_items.max(1) as f64) * 2.0;
    }

    // Mild global pressure: many open bins -> prefer consolidating.
    score += (open_bins_count as f64) * 0.03;

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave a gap still usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Penalize gaps that are too small for the known next item but still
    // above the absolute minimum — likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: many open bins -> favor filling existing ones,
    // making the new-bin candidate (residual == capacity) less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: penalize proportional to open bins and stream progress,
    // but relax slightly when the item is large and mean residuals are small.
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 3.0
            - if item_size > 60 { 8.0 } else { 0.0 }
            - if mean_residual < 5.0 { 6.0 } else { 0.0 };
    }

    // Coupling: prefer bins whose residual is already below the mean
    // (they are "tighter" than average — good targets to compact).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (bin becomes perfectly "closed" for the next item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step pairing
        } else if diff <= 5.0 {
            score -= 30.0 * (1.0 - diff / 5.0); // near-perfect pairing
        } else {
            // Penalize dead space the next item cannot use
            if post < nxt {
                score += (nxt - post).min(40.0) * 0.8;
            } else {
                score += diff * 0.15;
            }
        }
        // If next item is huge, prefer bins that can also host it later
        if nxt >= 50.0 && post >= nxt {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.3;
    }

    // Relative-to-mean residual coupling: prefer bins whose post_residual
    // sits below the mean (tight packing), avoid spreading waste evenly.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item fits badly everywhere else.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let bad_fit = if next_item_size > 0 {
            waste.min(next_item_size as f64)
        } else {
            waste
        };
        score += 35.0;             // base penalty for opening a new bin
        score += bad_fit * 0.5;    // extra penalty if fresh bin wastes space
        if fitting_bins_count == 0 {
            score -= 100.0;        // no alternative: must open
        }
        // Early in stream, new bins are cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.03;
    score
