pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer tight fits (penalize large residuals mildly less);
    // late stream: penalize wasted residual super-linearly.
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3) * 60.0;
    score += coupling;

    // Smooth reward for near-perfect fits, weighted by progress.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin bonus (smooth sigmoid on fitting_bins_count).
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 15.0 * last_chance;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * fits_next * (1.0 - gap / cap) * (0.5 + progress);
    }

    // Mild penalty for spreading across many bins vs. mean residual.
    score += 0.05 * open_bins_count as f64 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small dead-space classes are valuable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Class bonus: post_residual in {0} perfect, tiny residuals (1..=5) nearly perfect
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (6.0 - pr) * 40.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo-arithmetic harmonic classes: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are reusable "harmonics" — reward them.
    let harmonics: [u32; 4] = [10, 20, 25, 50];
    for h in harmonics {
        if post_residual >= h && post_residual % h == 0 {
            score -= (pr / h as f64) * 12.0; // more divisible => more reusable
        }
    }

    // Penalize residuals that are awkward (prime-ish / odd and small)
    if post_residual > 0 && post_residual < 10 && post_residual % 2 == 1 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // harmonic match: next item divides post residual
            if post_residual % next_item_size == 0 {
                score -= 120.0 + (pr / nxt) * 10.0;
            }
            // waste if next item would leave tiny remainder
            let rem = pr - nxt;
            if rem > 0.0 && rem < 10.0 {
                score -= 40.0; // still fine, near-perfect after next
            } else if rem >= 10.0 {
                score -= rem * 0.5; // mild reward for usable leftover
            }
        }
        // next item larger than residual: penalize bins that will strand space
        else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // last item: prefer perfect fills strongly
        score -= (cap - frac * 0.0) * 0.0;
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty so
    // it only wins when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if current item is large and would leave a harmonic residual anyway
        if item_size % 10 == 0 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packs)
    score += (mean_residual - pr) * 0.4;

    // Slight time decay: early on, be more conservative about opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    // Prefer filling more-open-bins state by tightening choice among open bins
    score += (open_bins_count as f64) * 0.05 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the
    // smallest plausible item (<= 10) are pure waste — punish hard.
    if post_residual < 10 {
        score += 60.0;
    }
    // Residuals too small for the lookahead item are semi-dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0;
    }
    // Reward near-perfect fills (small but still usable leftovers).
    if post_residual > 0 && post_residual <= 25 {
        score -= 12.0;
    }

    // Tight-fit bonus: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.7 {
        score -= 20.0 * (fill_ratio - 0.7);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into
    // existing bins rather than spawning new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // but relax when this bin's residual is unusable anyway.
        score += 30.0 + 8.0 * pressure;
        if post_residual >= 10 && bin_residual - item_size >= next_item_size.max(10) {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight reward scaled by pressure to keep bins closed.
        score -= (0.3 * pressure).min(6.0);
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (below-mean residual bins are more "committed" — fill them first).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Prefer exact match with lookahead: leave room the next item can use.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining: this bin will be closed by next item
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much would remain after it
            let second_residual = post_residual - next_item_size;
            score -= 30.0 * (1.0 - (second_residual as f64) / (bin_capacity as f64));
        } else {
            // next item does NOT fit: penalize leaving a residual that blocks nothing
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.3 * wasted;
        }
    } else {
        // last item: strongly prefer zero post_residual
        score += 5.0 * (post_residual as f64);
    }

    // Relative to mean residual: prefer bins whose post_residual sits near the mean
    // (keeps open bins homogeneous, preserves large gaps in a few bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 2.0 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when lookahead
    // suggests current bins would waste space badly.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 20.0; // discourage opening new bin when an open bin is last chance
        }
    }

    // Mild stream-progression pressure: later in stream, prefer closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear dead-space penalty: small residuals are nearly worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (waste minimization) with superlinear shaping.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * tightness;

    // Last-chance bonus: only bin that fits — avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Lookahead coupling: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap next item can't use.
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when fits are poor and
    // global residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64) / (bin_capacity as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // New bin is attractive when existing residuals are large/fragmented
        // and the item is big; late in stream, prefer reusing bins.
        let new_bin_appeal = 30.0 * fragmentation + 20.0 * poor_fit - 25.0 * progress;
        score += new_bin_appeal.max(-15.0);
        // Cap: never make a fresh bin overwhelmingly attractive.
        score = score.min(55.0);
    }

    // Mild global pressure: many open bins -> discourage spreading items.
    score += 0.6 * open_bins_count as f64 * (mean_residual / (bin_capacity as f64));

    // Time-horizon modulation: early stream, be greedy for tight fits; late,
    // prioritize closing bins (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 8.0 - progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear tight-fit reward: quadratic coupling of post_residual with progress.
    let tight = (pr / cap).powf(2.0 + 2.0 * progress);
    score -= 12.0 * (1.0 - tight);

    // Penalize large residuals relative to mean residual (dead space creation),
    // smoothly scaled by stream progress.
    let dead = (pr - mean_residual).max(0.0) / cap;
    score += 8.0 * dead * dead * (0.5 + progress);

    // Lookahead: if the next item fits into the post-residual, reward this placement;
    // if it nearly fits, penalize slightly (chained fit potential).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 6.0 * (1.0 - (pr - ni) / cap);
        } else {
            let gap = (ni - pr) / cap;
            score += 4.0 * gap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use the only bin that fits, growing over time.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Discourage opening new bins when decent open bins exist, more so late in stream.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 5.0 + 20.0 * progress * openness + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward placements leaving residuals that
    // are likely reusable by common item sizes (small classes modulo 10).
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.6; // prefer residual ending on "round" class

    // Strong reward for near-perfect fits (dead space minimized).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 7.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement is ideal; if the next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is
    // already tight or many bins are open with large mean residual.
    if bin_residual == bin_capacity {
        score += 12.0;
        if mean_residual > 25.0 {
            score -= mean_residual * 0.3;
        }
        if post_residual < 20 {
            score -= 5.0;
        }
    }

    // Progress modulation: early in the stream, be conservative (keep bins
    // balanced); late in the stream, prioritize tight fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.05;

    // Penalize leaving residuals that fall between common item sizes
    // (harmonic gaps: residuals just below multiples of 10 are awkward).
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Small-but-usable residual: mild reward for tight packing.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize spreading across many bins lightly.
    score += (open_bins_count as f64) * 0.15;

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced if current item is large
        // (large items leave big residuals anyway, less dead-space risk).
        let mut open_cost = 12.0;
        if item_size >= 50 {
            open_cost -= 4.0;
        }
        // If next item fits in the post residual of this new bin, opening is good.
        if next_item_size > 0 && next_item_size <= post_residual {
            open_cost -= 10.0;
        }
        score += open_cost;
    } else {
        // Reusing an open bin slightly favored when its residual is below mean
        // (tighter bins get drained first, keeping large residuals flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Lookahead: reward if next item exactly fits post residual.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Early-stream: be a bit more willing to open bins (build diverse residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item size (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Small bonus if next item also fits after this placement
        if next_item_size <= post_residual {
            score -= 8.0;
        }
        // Penalize leaving a residual just below next item (dead space for the lookahead)
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward tight fits (small post_residual) relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize large waste relative to capacity
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: nothing fits elsewhere
        } else {
            // Opening a new bin wastes the residual of existing bins; penalize,
            // but soften late in the stream when future items are unknown/large
            let waste = mean_residual * open_bins_count as f64;
            score += 20.0 + 0.05 * waste - 30.0 * progress;
            if next_item_size > bin_residual {
                score += 10.0; // next item won't fit a fresh 100-cap bin anyway
            }
        }
    }

    // Slight preference for filling bins early in the stream (keep many bins open)
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    } else if post_residual < 25 {
        score += 8.0; // small awkward gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
        }
    }

    // Time horizon: early in the stream, be more selective (open bins freely);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 25.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    } else if open_bins_count <= 2 {
        score += 6.0; // few bins: mild preference to keep filling them
    }

    // New-bin candidate: only attractive when the item is large relative to
    // residual and no bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fit_ratio > 0.8 && fitting_bins_count <= 1 {
            score -= 12.0;
        } else {
            score += 35.0 + 20.0 * (1.0 - fit_ratio);
        }
    }

    // Slight penalty for placing into bins with much larger residuals (waste big space).
    if bin_residual as f64 > item_size as f64 * 2.0 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: raw post residual (tighter fit -> lower score)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills (amplify small post_residuals).
    // Later: tolerate larger residuals slightly since stream is ending.
    let early_weight = (1.0 - progress).powi(2);
    let late_weight = progress.powi(2);
    score -= 30.0 * early_weight * (norm_pr * norm_pr);
    score += 15.0 * late_weight * (norm_pr * norm_pr * norm_pr);

    // Smooth penalty for leaving dead space that no typical item can use:
    // penalize residuals just below the smallest item size region via smooth bump.
    let dead_zone = (norm_pr * (cap / 10.0) - 5.0).powi(2);
    score += 2.0 * (-dead_zone * 0.1).exp() * pr * 0.05;

    // Reward being the only fitting bin (last chance) with smooth decay.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Coupling with mean residual: bins far below mean residual are "loose";
    // prefer bins whose residual is close to the item (post residual small) relative to mean.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score += 10.0 * mean_gap * mean_gap * (1.0 + progress);

    // Lookahead: if next item fits exactly into post residual, reward strongly (smooth).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let match_deg = (pr - next) / cap;
        let match_bump = (-match_deg * match_deg * 4000.0).exp();
        score -= 25.0 * match_bump;
        // Penalize if next item won't fit in post residual and post residual is large
        if next > pr {
            score += 5.0 * (next - pr) / cap * (1.0 - progress);
        }
    }

    // Mild penalty for proliferation of open bins early in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more valuable to fill tightly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Class 0: post_residual == 0 -> perfect fit, reward heavily.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        // Small dead space class (<=10): mild reward.
        score -= 12.0 - (post_residual as f64) * 0.5;
    } else if post_residual <= 20 {
        // Medium class: neutral-to-slight penalty.
        score += 2.0;
    } else {
        // Large dead-space class: penalize quadratically.
        score += (frac * frac) * 20.0;
    }

    // Modulo-10 harmonic: residuals divisible by 10 align with common item
    // sizes (10..80 multiples), making leftovers reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += (post_residual % 10) as f64 * 0.4;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward for near-exact next-item fit (harmonic residue match).
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit in this bin's leftover: slight penalty for
        // creating unusable space relative to lookahead.
        score += (next_item_size as f64 - pr).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the current bin would leave a big, unusable remainder.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if placing here would waste a lot (large item in fresh bin is
        // fine; small item leaving huge residual is bad), reduce penalty.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    // Prefer tighter bins relative to mean residual of open bins.
    score += (mean_residual - pr) * 0.3;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste — penalize quadratically.
    if post_residual < 10 {
        score += (11.0 - post_residual as f64) * 40.0;
    } else if post_residual <= 20 {
        // Small gaps that only fit tiny items: mild penalty.
        score += (20 - post_residual) as f64 * 4.0;
    } else {
        // Larger usable residuals get a small reward relative to tight fits.
        score -= (post_residual as f64 / 100.0) * 3.0;
    }

    // Reward very tight fits (item nearly fills the bin).
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 25.0 * tightness;
    } else if tightness > 0.7 {
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item fits badly everywhere and the next item is large
    // (reserving fresh capacity for it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 60.0 + open_bins_count as f64 * -0.5;
        if next_item_size > 0 {
            // Reserve fresh bin if next item is big and current fit is loose.
            if next_item_size >= 60 && tightness < 0.7 {
                new_bin_score -= 45.0;
            } else if next_item_size >= 40 && tightness < 0.5 {
                new_bin_score -= 20.0;
            }
        }
        // Early in the stream, allow more new bins; later, discourage.
        new_bin_score += progress * 15.0;
        // If mean residual across open bins is high, opening a new bin is wasteful.
        new_bin_score += mean_residual * 0.3;
        score = score.min(new_bin_score) * 0.0 + new_bin_score;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: strongly favor bins where the item fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the NEXT item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain placement
        } else if next_item_size < post_residual {
            // next item fits after placement: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize small post_residuals that become dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than the mean.
    score += 2.0 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer keeping many small open bins consolidated; penalize opening new bins
    // when open bins exist and the fit is reasonable.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 50.0 + 3.0 * open_bins_count as f64;
        // If lookahead item equals full capacity minus current item, opening is fine.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
        // Late in the stream, discourage opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference for tighter bins overall (best-fit bias).
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed (dynamic time horizon).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual dominates, but boost it nonlinearly.
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;
    score += tight_bonus;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no existing bin fits well (large post_residual in every open bin).
    if bin_residual == bin_capacity {
        let spread_penalty = 10.0 + 0.5 * open_bins_count as f64;
        score += spread_penalty;
        // Early in stream, keep bins open and consolidated; late, allow more bins.
        score -= 8.0 * progress;
        // If item is large relative to capacity, a fresh bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 6.0;
    }

    // Lookahead: if next item would fit into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item fits current bin but not after this placement — mild penalty.
            score += 4.0;
        }
        // If next item is large, prefer bins with less residual waste anyway.
        if next_item_size > bin_capacity / 2 {
            score += (post_residual as f64) * 0.05;
        }
    }

    // Prefer bins with below-average residual (keep high-residual bins for future big items).
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (bin_res - mean_residual) / mean_residual;
        score += rel * 5.0;
    }

    // Mild penalty for many open bins: encourage consolidation early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Small tie-breaker on exact residual to prefer fuller bins.
    score += post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), smoothed polynomial
    let mut score = pr;

    // Non-linear coupling: tightness reward scales with stream progress
    // (early on, keep bins flexible; late, pack tightly)
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score -= progress_weight * (cap - pr) * (pr / cap) * 0.8;

    // Penalize post-residuals that are small-but-unusable (dead space zone)
    // smooth bump centered around residual ~ item_size lower bound
    let dead = (norm_pr * (1.0 - norm_pr) * 4.0).powi(2);
    score += dead * (1.0 - progress_weight) * 6.0;

    // Lookahead coupling: if next item fits into post-residual, reward strongly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= fits_next * (1.0 - slack.abs()) * 12.0 * (0.5 + 0.5 * t);
    } else {
        // last item: strongly prefer zero residual
        score += norm_pr * norm_pr * 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Slight preference to fill fuller bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Mean-residual anchoring: prefer bins near the mean residual (keeps diversity)
    score += ((pr - mean_residual) / cap).abs() * 3.0 * (1.0 - t);

    // New-bin candidate: make it attractive only when it's genuinely better
    if bin_residual == bin_capacity {
        score = pr + 5.0 - 15.0 * (1.0 - t) * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "reusable" class (large chunks divisible by common item sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual exactly 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of C/8).
    let band = post_residual / (bin_capacity / 8); // 0..=8
    match band {
        0 => score -= 40.0,                       // tiny dead space, nearly full
        1 => score -= 10.0,                       // 13-25 left: usable for small items
        2 => score -= 15.0,                       // 26-37
        3 => score -= 8.0,                        // 38-50: awkward zone
        4 => score -= 20.0,                       // ~50: half bin left, valuable
        5 => score -= 5.0,
        6 => score -= 10.0,
        7 => score -= 12.0,
        _ => score -= 25.0,                       // nearly empty bin placement is wasteful
    }

    // Modulo arithmetic: residuals divisible by common item sizes (10,20,25,50)
    // are more likely to be filled later -> reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 25 == 0 { score -= 8.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
        // Penalize prime-ish / odd residuals (hard to fill exactly).
        if post_residual % 2 == 1 { score += 4.0; }
        if post_residual % 10 != 0 && post_residual < 10 { score += 6.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward;
    // if next item fits at all, moderate reward; else penalize stranded space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
            // harmonic class match: next item shares class with leftover
            if post_residual % next_item_size.max(1) == 0 { score -= 20.0; }
        } else {
            score += 15.0; // next item can't use this leftover
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave very poor fits and the item is small enough to matter later.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 60.0;
        // If there is exactly one fitting bin, opening is almost never worth it.
        if fitting_bins_count <= 1 {
            score += 400.0;
        } else {
            // If the current item fits snugly into a fresh bin but the fit
            // elsewhere would be terrible, allow opening (reduce penalty).
            let snug = (bin_capacity - item_size) as f64;
            score -= snug * 0.3;
            if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
                score -= 25.0;
            }
        }
        // Early in stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Prefer tighter bins generally (small residual before placement).
    score += (bin_residual as f64) * 0.15;

    // Slight preference for bins with below-average residual (fill emptier bins less).
    score += (mean_residual - pr).clamp(-50.0, 50.0) * 0.3;

    // Mild load balancing across open bins.
    if open_bins_count > 0 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: penalize so it's only chosen when no reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large, a fresh bin wastes little; soften the penalty.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // Late in the stream, opening new bins is less costly.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= progress * 10.0;
        }
    }

    // Lookahead: if the next item would fit into this bin's post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item barely misses, slight penalty for leaving a tempting gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 5.0;
    }

    // Slight nudge toward bins with low mean residual (well-utilized bins).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward if next item fits exactly in the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let nxt_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - nxt_left as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving a large awkward gap
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless post_residual
    // is large (room for future items) and few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score = 55.0 + 30.0 * (1.0 - openness) + 20.0 * progress;
        // Allow new bin when lookahead item is large and would waste an open bin
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 6.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 3.0 * fit_ratio;
    }

    // Penalize leaving awkward small residuals (dead space that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 4.0 + 4.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item could have gone here but we're consuming the space it needs; mild penalty.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: empty bin starts with a handicap that shrinks
    // when open bins are fragmented (high mean residual, many bins) or late in stream.
    if bin_residual == bin_capacity {
        score += 12.0;
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).clamp(0.0, 1.0);
        score -= 14.0 * fragmentation * open_norm * (0.5 + 0.5 * progress);
        // Never open a new bin if a decent fit exists elsewhere
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 10.0;
        }
    }

    // Mild global pressure: prefer filling existing bins as stream progresses.
    score += progress * (post_residual as f64 / bin_capacity as f64) * 2.0;

    // Prefer bins whose residual is close to mean residual (keeps bin sizes balanced)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling: squashed post-residual, weighted by stream progress
    let pr_norm = pr / cap;
    let squash = pr_norm * pr_norm * (3.0 - 2.0 * pr_norm); // smoothstep on residual fraction
    score += 20.0 * squash * (0.5 + progress);

    // Reward tight fits (low post residual) more strongly late in the stream
    score -= 30.0 * (1.0 - squash) * progress;

    // Penalize dead space relative to mean residual across open bins
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // Smooth stream-progress polynomial tilt: early stream slightly favors new bins
    score += 4.0 * progress * progress - 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: capacity fractions / integer division ---
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = (post_residual * 4) / bin_capacity; // 0..3 harmonic quarter classes
    match post_class {
        0 => score -= 12.0,                    // near-perfect fill (post <= 25% cap)
        1 => score -= 4.0,                     // decent fill
        2 => score += 3.0,                     // half-empty bin
        _ => score += 8.0,                     // mostly empty, wasteful placement
    }

    // Modulo arithmetic on post_residual: dead-space "harmonics"
    // Residuals that are multiples of small item sizes (10/20/25) are reusable.
    let reusable = |r: u32| -> bool {
        r == 0 || r % 10 == 0 || r % 25 == 0 || r % 20 == 0
    };
    if reusable(post_residual) {
        score -= 6.0;
    } else if post_residual < 10 && post_residual > 0 {
        // tiny unusable dead space below min item size
        score += 15.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let snug = (next_item_size as f64) / post;
            score -= 10.0 * snug;
            if reusable(post_residual - next_item_size) {
                score -= 5.0;
            }
        } else {
            // next item cannot follow here: penalize more for large next items
            score += 4.0 + (next_item_size as f64) * 0.05;
        }
    } else {
        // last item: just minimize waste
        score = post as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Prefer bins whose residual is close to the mean (keep residuals uniform)
    score += (post - mean_residual).abs() * 0.15;

    // New-bin candidate: default tie-breaker — only attractive when existing bins
    // would leave bad residuals. Give it a mild penalty that tight fits overcome.
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if item is huge relative to capacity and stream is early,
        // a fresh bin is a reasonable hedge
        if item_size * 5 / 4 >= bin_capacity && progress < 0.5 {
            score -= 8.0;
        }
    }

    // Exact fill is always best
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are fine only if zero; small nonzero gaps that nothing can use are heavily penalized.
    if post_residual > 0 {
        // gap too small for any item (items >= 1, but practically penalize tiny gaps)
        if post_residual < 3 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 10 {
            score += 25.0; // nearly unusable dead space
        } else if post_residual <= 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity (fill ratio of the gap consumed)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.6 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a useful way
    // (a bin with small residual relative to mean is well-used; keep filling it)
    if post_residual as f64 > mean_residual {
        score += 3.0; // leaving more than average behind: mild penalty
    } else {
        score -= 3.0;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in the leftover gap, penalize leaving a large gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    // Empty bin has post_residual = capacity - item_size; penalize opening new bins
    // unless the item is large or the stream is early.
    if bin_residual == bin_capacity {
        let early = progress < 0.15;
        let big_item = item_size >= 70;
        if !early && !big_item {
            score += 40.0; // prefer placing into existing open bins
        } else if big_item {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Core: post_residual relative to bin capacity (tight fit reward)
    score = 0.6 * post + 0.4 * (post * post) / cap;

    // 2-step lookahead: reward if next item fits into the post residual exactly
    if next > 0.0 {
        if next <= post {
            // perfect lookahead match: next item fills the bin completely
            let gap = post - next;
            score -= (1.0 - gap / cap) * 30.0;
            // bonus for near-exact match
            if gap <= 2.0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to leftover waste
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer it only when nothing fits well
    if bin_residual == bin_capacity {
        // neutral-ish baseline; make it slightly worse than a decent fit
        score += 12.0;
        if next > 0.0 && next <= post {
            score -= 10.0; // fresh bin can host a long chain
        }
    }

    // Compare against mean residual: bins with residual below mean are more "committed"
    if post < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late in stream: prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.05;

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Penalize dead space relative to smallest useful item (assume ~10).
    score += (post_residual as f64).powf(1.4) * 0.35;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when fit is poor or stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 120.0; // default cost of opening a bin
        if post_residual as f64 > mean_residual * 0.9 {
            score -= 60.0; // item leaves a typical residual; fresh bin fine
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
        // Early in the stream, spreading items is cheaper long-term.
        score -= (1.0 - progress) * 70.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 40.0;
        } else {
            // next item won't fit here; penalize leaving large stranded gaps
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.5;
        }
    }

    // Prefer bins whose residual is already below mean (consolidate small gaps).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Slight preference for fuller bins as stream matures.
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial coupling to stream progress.
    // Early on, prefer tighter fits mildly; later, demand tight fits strongly.
    let base = pr * (1.0 + 1.5 * progress * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Dead-space penalty: residuals too small for any plausible item (min size 1,
    // but small slivers under ~10 are effectively dead) grow super-linearly.
    let dead = if pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.6 } else { 0.0 };

    // Last-chance bonus: if this is the only bin that fits, reward strongly.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -30.0
    } else {
        0.0
    };

    // Lookahead coupling: reward residuals that can also hold the next item,
    // scaled by how much slack remains after a hypothetical second placement.
    let lookahead = if next_item_size > 0 {
        let two = pr - next_item_size as f64;
        if two >= 0.0 { -8.0 * (1.0 - two / cap) } else { 6.0 * (-two / cap) }
    } else {
        0.0
    };

    // New-bin candidate: penalize opening a bin, more so late in the stream
    // and when many bins are already open.
    let new_bin = if bin_residual == bin_capacity {
        12.0 + 10.0 * progress + 0.4 * open_bins_count as f64
    } else {
        0.0
    };

    // Mild preference toward bins whose residual is below the mean residual
    // (keeps large residuals available for large future items).
    let mean_pull = (mean_residual - pr) * 0.05;

    base + dead + last_chance + lookahead + new_bin + mean_pull
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into coarse
    // capacity-fraction buckets. Leftovers in "awkward" classes are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class by eighth-fractions of capacity: 0 = tight fit, 7 = nearly empty bin.
    let class = (pr / (cap / 8.0)) as u32;
    let awkwardness: f64 = match class {
        0 => -6.0,                 // tiny leftover: excellent packing
        1 => -3.0,
        2 => 1.0,                  // ~25% leftover: moderately wasteful
        3 => 4.0,                  // ~37%: classic dead-space trap
        4 => 2.0,                  // half-full leftover is reusable
        5 => 5.0,
        6 => 7.0,
        _ => 0.0,                  // nearly empty bin: neutral (new-bin class)
    };
    score += awkwardness;

    // Integer-division harmonic bonus: residuals that are multiples of common
    // small item sizes (10, 20, 25, 50) remain splittable.
    let harmonics = [(10u32, 3.0f64), (20, 2.5), (25, 2.0), (50, 2.0), (5, 1.0)];
    for &(m, w) in harmonics.iter() {
        if post_residual % m == 0 && post_residual > 0 {
            score -= w;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 4.0 + (nxt_post as f64) / cap * 3.0;
            // Harmonic match on the two-step residual
            if nxt_post % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_ratio = item_size as f64 / cap;
        // Large items pack cleanly into fresh bins; small items waste fresh bins.
        score = 55.0 - fill_ratio * 30.0 + progress * 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can also host the next item
        }
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter existing bins (best-fit tiebreak).
    score += (bin_residual as f64 - pr) * 0.01;

    // Slight pressure toward consolidating many open bins.
    score += open_bins_count as f64 * 0.05;

    // Bins far below the mean residual are worse candidates for medium items.
    if (mean_residual - pr).abs() < 5.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left after placement are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        // Larger gaps remain usable; mild reward scaled by gap size.
        score -= (post_residual as f64) * 0.2;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 && gap_after_next > 0 {
            score -= 20.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement would strand the next item: penalize.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins, opening new is cheaper.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: only attractive when existing residuals are poor or many bins are open.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 || mean_gap > 25.0 {
            score -= 30.0;
        } else {
            score += 20.0 + open_bins_count as f64;
        }
    }

    // Mild stream-progression bias: early on, be flexible; later, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin afterwards (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward if next item fits into the post residual (good lookahead chain)
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize creating dead space that the next item cannot use
    else if next_item_size > 0 {
        score += 40.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Prefer tight fits relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 50.0 * (1.0 - tightness);

    // Deviation from mean residual: prefer bins with residual near/below mean (avoid fragmenting fat bins)
    score += 0.4 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large dead space otherwise)
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if poor_fit {
            score -= 60.0; // open a new bin rather than create unusable dead space
        } else {
            score += 120.0; // keep using open bins when fits are fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual (nonlinear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness.powi(4);

    // Penalize dead space that is too small to be useful later (below min item size 1..100,
    // use a soft threshold around 25% of capacity as "likely unusable" zone).
    let dead = post_residual as f64;
    if dead < 0.25 * bin_capacity as f64 {
        score += 12.0 * (1.0 - dead / (0.25 * bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // If multiple bins fit, mildly prefer bins with smaller residual (best-fit bias).
    if fitting_bins_count > 1 {
        score += 0.05 * bin_residual as f64;
    }

    // Lookahead: if the next item could fit exactly into the post_residual,
    // reward heavily; if next item cannot fit post_residual but the bin is a poor
    // fit anyway, slight penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let leftover = post_residual as f64 - nx;
            score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // If next item fits this bin better than current item, encourage reserving:
        // penalize consuming space the next item needs.
        if nx > post_residual as f64 && nx <= bin_residual as f64 && item_size as f64 > bin_residual as f64 - nx {
            score += 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins (penalize opening new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.35 * crowd * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets a base cost that shrinks when
    // no good existing option exists (high mean residual usage, few fitting bins).
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 60.0; // no open bin fits -> must open
        } else if fitting_bins_count == 1 {
            new_bin_cost -= 15.0; // weak alternative exists
        }
        // Late in the stream, opening fresh bins is less costly (no future to waste).
        new_bin_cost *= 1.0 - 0.4 * progress;
        score = new_bin_cost + 0.1 * item_size as f64;
    }

    // Mild preference for keeping mean residual balanced: avoid bins far from mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let mean_fill = 1.0 - mean_residual / cap;

    // Base: quadratic penalty on wasted residual, scaled by stream progress
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling: reward high fill more strongly as stream progresses
    let fill_coupling = fill * fill * (0.5 + progress);
    score -= 30.0 * fill_coupling;

    // Coupling with mean residual: prefer bins deviating below mean fill (tighter bins)
    let dev = fill - mean_fill;
    score -= 8.0 * dev * (1.0 - dev * dev).abs();

    // Lookahead: penalize leaving residual that neither fits next item nor is near zero
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let waste = if fits_next > 0.5 { 0.0 } else { pr };
        score += 0.6 * waste;
        // Smooth bonus when post residual is close to next item size
        let gap = (pr - nxt).abs();
        score -= 6.0 * (-gap / 10.0) * fits_next;
    } else {
        // Last item: strongly reward tightest fit
        score -= 40.0 * fill * fill;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / cap;
    score -= 12.0 * (1.0 - tight) * (1.0 - tight) * (item_size as f64) / cap;

    // Harmonic class of post_residual: residues divisible by common item
    // granularities (10/20/25/50) are more reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        25.0
    } else if pr % 50 == 0 {
        18.0
    } else if pr % 25 == 0 {
        12.0
    } else if pr % 20 == 0 {
        10.0
    } else if pr % 10 == 0 {
        8.0
    } else if pr % 5 == 0 {
        4.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 0.15 * (pr as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_spread = (mean_residual - (bin_residual - item_size) as f64).abs();
        let new_bin_cost = 55.0
            + 0.4 * open_bins_count as f64
            + 30.0 * progress
            - 25.0 * (item_size as f64) / cap
            + 0.1 * poor_spread;
        score += new_bin_cost;
    }

    // Mild penalty for wasting space in a nearly-full bin when other bins fit.
    if fitting_bins_count > 2 && post_residual > 40 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 25.0 + (10 - post_residual as i32).max(0) as f64 * 4.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap remains useful for the next item
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones,
    // especially when few bins fit the item (last chance).
    if bin_residual != bin_capacity {
        score -= 6.0;
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // More open bins => stronger pressure to use them.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    } else {
        // New-bin candidate: penalize so it only wins when open bins are bad.
        score += 14.0;
        // Allow new bin late in the stream when many bins are open and mean residual is low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 0.5 && progress > 0.5 {
            score -= 18.0;
        }
    }

    // Mild preference for bins with residuals close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: exact 2-step lookahead match — post_residual exactly fits next item
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual as u32 > next_item_size {
            // next item still fits after this placement: mild reward proportional to closeness
            let gap = (post_residual as u32 - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use leftover: penalize dead space
            let dead = next_item_size - post_residual as u32;
            score += dead as f64 * 0.5;
        }
    }

    // Reward tight fits relative to capacity
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;

    // Penalize residuals far below the mean residual (creating unusable slivers)
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.3;
    } else {
        score -= (post_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // New empty bin candidate: penalize unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize bins that become nearly-empty-but-unusable dead space
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to prefer keeping flexibility (best-fit still wins via base)
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would exactly fill the remainder, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in the remainder, penalize creating stranded space
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 && progress < 0.5 {
        score += 3.0 * (1.0 - progress);
    }

    // Prefer bins with residual above the mean (keeps mean residual spread balanced)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New empty bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0; // default penalty for opening new bin
        // Allow new bin when current bin would leave a large awkward gap
        if post_residual > 0 && post_residual < 10 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): favor tight fits strongly (post_residual penalty amplified).
    // Later (progress ~ 1): relax slightly since residual space matters less over remaining stream.
    let tightness = (pr / cap).powi(2);
    let coupling = tightness * (1.0 + 2.0 * (1.0 - progress) * (1.0 - progress));
    score += 6.0 * coupling;

    // Reward filling a bin to near-capacity with smooth saturating term.
    let fill = 1.0 - pr / cap;
    score -= 4.0 * fill * fill * fill;

    // Penalize when this bin is the only fitting bin (last chance) but the fit is poor.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - tightness);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let match_quality = 1.0 - ((pr - nxt) / cap).powi(2);
            score -= 3.0 * match_quality.max(0.0);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover dead space.
            score += 1.5 * tightness;
        }
    }

    // Smooth deviation from mean residual: prefer bins whose residual deviates smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // Mild preference to spread across bins when many open bins exist.
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large usable" classes are favored; tiny dead-space classes are penalized.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongest reward.
        score -= 1000.0;
    } else if pr <= 5 {
        // Near-dead space: slightly favored over moderate waste (small leftover
        // is nearly a perfect fit for future small items).
        score -= 40.0;
    } else if pr <= 20 {
        // Small-but-usable class.
        score -= 10.0;
    } else if pr <= 50 {
        // Mid class: neutral-ish, small bonus scaled by class parity.
        score -= if pr % 10 < 5 { 4.0 } else { 2.0 };
    } else {
        // Large leftover: fine, but slightly worse than tight packing.
        score -= 0.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or closely (harmonic pairing of consecutive items).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 60.0;
            } else if slack <= 30 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // the leftover is "wasted" relative to the lookahead.
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += 20.0;
            } else if gap <= 30 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 30 {
            score -= 150.0;
        } else {
            score -= 50.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly so good fits win,
    // but not so much that horrible fits are preferred.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in the stream, opening bins is cheaper (more items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 60.0 * (1.0 - progress);
    }

    // Prefer packing into bins whose residual is already below the stream mean
    // (consolidates space, keeps large-residual bins available for big items).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f).min(40.0) * 0.5;
    } else {
        score += (res_f - mean_residual).min(40.0) * 0.25;
    }

    // Slight preference for fewer open bins (reduce fragmentation).
    score += open_bins_count as f64 * 0.3;

    // Modulo-class tiebreak on post_residual: leftover divisible by common
    // item-size classes (multiples of 10) pairs better with typical items.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items (1..=10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range unusable gaps (too small for medium items) get a soft penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (post residual near zero but not creating a tiny gap).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual >= 20 && post_residual <= 40 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits the post residual, this placement
    // chains nicely; reward it. If it nearly fits, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual + 5 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; favor consolidation and new-bin avoidance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Prefer bins whose residual is already below average (consolidate
    // fragmented bins), mildly.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate calibration: an empty bin has zero dead-space risk
    // but incurs the open-bin pressure cost; ensure it loses against
    // reasonable fits but wins against terrible fits (already handled by
    // the dead-space penalties above).
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
        } else {
            // post_residual too small for next item: penalize dead space unless near zero
            score += 0.5 * (post_residual as f64);
        }
    }

    // Penalize bins whose residual is far from mean (fragmentation control)
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 60.0 + 120.0 * poor_fit + 0.5 * (open_bins_count as f64);
    }

    // Early in stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good (already base), amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward leaving room for the next item if it would fit nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Perfect chain: next item fills bin exactly or leaves small remainder.
            if gap < 10 {
                score -= 15.0;
            } else {
                score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global pressure: many open bins relative to progress -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.3 * pressure;

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin; prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin gets a moderate default penalty,
    // overcome only when no open bin fits well (post_residual small).
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if item is large and lookahead is large, opening fresh may be wise.
        if item_size > 60 && next_item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.9 * progress * progress + 0.6 * fit * fit);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (cap - pr) * (0.15 + 0.35 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic term)
    score += 0.4 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item (smooth)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 0.5 * ns * (1.0 - gap / cap).max(0.0);
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (mod-10 classes) ---
    let pr = post_residual as i64;
    let class = pr % 10;
    // Dead-space penalty: residuals that no item (1..=100) can pair usefully
    // with are penalized. Small nonzero residuals (1..=9) are near-dead.
    if pr > 0 && pr < 10 {
        score += 60.0 - (pr as f64) * 2.0; // tiny slivers are terrible
    }
    // Perfect fit bonus: harmonic class 0 (residual divisible by 10)
    if class == 0 && pr >= 0 {
        score -= 25.0;
    }
    // Class 5 residuals are semi-useful (many items leave/take 5s)
    if class == 5 {
        score -= 10.0;
    }
    // Odd small classes are less reusable than even ones
    if class % 2 == 1 && pr > 0 {
        score += 6.0;
    }

    // --- Integer-division thresholds: can next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: strong reward, scaled by tightness of fit
            let waste_after_next = post_residual - next_item_size;
            score -= 30.0 + (waste_after_next as f64).min(20.0);
        } else {
            // next item won't fit here; residual becomes dead space for lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Harmonic pairing: next_item_size and post_residual share a divisor class
        let g = gcd(post_residual, next_item_size);
        if g > 1 {
            score -= (g as f64).min(10.0) * 1.5;
        }
    } else {
        // last item: only the exact fill matters
        score -= 40.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0; // avoid opening a new bin if this is the only fit
    }
    if fitting_bins_count > 3 {
        score += 4.0; // many alternatives: be pickier
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early, or when existing residuals are bad fits.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_gap = (mean_residual - item_size as f64).abs();
        score = 45.0 + 30.0 * progress + mean_gap * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
        if fitting_bins_count == 1 {
            score += 50.0; // don't open new bin when a sole bin fits
        }
        return score;
    }

    // --- Tightness coupling: reward filling a large fraction of residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 22.0;

    // Mild pressure toward consolidating open bins
    score += (open_bins_count as f64).sqrt() * 0.8;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (min item size 1..100, but practically small gaps < 10)
    // are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that can still accommodate typical future items.
    if post_residual >= 50 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, especially when
    // open-bin pressure is low; relax penalty late in the stream or when
    // many bins are open (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 55.0 + 15.0 * pressure - 20.0 * progress;
        // If the next item would perfectly fill the leftover of this new bin
        // after placing the current item, soften the penalty.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Lookahead: if this bin's post residual exactly fits the next item,
    // reward the placement (chains items tightly).
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 12.0; // awkward gap just above next item size
    }

    // Mild open-bin pressure: prefer fewer open bins by favoring existing bins.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    // Prefer bins tighter than average (good fits concentrate residual usage).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward even more
    // when the leftover exactly accommodates the next item (2-step lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = post - next;
        if diff >= 0.0 {
            // Perfect chain: this bin's leftover exactly fits the next item.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            // Exact match is gold.
            if diff == 0.0 {
                score -= 25.0;
            }
        } else {
            // Leftover too small for next item: mild penalty proportional to waste.
            score += 0.5 * (-diff);
        }
    } else {
        // Last item: simply minimize residual, small bonus for tightness.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already "tight"; placing here is efficient. Bins far above mean
    // should absorb the item instead of wasting tight bins.
    let post_f = post_residual as f64;
    let mean_gap = post_f - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly by default...
        score += 20.0;
        // ...but large items justify fresh bins more readily.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 35.0 * size_frac;
        // If several bins fit, definitely prefer reusing one.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Late in the stream, consolidate: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny sliver is worthless
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining is golden.
            if post_residual == next_item_size {
                score -= 15.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Penalize leaving a gap the next item cannot use, scaled by waste.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
        }
    }

    // Global state coupling: when mean residual across open bins is large,
    // we should consolidate into existing bins rather than spreading out.
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score += 6.0 * mean_res_norm;

    // Penalize opening a new bin when many bins are already open and underused.
    if bin_residual == bin_capacity {
        let open_norm = open_bins_count as f64;
        let pressure = open_norm / (open_norm + 3.0);
        score += 10.0 * pressure + 3.0 * mean_res_norm;
        // Early in the stream, opening bins is cheap; later it is costly.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * t;
        // But if the item is huge and mean residual can't hold it, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 6.0;
        }
    }

    // Time-horizon modulation: as the stream nears its end, avoid leaving
    // fragmented residuals; prefer placements that nearly close a bin.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if t > 0.8 && post_residual == 0 {
        score -= 10.0; // perfectly closed bin near the end
    }

    // Mild penalty for very loose fits relative to item size.
    let looseness = post_residual as f64 / (item_size.max(1) as f64);
    score += 2.0 * looseness.min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3);
    score -= 30.0 * coupling;

    // Penalize small-but-nonzero dead space quadratically
    if pr > 0.0 {
        let dead = norm_pr * (1.0 - norm_pr);
        score += 20.0 * dead * (0.5 + progress);
    }

    // Perfect fit reward, stronger late in the stream
    if pr == 0 {
        score -= 40.0 * (1.0 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (1.0 - ni / cap) * (1.0 + p2);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Crowd-out pressure when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Mean residual alignment term
    score += 3.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no plausible item can fill.
    // Items are integers in 1..=100; a residual below ~10 is nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Strongly penalize leaving a gap that is smaller than the next item,
    // but only if that gap is also small enough to be hard to reuse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Reward exact/near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; the emptier the bin relative to others, the more it should
    // be penalized unless it closes nicely.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer
    // reusing open bins with good fits, but kept attractive when all open bins
    // would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 4.0;
        // Opening a new bin is more attractive early when few bins are open.
        score -= open_bins_count as f64 * 0.3;
    }

    // Slight preference for keeping mean residual balanced: avoid bins far
    // below the mean residual (wasting capacity unevenly).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leftover space is unusable dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward post_residual matching next_item_size
    // so the next item can fill this bin exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 40.0 - gap.min(40.0); // best when gap == 0, decays to 0
        if gap == 0.0 {
            score -= 120.0; // exact 2-step chain fit
        }
    }

    // Penalize small unfillable residuals (< minimum plausible item size),
    // scaled by how early we are in the stream (waste matters more early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.5 - progress) * 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing bins offer a poor fit (large post_residual or lookahead mismatch).
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            1.0
        };
        score += 25.0 - poor_fit * 20.0;
        // More open bins already -> slightly favor consolidation into them.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward bins tighter than the mean residual (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Mild preference for filling larger-capacity chunks early.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- New-bin candidate detection ---
    let is_new_bin = bin_residual == bin_capacity;

    // Progress ratio (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Lookahead coupling: does the next item fit in the leftover space? ---
    let next_fits_here = next_item_size > 0 && (next_item_size as f64) <= post_residual as f64;
    let next_fits_tight = next_item_size > 0
        && (next_item_size as f64) <= post_residual as f64
        && (post_residual as f64 - next_item_size as f64) <= 10.0;

    if next_fits_tight {
        // Excellent chain potential: strongly reward
        score -= 25.0 * (1.0 - progress * 0.5);
    } else if next_fits_here {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
        // Dead space relative to the known next item: penalize proportionally
        let waste = next_item_size as f64 - post_residual as f64;
        score += waste * 0.6;
    }

    // --- Perfect / near-perfect fit reward ---
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // --- Penalize fragmenting large residuals into tiny unusable slivers ---
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // --- Global state coupling ---
    // Many open bins with high mean residual: prefer reusing existing space
    let global_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if !is_new_bin {
        score -= global_pressure * 1.5;
    } else {
        // Opening a new bin when existing residual capacity is plentiful is wasteful
        score += global_pressure * 2.0;
    }

    // --- New-bin candidate logic ---
    if is_new_bin {
        // Base penalty so a new bin is only chosen when fits are poor
        score += 30.0;
        // If the next item chains perfectly into a fresh bin, ease the penalty
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= (item_size as f64) {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        score -= (1.0 - progress) * 10.0;
        // Late in the stream, squeeze existing bins harder
        score += progress * 15.0;
    }

    // --- Mild tie-breaker favoring fuller bins ---
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Non-linear penalty on tiny residuals that grows with progress
    score += 40.0 * t * (1.0 - x).powi(6) * x.powi(2);

    // Reward tight fits smoothly
    score -= 25.0 * (1.0 - t) * (1.0 - x).powi(3);

    // Lookahead: favor bins whose post residual matches next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        score -= 15.0 * (-8.0 * (x - nx).abs()).exp();
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * t);
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln() * 3.0 * t;

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += 0.3 * (pr as f64 - mean_residual).abs() * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10, and small residues) are more reusable.
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0; // perfectly aligned leftover
    } else if r <= 2 {
        score += 4.0; // nearly-dead sliver
    } else if r >= 8 {
        score -= 2.0; // close to next decade boundary
    }

    // Integer-division thresholds: post_residual buckets by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 12.0; // unusable dead space
    } else if frac < 0.3 {
        score += 3.0;
    } else if frac >= 0.5 && frac < 0.7 {
        score -= 4.0; // sweet spot: half-full leftover
    }

    // Harmonic coupling with next item (lookahead, k=2).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0; // next item would land on a harmonic boundary
            } else {
                score -= 3.0;
            }
            if gap == 0 {
                score -= 6.0; // perfect fit for the follower
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: opening fresh is only attractive when residuals are
    // fragmented and this bin would leave a bad harmonic class anyway.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 25.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are worthless.
    let min_item = 1u32; // sizes 1..100, but treat tiny gaps as dead
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward gaps that still fit the known next item (lookahead synergy)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap wasted relative to lookahead
        score += 8.0;
    }

    // Tightness reward: fraction of residual consumed
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new bin candidate: penalize more when many bins already open or mean residual is high
        score += 15.0 + 4.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // but if no open bin fits well, new bin may be attractive: handled by fitting count
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // last chance: strongly favor using this bin
        score -= 30.0;
    }

    // Mild pressure to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - progress);

    // Prefer bins whose residual is below average (filling emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: reward residuals that match the next item well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits here later: strong reward for tight match
            score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit: penalize leftover dead space relative to mean residual
            score += 8.0 + (post_residual as f64 - mean_residual).abs();
        }
        // perfect pairing bonus: residual equals next item exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // last item: minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 20.0; // fresh bin pairs perfectly with next item
        }
        // discourage opening new bins when existing residuals are usable
        score += 15.0 * (avg_waste / bin_capacity as f64);
        if open_bins_count > 0 {
            score += 10.0 * progress;
        }
    }

    // Prefer filling tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for many open bins being consolidated
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual nonlinearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score += 5.0 * (1.0 - next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasted residual below next item size.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.2 * waste;
        }
    }

    // Prefer bins already below mean residual (consolidate small leftovers).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Late in the stream, be more conservative: favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate: penalize opening a new bin, more so if decent fits exist
    // or we are late in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Still allow new bin early if mean residual is high (fragmented state).
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, larger post_residual is acceptable; later, penalize leftover space more.
    let progress_coupling = post_norm * (0.5 + 2.0 * progress * progress);
    score += 30.0 * progress_coupling;

    // Quadratic dead-space penalty: small post_residuals are fine, mid-range residuals are wasteful.
    let waste = post_norm * (1.0 - post_norm);
    score -= 25.0 * waste;

    // Reward tight fits (post_residual near zero) more strongly as the stream progresses.
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 20.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if the next item fits exactly in the post residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 15.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * miss;
        }
    }

    // Slight preference for bins whose residual is below the mean (denser bins), scaled by progress.
    let mean_dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * mean_dev * (0.5 + progress);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 4 classes.
    let cap_f = bin_capacity as f64;
    let q = post_residual * 4 / bin_capacity; // 0..=3 harmonic class of post residual
    match q {
        0 => score -= 12.0, // tiny dead space, near-perfect fit -> strongly reward
        1 => score -= 3.0,  // quarter leftover, still usable
        2 => score += 0.0,
        _ => score += 4.0,  // large leftover, wasteful use of this bin
    }

    // Compatibility: can next item fit into post_residual? (lookahead pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: reward, more if exact harmonic match
            score -= 6.0;
            if next_item_size == post_residual {
                score -= 15.0; // perfect chain
            } else if post_residual - next_item_size <= bin_capacity / 8 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize leaving a stranded gap
            score += 5.0;
            if post_residual < 10 {
                score += 3.0; // small stranded gap is worst
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // or mean residual is already fragmented.
    if bin_residual == bin_capacity {
        // baseline: fresh bin has full capacity; make it competitive but
        // discourage opening when a decent fit exists.
        score = cap_f * 0.35;
        if post_residual as f64 > mean_residual {
            score -= 2.0;
        }
        if fitting_bins_count <= 1 {
            score -= 8.0; // no good alternative -> open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0; // big next item wants fresh capacity
        }
    }

    // Fragmentation pressure: penalize bins whose residual deviates badly
    // from the mean (keeps residuals homogeneous for future packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream, prefer tighter fits (less room to fix mistakes).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    // Many open bins: discourage spreading, prefer filling existing ones.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it's too small to fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 4.0; // up to +60 penalty
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; small gap becomes even more dead
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is acceptable if current bin would leave a dead gap
        if post_residual > 0 && post_residual < 15 {
            score -= 40.0;
        }
    } else {
        // Slight preference for tighter bins among open candidates
        score += (bin_residual as f64 / bin_capacity as f64) * 3.0;
    }

    // Late in stream, be more conservative with new bins (fewer future items to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 20.0 * progress;
    }

    // Prefer bins below mean residual (tighter than average).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits, but leaves slack: mild reward proportional to tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.5 * slack;
    } else if next_item_size > 0 {
        // Next item won't fit in this bin after placement: penalize dead space creation.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.6 * dead;
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness);

    // Penalize bins whose residual deviates strongly below the mean (likely to become dead space).
    if (bin_residual as f64) < mean_residual {
        score += 0.4 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin early in the stream unless no good fit exists;
    // new-bin candidate gets a slight handicap that shrinks as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for filling more-opened bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * next_item_size as f64;
    }
    // Reward leaving exactly enough room for the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Discourage opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count.max(1) as f64).recip();
        score += 8.0 * pressure + 0.1 * open_bins_count as f64;
        // Early in the stream, prefer opening bins to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (prefer balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, be more greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;
    let x2 = x * x;
    let x3 = x2 * x;

    // Base: post-residual, non-linearly shaped by stream progress.
    // Early on, prefer tight fits (low post_residual); late, keep bins flexible.
    let mut score = pr * (1.0 + 0.6 * progress * x2) - 8.0 * (1.0 - progress) * (1.0 - x) * (1.0 - x);

    // Smooth polynomial coupling: penalize mid-range dead space quadratically.
    score += 6.0 * (x - 0.5) * (x - 0.5) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild congestion-aware discount scaled by how many alternatives exist.
        score -= 2.0 / (fitting_bins_count as f64).powf(0.5);
    }

    // Lookahead: reward leaving room for the next item; penalize if it won't fit.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 5.0 * (nx - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress);
        }
    }

    // Mean-residual alignment: prefer bins near the mean (keeps bin sizes balanced).
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    // Slight preference for reusing open bins over opening new ones.
    score -= 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by integer division
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..=4

    // Reward tight fits: post_residual in [0, quarter) is excellent
    match post_class {
        0 => score -= 30.0,
        1 => score -= 8.0,
        2 => score -= 2.0,
        3 => score += 6.0,
        _ => score += 12.0, // near-empty bin barely used -> wasteful
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmony: residuals divisible by 10 pair well with item sizes 1..100
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= quarter {
                score -= 12.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // next item won't fit here; penalize more if this bin becomes dead space
            if post_residual < 10 {
                score -= 4.0; // tiny dead space is fine
            } else {
                score += post_residual as f64 * 0.1;
            }
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to typical residuals and few bins fit it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64)
            * (1.0 + (mean_residual / bin_capacity as f64));
        score = 40.0 + 30.0 * progress - 35.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference for fuller bins overall
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that can fit the next item (lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin bonus: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: penalize using bins when many are open,
    // but only mildly so tight fits still win
    score += open_bins_count as f64 * 0.5;

    // New bin candidate: slightly discourage unless current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Progress-based tightening: later in stream, be stricter about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Prefer filling bins below mean residual (balancing)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly/tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.5; // next item fits: tighter is better
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3; // next item won't fit here: penalize
        }
    } else {
        // Last item: prefer minimizing post residual hard.
        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that can fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< min item size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early stream: be more selective, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // Prefer filling nearly-full bins to consolidate.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual already does this),
    // but add a superlinear penalty for large wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste * waste;

    // Reward using bins that are hard to fill further (small residual relative to item).
    if bin_residual < bin_capacity {
        let snug = 1.0 - (post_residual as f64 / bin_residual as f64).max(0.0);
        score -= 25.0 * snug;
    }

    // Lookahead: if the next item could exactly fill this bin's post-residual,
    // strongly favor this bin (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to how well it pairs
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open and their mean residual is large (plenty of slack available).
    if bin_residual == bin_capacity {
        score += 30.0;
        score += 2.0 * (open_bins_count as f64).sqrt();
        score += (mean_residual / bin_capacity as f64) * 40.0;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If no existing bin fits well, new bin is less bad.
        if post_residual == 0 { score -= 20.0; }
    }

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Mild preference for fuller bins among open ones.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: late in the stream, tighten more
    let prog_coupling = 20.0 * progress * (norm_pr * (1.0 - norm_pr));
    score += prog_coupling * pr / cap;

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (pr - mean_residual) / cap;
    score += 5.0 * dead * dead;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic gap term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.3 * gap * gap / cap;
    } else {
        // Last item: heavily favor minimal post-residual
        score += 0.5 * pr;
    }

    // Mild penalty for bin proliferation early on
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in [0,10] -> tiny dead space, strongly favored.
    if post_residual <= 10 {
        score -= 40.0;
    }
    // Class B: post_residual in (10, 25] -> acceptable leftover, mild reward.
    else if post_residual <= 25 {
        score -= 15.0;
    }
    // Class C: post_residual in (25, 50] -> half-full leftover, mild penalty.
    else if post_residual <= 50 {
        score += 10.0;
    }
    // Class D: post_residual > 50 -> large leftover, penalize (wasteful placement).
    else {
        score += 25.0;
    }

    // Modulo-10 harmonic class: leftovers divisible by 10 pair better with
    // common item sizes (multiples of 10), reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Odd leftover classes are harder to fill later.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 4.0;
    }

    // Integer-division threshold: leftover >= 20 can host a small item (>=10).
    if post_residual >= 20 {
        score -= 8.0;
    } else if post_residual > 0 {
        score += 6.0; // dead space below minimum item size
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 - (chain_waste as f64) * 0.5;
        } else {
            // Next item cannot use this bin's leftover; penalize large leftovers more.
            score += (pr - (next_item_size as f64)).abs() * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless all open
    // bins would leave bad leftovers. Give the fresh bin a mild penalty so it is
    // only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If stream is early, allow new bins more freely (spread items).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 25.0;
        // If many bins are open and mean residual is low, opening new bin is fine.
        if (mean_residual / cap) < 0.15 && open_bins_count > 4 {
            score -= 20.0;
        }
    }

    // Slight preference to fill fuller bins (smaller residual) among equals.
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: prefer bins close to the mean residual (balance).
    score += (mean_residual - pr).abs() * 0.1;

    // Mild progression pressure: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10) are almost unusable
    // given typical item sizes; penalize them heavily with a non-linear bump.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 6.0; // steep penalty for tiny dead gaps
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: strong reward
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward; if post residual is smaller than next item but nonzero, dead space
    // is confirmed, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 5.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but relax as the stream progresses (committing to open bins is fine later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - progress);

    // New-bin candidate: only attractive when open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; the dead-space penalties above on open bins will
        // naturally beat it when fits are poor.
        score += 3.0;
        // If mean residual across open bins is small (bins are nearly full),
        // opening a new bin is reasonable.
        score -= (mean_residual / 20.0).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead matches (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize dead space relative to next item
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
        // coupling with mean residual: prefer bins whose post_residual diverges usefully
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        // last item: minimize post residual directly (already done), small tightness bonus
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0;
        // allow new bin when few bins open and item is large
        if item_size > 60 && open_bins_count > 0 {
            score -= 4.0;
        }
    }

    // Progress-based mild bias: prefer tighter fits early, spread later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: strongly favor small post_residual.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills leftover space.
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: mild penalty for large dead space.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize opening new bins when many bins already fit the item mildly;
    // reward keeping bin count low generally.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, reduced late in stream
        // or when open bins are fragmented (high mean residual).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0;
        new_bin_cost -= 20.0 * progress;
        // If existing bins are fragmented (mean residual high relative to item), new bin less bad.
        if mean_residual < item_size as f64 * 1.2 {
            new_bin_cost -= 15.0;
        }
        // If next item is huge, an empty bin is valuable for it.
        if next_item_size >= 70 {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    } else {
        // Reward using existing bins, more so when open_bins_count is high.
        score -= 5.0 + (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Coupling: penalize leaving residual that no small item (min 1) could pair with,
    // i.e. very small residuals are actually great (near-perfect fill).
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Time-horizon modulation: early in stream, be conservative with bins;
    // late in stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
