pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual) super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 120.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes: bins whose residual falls into "usable" classes
    // (residuals that common item sizes 1..=100 can still fill well) are favored.
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -1.0,
        1..=10 => -0.8,
        11..=20 => -0.4,
        21..=30 => 0.0,
        31..=50 => 0.5,
        51..=70 => 1.0,
        _ => 1.5,
    };
    score += class * 15.0;

    // Modulo coupling: residual congruent to small multiples of 10 are
    // friendlier to typical item sizes; odd awkward residuals penalized.
    if pr > 0 && pr % 10 != 0 {
        score += 6.0;
    }
    if pr >= next_item_size && next_item_size > 0 {
        // This bin can also serve the next item: big reward for chain fits.
        score -= 25.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Post-residual is dead space for the lookahead item.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; only
    // attractive when the item would leave huge dead space in every open bin.
    if bin_residual == bin_capacity {
        let dead_elsewhere = (post_residual as f64) / 100.0; // placeholder if new bin chosen elsewhere
        let _ = dead_elsewhere;
        // New bin leaves residual = capacity - item_size; penalize unless item is large
        // and mean residual of open bins is small (open bins nearly full anyway).
        let new_bin_residual = bin_capacity - item_size;
        score = 40.0 + new_bin_residual as f64;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to fill older bins first as the stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    // Slight penalty for having many open bins already (consolidation pressure).
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if open bins are on average roomy, prefer filling them
    // rather than spreading; reward this bin when its residual is below mean.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (1..=10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual < 25 {
        // small but potentially usable gap: moderate penalty scaled by gap
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (near-zero post residual but not the dead zone).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Mean residual coupling: if average residual is high, opening new bins
    // is wasteful; penalize the new-bin candidate (residual == capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.35 * mean_residual + open_bins_count as f64 * 2.0;
        // But late in the stream with a poor fit elsewhere, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap: penalize leftover gap proportionally
        score += 0.3 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits exactly into the residual after this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 300.0 - 2.0 * tightness;
    }

    // Penalize leaving residual that cannot host the next item (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // Penalize very small unusable residuals relative to capacity
    if post_residual < 10 {
        score -= 80.0; // tiny leftover = bin was packed well
    }

    // Compare against mean residual of open bins: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it mildly attractive only when existing fits are bad
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (open_bins_count as f64).ln().max(1.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
