pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep shaping
    score += poly * (40.0 + 60.0 * progress) * (1.0 - x);

    // Penalize residuals too small for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = ((nx - x) / cap).abs();
        score += (waste * 30.0).exp() * 5.0 * (1.0 - progress);
    }

    // Reward filling bins tightly (low post-residual)
    score -= (1.0 - x) * (1.0 - x) * 25.0;

    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight preference to keep mean residual balanced
    score += (mean_residual - pr) * 0.1;

    // New-bin candidate: mildly penalize opening bins late, allow early
    if bin_residual == bin_capacity {
        score += 10.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by divisibility classes of capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divides capacity evenly (harmonic residual, reusable)
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 0.5 * pr / cap;
    }
    // Class B: post_residual is a multiple of a "half-capacity" class
    if post_residual > 0 && post_residual % (bin_capacity / 2) == 0 {
        score -= 1.0;
    }
    // Class C: dead-zone penalty for tiny unusable residuals (non-harmonic crumbs)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Integer-division threshold on next_item_size vs post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits: reward, more if exact
        if next_item_size == post_residual {
            score -= 5.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // residual too small for next item: penalize by how close it is to wasted
        score += 1.5 * (pr / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Prefer fuller bins (low residual) mildly, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * (bin_residual as f64 / cap);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -20.0 } else { 25.0 + 5.0 * open_bins_count as f64 };
        score += penalty;
    }

    // Prefer bins below mean residual (keeps spread balanced)
    score += 0.2 * (mean_residual - pr).signum() * (mean_residual - pr).abs().min(20.0) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly
