    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 12.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
