    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (filling emptier-of-space bins first)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight progression awareness: later in stream, avoid wasteful gaps more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual relative to capacity
    score = post_residual as f64 * 1.0 + (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += gap * 0.8;
            if gap < 10.0 {
                score -= 20.0; // near-perfect two-item chain
            }
        } else {
            // next item cannot fit here; post_residual becomes dead space
            let dead = post_residual as f64;
            score += dead * 1.5;
        }
    }

    // Compare residual against mean residual across open bins
    let rel = if mean_residual > 0.0 {
        post_residual as f64 / mean_residual
    } else {
        1.0
    };
    if rel < 0.5 {
        score -= 10.0 * (0.5 - rel); // tighter than average: good
    } else if rel > 1.5 {
        score += 10.0 * (rel - 1.5); // much looser than average: bad
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // no open bin offers a decent fit (post_residual small in existing bins is better)
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > post_residual {
            1.0
        } else {
            0.0
        };
        score = bin_capacity as f64 * 0.9 - pressure * 20.0
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // if many bins are open and fragmented, prefer consolidation
        if open_bins_count > 4 {
            score += 15.0;
        }
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base score.
    // Penalize dead space that is too small to be useful for future items
    // (typical items 10..80), with a non-linear ramp.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Reward using bins with low residual (near-full bins get priority),
    // scaled by how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chaining good pairs).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item can't use leftover; mild penalty proportional to waste
            score += 4.0 * (1.0 - (post_residual as f64 / 100.0));
        }
    } else {
        // Last item: minimize post residual aggressively.
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global state: many open bins -> discourage opening new ones; the new-bin
    // candidate (bin_residual == bin_capacity) gets penalized when bins are plentiful.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
        score += 10.0 + pressure;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible
    // (larger post_residual is less harmful); late in the stream, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, non-linearly penalized more as stream progresses
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Smooth quadratic coupling of post residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth cubic term
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Prefer bins whose residual is close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Lookahead: bonus if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits = (norm_pr - norm_next).max(0.0);
        let next_waste = (norm_pr - norm_next).abs();
        score -= 5.0 * (1.0 - next_waste.min(1.0)) * (1.0 - progress);
        score += 4.0 * fits * fits;
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty scaled by number of open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: smooth calibrated threshold via polynomial gate
    if bin_residual == bin_capacity {
        let gate = 0.5 + 0.5 * (norm_item * (1.0 - progress));
        score += 12.0 * gate + 6.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes are more valuable to preserve.
    let cap = bin_capacity as f64;

    // Reward tight fits (small post_residual), with a harmonic bonus
    // for post residuals that are small multiples of common item sizes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Harmonic divisibility: leftover that can host typical future items
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr % 50 == 0 {
            score -= 4.0;
        }
        // Dead-space penalty: leftovers too small for the minimum item (1..10)
        // are hard to fill later.
        if pr < 10 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (chained fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot class
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded
    // or fit is perfect. Penalize opening new bins when open bins are roomy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = (mean_residual / cap).clamp(0.0, 1.0);
        // High mean residual => existing bins have room => opening new bin is bad.
        score += 35.0 + 40.0 * crowdedness - 20.0 * progress;
        // If item is huge (hard to place later), new bin is more acceptable.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild pressure toward bins below mean residual (balancing loads creates
    // more uniform, usable leftovers).
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * diff;

    // Fractional-capacity class of the item: items near half capacity pair well
    // with each other; slight bonus for placing them into partially filled bins.
    let half = bin_capacity / 2;
    if (item_size as i32 - half as i32).abs() <= 5 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        // Worst zone: tiny unusable slivers (1..=9) — heavy penalty.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        } else {
            // Large leftovers are reusable; mild reward.
            score -= 10.0;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 120.0;
    }

    // Reward tight fits relative to residual (low waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation over new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open / late stream.
        score += 40.0 + pressure;
        // But if this bin's residual would be a dead sliver anyway, opening a new
        // bin can be fine — soften slightly when item is large.
        if item_size > 70 {
            score -= 30.0;
        }
    } else {
        // Using an existing bin relieves pressure slightly.
        score -= 0.15 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item would fit the current residual but not post-residual, penalize.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins below mean residual (fills emptier bins first, keeps tight bins for tight items).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (small dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits exactly in the leftover: excellent chain.
            score -= 45.0 / (1.0 + gap);
            if gap == 0.0 {
                score -= 80.0;
            }
        } else {
            // Next item won't fit in the leftover: penalize proportional dead space.
            score += 0.5 * gap;
            // Small leftovers that block the next item are especially wasteful.
            if post_residual < 10 {
                score += 40.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Penalize opening new bins when reasonable open bins exist,
    // but allow it late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - 40.0 * progress;
        if open_bins_count > 0 {
            score += 30.0;
        }
        // New bin is attractive if the next item is large and would fit alone here.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 90.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly: small post_residual is great.
    let cap = bin_capacity as f64;
    let frag = (post_residual as f64 / cap).powi(2);
    score += 40.0 * frag;

    // Lookahead: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to leftover waste
        score += 0.2 * (post_residual as f64 - (next_item_size as f64 - 1.0).min(post_residual as f64)).max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Time horizon: early in the stream, keep bins flexible (favor tight fills less,
    // favor spreading to keep residual options open); later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / cap);

    // Global state: many open bins with high mean residual -> encourage filling
    // existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / cap);
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // unusable sludge and the item is large.
    if bin_residual == bin_capacity {
        let sludge = (bin_residual - item_size) as f64;
        let waste_here = if post_residual < 10 { 60.0 } else { 0.0 };
        score += 35.0 - 0.4 * item_size as f64 - waste_here;
        // late in stream, opening new bins is fine since consolidation already happened
        score -= 10.0 * progress;
        let _ = sludge;
    }

    // Discourage placing small items into large-residual bins early (waste of space).
    if item_size < 30 && bin_residual > 70 && progress < 0.5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but with a non-linear penalty for mid-range waste
    let mut score = norm_pr;
    // Smooth quartic-ish coupling: penalize residuals near ~half capacity more strongly,
    // since dead space there is least reusable
    let bump = 4.0 * norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score += 0.6 * bump * bump;

    // Stream-progress coupling: later in the stream, waste matters more (fewer chances to fill)
    score += norm_pr * (0.5 + 2.0 * progress * progress);

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 0.9 * (nx / cap) * (1.0 - progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 0.4 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Tie-breaking toward fuller bins when many bins are open
    score -= (item_size as f64 / cap) * 0.1 * (open_bins_count as f64).sqrt();

    // New-bin candidate: neutral-ish baseline scaled with progress
    if bin_residual == bin_capacity {
        score = 1.0 + 0.8 * progress + 0.2 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // "reusable" buckets via integer division. Leftovers that are exact
    // divisors/quarters of capacity are more likely reusable later.
    let pr = post_residual;
    let class = if pr == 0 { 0u32 }
        else if pr <= 5 { 1 }
        else if pr <= 15 { 2 }
        else if pr <= 30 { 3 }
        else { 4 };
    score += class as f64 * 4.0;

    // Reward exact modular harmony: leftover divisible by common item sizes
    if pr > 0 && (pr % 10 == 0) {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // penalize wasting space the next item could have used elsewhere
            score -= 8.0 * (pr - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item cannot fit here; leftover dead space penalty grows
            score += 3.0 * (next_item_size - pr).min(40) as f64;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into fuller bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 6.0;

    // Mean residual coupling: bins far below mean residual are worse targets
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when nothing fits harmonically
    if bin_residual == bin_capacity {
        let penalty = 30.0 + 20.0 * (open_bins_count as f64).ln().max(0.0) + 40.0 * (1.0 - progress);
        // if this is the only fitting option (no open bin fits), opening is fine
        if fitting_bins_count == 0 {
            score = -50.0;
        } else {
            score += penalty;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap slightly larger than next item (near-miss waste).
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: reward using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // (mean residual low) or the fit into any open bin would be poor.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = (mean_residual - item_size as f64).max(0.0);
        let crowd = (open_bins_count as f64) * 0.5;
        score -= (poor_fit_pressure * 0.8 + crowd * 2.0).min(45.0);
        // Base handicap so decent existing fits still win.
        score += 5.0;
    }

    // Mild alignment with mean residual: prefer bins below-average residual
    // (tighter bins) to consolidate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item size (creates a perfect fit for the following item).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        if gap == 0.0 {
            score -= 40.0; // perfect 2-step chain
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot follow here: penalize dead space proportionally
        score += 0.35 * post_residual as f64;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is above average (absorb item into loose bins).
    if post_residual as f64 > mean_residual {
        score -= 8.0;
    } else {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (< smallest item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: default mild penalty; only attractive when all open
    // bins would leave large dead space or the current item is huge.
    if bin_residual == bin_capacity {
        let best_open_waste = (post_residual as f64) / (bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        } else if item_size >= 50 && fitting_bins_count <= 2 {
            score -= 15.0; // big item, few options: fresh bin is fine
        } else if best_open_waste > 0.0 {
            score += 20.0 + 0.2 * open_bins_count as f64; // prefer filling existing bins
        }
    }

    // Late in the stream, tighten packing (avoid opening bins near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress > 0.85 {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: geometric bonus when post_residual is small.
    let tight = 1.0 - post / cap;
    score -= 45.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post > 0.0 {
        let nx = next_item_size as f64;
        if nx > 0.0 && nx > post && nx <= bin_residual as f64 {
            score += 12.0; // lookahead item won't fit this bin's leftover
        }
        if nx > 0.0 && nx <= post {
            score -= 18.0 * (nx / post); // next item can reuse leftover
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 4.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Time horizon: early stream -> encourage filling few bins well;
    // late stream -> prefer opening fresh bins over scattering.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * t * (post / cap);

    // Global residual coupling: if mean residual is high, prefer bins
    // above the mean (consolidate); if low, prefer below-mean bins.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Mild penalty for too many open bins; reward consolidation.
    score += 0.6 * open_bins_count as f64 * (post / cap);

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let fill_ratio = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like, no piecewise constants

    // Base: penalize wasted residual, more strongly later in the stream.
    let mut score = pr * (0.6 + 0.8 * poly);

    // Non-linear reward for tight fits (high fill ratio), amplified with progress.
    score -= (fill_ratio * fill_ratio) * (8.0 + 14.0 * poly);

    // Cubic dead-space penalty: small residuals (<~half item scale) are hard to reuse.
    let dead = (1.0 - pr / (item_size.max(1) as f64 + 1.0)).max(0.0);
    score += dead * dead * dead * 4.0;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * poly;
    }

    // Lookahead: reward if next item fits in post_residual (smooth exponential).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 6.0 * (-(slack / cap).max(0.0) * 2.0).exp();
    } else if next_item_size > 0 {
        // Penalize blocking the next item proportionally to how badly it misses.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 5.0 * miss * miss;
    }

    // Mild penalty for bin proliferation relative to stream size.
    score += (open_bins_count as f64) * 0.05 * (1.0 - poly);

    // Slight preference toward bins with below-average residual (conserving big gaps).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 2.0 * dev * dev * (1.0 - dev.signum() * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse integer division thresholds
    let item_class = item_size / 25;              // 0..3 (tiny, small, medium, large)
    let next_class = next_item_size / 25;

    // Fractional fill of the bin after placement
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward near-full fills strongly (non-linear)
    score -= 40.0 * fill_frac * fill_frac * fill_frac;

    // Penalize dead space in harmonic classes: residuals in (0,10) are useless,
    // residuals in [10,25) can host tiny items, etc.
    if post_residual > 0 {
        let usable = if post_residual >= 25 { 3 }
                     else if post_residual >= 10 { 2 }
                     else { 0 };
        if usable == 0 { score += 60.0; }
        else { score -= 8.0 * usable as f64; }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Modulo coupling: can the next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Chainability bonus, scaled by how tightly next item fits
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.3 * slack;
        // Harmonic match: same class chains well
        if item_class == next_class { score -= 10.0; }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how far off
        let gap = (next_item_size - post_residual) as f64;
        score += 0.4 * gap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 25.0 + 10.0 * crowded;
        if item_class == 3 {
            // Large items: opening fresh bins is relatively safer
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 12.0; // keep space for big lookahead item
        }
    }

    // Stream progression: early on, be conservative with bins; later, pack aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - fill_frac);

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_frac);

    // Alignment with mean residual: prefer bins whose residual stays near the mean
    let new_residual = post_residual as f64;
    let dev = (new_residual - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (items >= 1, but practically below ~10 are near-unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 60.0;
    } else {
        // Usable residual: reward tight-but-usable fits.
        score -= (post_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // Reward filling a bin deeply (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Last-chance pressure: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += open_pressure * 8.0;

    // Deviation from mean residual: prefer bins that are already low-residual
    // (keeps residual distribution tight, avoiding many half-empty bins).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.4;

    // Lookahead: if the next item would fit exactly in the post-residual,
    // strongly favor this placement (chains items perfectly).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 55.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would be blocked by the dead space we create, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // fits well, i.e. when open bins are crowded. Otherwise discourage it.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual < item_size as f64) || (fitting_bins_count == 0);
        if crowded {
            score -= 45.0;
        } else {
            score += 70.0 + open_pressure * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin: base cost is its full leftover capacity minus what we put in.
        score = post_residual as f64;
        // Mild penalty so existing tight fits win; relax late in the stream or when
        // the item is huge and would leave a nearly perfect post_residual anyway.
        score += 10.0 - 6.0 * progress;
        if item_size >= 70 { score -= 5.0; }
    } else {
        // Reward exact 2-step lookahead match: post_residual == next_item_size.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual == next_item_size {
                score -= 40.0; // perfect chain: next item fills this bin exactly
            } else if post_residual < next_item_size {
                // Dead space relative to the lookahead item: penalize proportionally.
                score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            } else {
                // Next item still fits afterwards: mild reward scaled by tightness.
                score -= 8.0 * (next_item_size as f64 / post_residual as f64);
            }
        }
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins tighter than the current mean residual (good fits).
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large or the current fit is poor elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 18.0;
        // Large items benefit from a fresh bin (avoid fragmentation).
        if item_size >= 60 {
            new_bin_penalty -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to
        // co-pack); late in the stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty *= 0.5 + progress;
        // If open bins are already loose, a new bin dilutes packing density.
        if mean_residual > 30.0 {
            new_bin_penalty += 8.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead coupling: if the next item would fit exactly in the
    // post_residual, reward heavily (perfect two-item pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty if we leave big gap.
            let gap = post_residual as f64;
            if gap > 40.0 {
                score += 5.0;
            }
        }
    }

    // Dynamic time horizon: near the end of the stream, squeeze into
    // existing bins aggressively (new bins waste capacity permanently).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 10.0 * (progress - 0.8) * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins below mean residual (balance load, keep big holes alive).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic-ish penalty on wasted space, smoothed by capacity normalization.
    let mut score = (pr / cap).powi(2) * 100.0 + pr * 0.5;

    // Smooth non-linear coupling of wasted space with stream progress:
    // later in the stream, dead space matters more (fewer chances to fill it).
    let progress_coupling = (pr / cap) * (progress * progress * 60.0 + 20.0 * progress);
    score += progress_coupling;

    // Reward tight fits: cubic reward decaying with post_residual.
    score -= (1.0 - pr / cap).powi(3) * 30.0;

    // Lookahead: penalize if remaining space cannot fit the next item
    // (smoothly via gap ratio), reward if it can.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack).powi(2) * 25.0;
        } else {
            let gap = (nxt - pr) / cap;
            score += gap.powi(2) * 40.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin smoothly,
    // more so when good fitting bins exist or many bins are open.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln_1p() * 4.0;
        let waste_pressure = (mean_residual / cap).powi(2) * 20.0;
        let progress_pressure = 10.0 + 30.0 * progress;
        score += open_pressure + waste_pressure + progress_pressure;
    } else {
        // Slight preference for bins below mean residual (consolidate waste).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (10s) are more reusable.
    let pr = post_residual;
    let class_bonus = match pr {
        0 => 60.0,                       // perfect fit
        r if r % 10 == 0 => 25.0,        // highly reusable leftover
        r if r % 5 == 0 => 10.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Dead-space penalty: tiny unusable leftovers (below min plausible item) are bad,
    // but a perfect 0 is great. Nonzero residual < 10 is wasted space.
    if pr > 0 && pr < 10 {
        score += 40.0 * (10 - pr) as f64;
    }

    // Integer-division thresholds: leftover in "thirds" of capacity.
    let third = bin_capacity / 3;
    if pr >= third && pr < 2 * third {
        score -= 8.0; // mid-range leftover is a useful slot
    } else if pr < third && pr > 0 {
        score += 12.0; // cramped leftover
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item divides into this bin's class
            if pr % next_item_size.max(1) == 0 {
                score -= 30.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize less if leftover is still broadly usable
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64).max(1.0);
        let pressure = (mean_residual / cap).max(0.0).min(1.0);
        // base cost of a fresh bin, discounted when open bins have little room left
        score += 55.0 + 20.0 * progress - 45.0 * (1.0 - pressure) / crowding.sqrt();
        // opening a bin right before a small next item is wasteful
        if next_item_size > 0 && next_item_size <= 20 {
            score += 15.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor with harmonic tilt).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=100 range) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is excellent
    } else {
        // Larger usable gaps: mild quadratic penalty to prefer tighter fits
        let r = post_residual as f64;
        score += 0.02 * r * r / bin_capacity as f64;
    }

    // Reward bins whose gap exactly accommodates the lookahead item (k=2)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins;
    // opening a brand-new bin (residual == capacity) gets a penalty
    // that grows with the number of already-open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        // Using an existing bin relieves pressure slightly
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (better consolidation)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, be more conservative about dead space;
    // late in the stream, closure matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * progress * if post_residual == 0 { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: item + next item exactly fills bin
        } else {
            score += diff * 0.8; // penalize mismatch between dead space and next item
        }
    }

    // Reward tight packing: small post_residual relative to capacity
    let tightness = post_residual as f64 / cap;
    score += tightness * tightness * 40.0;

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist, unless residual would be tiny
    if bin_residual == bin_capacity {
        // new bin candidate: post_residual = cap - item_size; penalize unless very tight
        score += 20.0;
        if post_residual as f64 <= cap * 0.2 {
            score -= 45.0; // near-full new bin is fine
        }
    }

    // Slight pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
