    // existing bins are badly fragmented / none fit well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Opening a new bin is good for big items (keeps big-item flexibility).
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        // Penalize new bins when plenty of open bins have room (avoid bin explosion).
        let crowding_penalty = 6.0 * (open_bins_count as f64).ln().max(0.0);
        score = score.max(0.0) + 45.0 - big_item_bonus + crowding_penalty
            - 10.0 * progress * (1.0 - fragmentation / bin_capacity as f64);
        // If no other bin fits at all, new bin is essentially forced.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // encourage consolidating into bins with below-average residual.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.08 * dev;
    }

    // Time horizon: late in the stream, be more conservative (avoid waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: waste measure with non-linear shaping (quartic trough near mid residuals)
    let mut score = x * (1.0 - 0.6 * (1.0 - x) * (1.0 - x));

    // Polynomial coupling of post_residual with stream progress:
    // early stream: prefer leaving moderate space (tight fit bonus), late stream: prefer tight fits strongly
    let coupling = (1.0 - progress) * (x - 0.35) * (x - 0.35) + progress * x * x;
    score += 2.0 * coupling;

    // Reward tight fits: small post residual gets subtraction, scaled by progress
    score -= (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Last-chance bin bonus: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 + 0.5 * progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let waste = (pr - nx).max(0.0) / cap;
        score += 1.2 * waste * waste;
        // reward if next item fits snugly into the post residual
        if nx <= pr {
            score -= 0.8 * (nx / cap) * (1.0 - progress);
        }
    }

    // Slight preference to fill existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 0.3 + 0.7 * progress;
    }

    // Coupling with mean residual: penalize bins deviating from the mean (keeps balance)
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev;

    // Mild penalty for many open bins
    score += 0.01 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // for common item sizes (multiples of 10, and small residuals 1..10).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if pr < 10 {
        score += 25.0; // dead space below smallest item
    } else {
        // class bonus by divisibility structure
        let class_bonus: f64 = if pr % 50 == 0 {
            18.0
        } else if pr % 25 == 0 {
            14.0
        } else if pr % 20 == 0 {
            12.0
        } else if pr % 10 == 0 {
            10.0
        } else if pr % 5 == 0 {
            5.0
        } else {
            0.0
        };
        score -= class_bonus;

        // integer-division threshold: how many "average" items still fit
        let slots = pr / 15;
        score -= slots as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.5;
        } else {
            // next item won't fit here; penalize wasting capacity on tight fits
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate penalty: only open a new bin when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        // allow opening when current item is huge and would leave large residue elsewhere
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Mild preference for tight fits overall
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small unusable dead space (gaps below the minimum item size).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Dead space is worse if it cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Prefer tight fills relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            score += 12.0; // only open a new bin if no open bin fits well
        }
    } else {
        // Reusing a bin reduces open-bin growth pressure.
        score -= 2.0;
    }

    // Last-chance bin: strongly favor it to avoid wasting its capacity.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    // Mild preference to spread load when mean residual is high.
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: bin closes perfectly over two items.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving exactly next_item_size; penalize slack quadratically.
            score -= 60.0 - (slack * slack).min(60.0);
        } else {
            // Next item cannot follow here: residual likely dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 20.0 + waste.min(80.0);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 100.0;
    }

    // Reward bins tighter than the mean (good fits), penalize loose bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let pressure = mean_residual / (bin_capacity as f64);
        score += 40.0 + pressure * 80.0 - 200.0 / crowding;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    // Mild stream-phase modulation: early on, keep bins open (exploit flexibility later).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - phase) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // If the leftover space can still fit the next item, this bin is extra valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Bonus when leftover is a snug fit for the next item.
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Penalize dead space: leftover that likely cannot be used (too small for typical items).
    if post_residual < 10 {
        score -= 20.0; // nearly perfect fit
    } else if next_item_size == 0 || post_residual < next_item_size {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer consolidating into existing ones;
    // when few bins are open, opening a new one is cheaper.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, favor closing bins tightly (avoid stragglers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual: if this bin's residual is far below average, it's a good fit target.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin offers a reasonable fit
    // (i.e., this empty bin has huge residual but we add a penalty so it loses to decent fits).
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room to also take the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: residuals hurt more as stream progresses
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let poly = pn * pn * (1.0 + 2.0 * progress) + pn * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    let tightness = 1.0 - pn;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Few fitting bins: mild reward for this bin
    if fitting_bins_count >= 2 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: penalize opening bins unless residual is very unusable
    if bin_residual == bin_capacity {
        let waste = if post_residual < item_size { 0.0 } else { 1.0 };
        let dead = (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * bin_capacity as f64);
        score += 25.0 + 30.0 * (1.0 - progress) - 35.0 * dead * waste;
        // Lookahead: if next item fits the new bin's post residual, reduce penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if next item fits post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }
    // Penalize if next item cannot use the leftover space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0 * progress;
    }

    // Mean-residual coupling: placing into bins below mean residual keeps balance
    let dev = mean_residual - bin_residual as f64;
    score += 2.0 * dev.abs() / bin_capacity as f64;

    // Many open bins: discourage spreading too thin, favor filling existing bins
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual: how "reusable" is the leftover? ---
    // Residuals divisible by common small item sizes (5,10,20) remain highly packable.
    let pr = post_residual as i64;
    let mut reuse_bonus = 0.0;
    if pr == 0 {
        reuse_bonus += 60.0; // perfect closure
    } else {
        if pr % 5 == 0 { reuse_bonus += 6.0; }
        if pr % 10 == 0 { reuse_bonus += 6.0; }
        if pr % 20 == 0 { reuse_bonus += 4.0; }
        if pr % 25 == 0 { reuse_bonus += 3.0; }
        // Dead-space class: tiny unusable slivers (1..5) are almost dead
        if pr < 5 { reuse_bonus -= 25.0; }
        else if pr < 10 { reuse_bonus -= 12.0; }
    }
    score -= reuse_bonus;

    // --- Lookahead coupling: does the leftover exactly host the next item? ---
    if next_item_size > 0 {
        if pr == next_item_size as i64 {
            score -= 30.0; // next item closes this bin perfectly
        } else if pr >= next_item_size as i64 {
            let left_after_next = pr - next_item_size as i64;
            if left_after_next % 10 == 0 { score -= 8.0; }
            if left_after_next < 10 && left_after_next > 0 { score += 6.0; }
        } else {
            score += 10.0; // leftover too small for the next item
        }
    }

    // --- Tightness reward: reward filling a large fraction of current residual ---
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac * fill_frac;

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // A fresh bin is attractive only if item is large and no bin fits snugly.
        // Penalize opening new bins mildly; the base post_residual (= capacity - item)
        // already penalizes small items in new bins.
        score += 8.0 + 0.05 * open_bins_count as f64;
        if item_size >= 50 {
            score -= 10.0; // large items are fine to start fresh
        }
    }

    // --- Stream progression: early on, be conservative with new bins; late, consolidate ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // --- Mean residual context: if this bin's residual is far below mean, it's a good target ---
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev; // bins with residual below mean (tighter) get lower score

    // --- Integer-division threshold classes on post_residual ---
    let class = pr / 10; // coarse harmonic class
    score -= match class {
        0 => 8.0,   // 0..9: nearly closed, good
        1 => 4.0,   // 10..19: fits small items
        2 => 1.0,   // 20..29
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small to hold even the smallest plausible item.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual as f64 > 0.0 && (post_residual as f64) < dead_threshold {
        score += 60.0; // heavy penalty for creating unusable slivers
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is strongly rewarded
    }

    // Nonlinear coupling: penalize wasted fraction of the bin quadratically,
    // scaled by how tight the fit is.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Reward tight fits: item filling most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; penalize slightly per open bin
    // unless the fit is very good.
    if open_bins_count > 2 {
        score += (open_bins_count as f64) * 1.5 * waste_frac;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and existing fits would leave big dead space.
    if bin_residual == bin_capacity {
        let would_waste = waste_frac;
        score += 35.0; // base cost of opening a new bin
        // But if no existing bin fits well (high mean residual usage mismatch),
        // opening a new bin becomes more attractive.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if would_waste < 0.2 {
            score -= 20.0; // large item into fresh bin is fine
        }
    }

    // Lookahead: if the next item would fit the post-residual exactly,
    // reward leaving that gap; if the gap is useless for the next item,
    // penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Stream progression: early in the stream, be slightly more willing to
    // open bins (build diverse residuals); late, consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += 10.0 * (1.0 - fill); // late stream: punish loose fits
    } else if progress < 0.2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-item pairing
        } else if post_residual >= next_item_size {
            // next item fits too: mild reward, tighter slack is better
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space proportionally
            score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that are already "loaded" (small residual vs mean)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline; only attractive if open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // prefer new bin when open bins have large residuals (poor fits elsewhere)
        score = 40.0 + 30.0 * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // slight bonus when a fresh bin can host the next item too
        }
    }

    // Slight time pressure: later in stream, consolidate more aggressively
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable slivers (post_residual < 10 is dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the leftover residual can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalty if the residual is *just barely* too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Last-chance bin: strongly reward using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base reluctance to open a new bin, decaying as the stream progresses
        // (late in the stream, consolidating matters more; early, spreading is fine).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 20.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // If open bins have large mean residual, prefer using them.
        score += mean_residual * 0.1;
        // Late in stream with few fitting bins, opening a fresh bin is reasonable.
        if fitting_bins_count <= 2 && progress > 0.5 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, favor consolidation.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Exact-fit jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (post_residual penalized strongly).
    // Late: tolerate residual waste slightly more to avoid opening bins.
    let w = 1.0 + 0.8 * progress - 0.6 * progress * progress;
    score += w * (pr * pr) / cap;

    // Reward good fit: small post_residual relative to capacity.
    let fit_ratio = pr / cap;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that cannot fit a plausible next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 6.0 + 4.0 * (ni - pr) / cap;
        } else {
            // Reward leaving room for the lookahead item.
            score -= 4.0 * (1.0 - (pr - ni).abs() / cap);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly, more early in stream; relax late.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
        // Avoid opening new bins when many open bins still have room.
        score += (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);
    }

    // Slight preference for bins with residuals near the mean (balance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (Best-Fit core).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // residual fraction

    // Harmonic class penalty: quantize post_residual into classes of 10.
    // Residuals in (0,10] are near-perfect; residuals just above multiples of 10
    // are "wasted class" residuals that rarely fit future items.
    let class = (post_residual + 9) / 10; // ceil class index 1..10
    let class_center = (class * 10 - 5) as f64;
    let deviation = (post_residual as f64 - class_center).abs();
    score += 0.6 * deviation / 10.0;

    // Perfect closure reward: residual exactly 0 or exactly matches a small item class.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual remains usable, but prefer leaving
            // post_residual that also divides nicely (harmonic divisibility).
            if post_residual % 25 == 0 || post_residual % 20 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize large dead space.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: the fresh empty bin should only win when
    // all open fits are bad. Penalize opening a new bin unless the item is
    // large relative to capacity or there are no fitting bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // pairing large items in fresh bins is fine later
        }
        if item_size >= 50 {
            score -= 20.0; // large items are fine to start fresh bins
        }
    }

    // Stream progression: early on, keep bins open (packing density matters later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (mean_residual / cap);

    // Penalty scaling with how much this placement strands space vs mean residual.
    if post_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 0.25 * (post_residual as f64 - mean_residual);
    }

    // Modulo harmonic bonus: residuals that are multiples of common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that no realistic future item (1..=100) can pair with well
    // is treated as pure waste.
    let gap = post_residual as f64;
    if post_residual > 0 {
        // Dead zone: gap too small to be useful for medium/large items.
        if post_residual <= 10 {
            score += 60.0; // nearly unusable sliver
        } else if post_residual <= 20 {
            score += 30.0;
        } else if post_residual <= 35 {
            score += 12.0;
        } else if post_residual <= 50 {
            score -= 8.0; // still useful for mid-size items
        } else {
            score -= 15.0; // large residual = flexible bin
        }

        // Coupling: if the lookahead item fits exactly into the post residual,
        // this placement chains perfectly — reward strongly.
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 40.0;
            } else if slack <= 15.0 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here after placement: bin likely closes.
            // Small penalty scaled by how dead the leftover space is.
            score += gap * 0.25;
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 80.0;
    }

    // Tight fit reward: item fills most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 25.0;
    } else if fill_ratio > 0.7 {
        score -= 10.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins over opening new ones.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin fits well (last chance) or mean residual is low.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        let mut new_bin_score = 55.0 + pressure;
        if next_item_size > 0 {
            // A fresh bin can always accept the next item too.
            new_bin_score -= 10.0;
        }
        // If this bin is the only fitting option, existing bins are scarce:
        // make new bin slightly less attractive so we still use the last bin.
        if fitting_bins_count == 1 {
            new_bin_score += 20.0;
        }
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_score += mean_residual * 0.3;
        return new_bin_score;
    }

    // Last-chance bin: if this is the ONLY open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild stream-progression term: late in the stream, closing bins cleanly
    // matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (gap * 0.15);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead core ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: next item fits here too -> excellent chaining placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.4 * slack;
        } else {
            // Penalize dead space the next item cannot use.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
            // Extra penalty if the dead space is tiny and unusable (fragmentation).
            if post_residual > 0 && post_residual < 10 {
                score += 25.0;
            }
            // Perfect closure: bin becomes exactly full -> very desirable.
            if post_residual == 0 {
                score -= 60.0;
            }
        }
    } else {
        // Last item: just close bins tightly.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // ---- Relative tightness vs mean residual ----
    // Prefer bins that are already somewhat filled (residual below mean).
    let tightness = mean_residual - bin_residual as f64;
    score += 0.25 * tightness;

    // ---- Last-chance bonus ----
    // If this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Opening a new bin is fine early in the stream or when many bins needed anyway,
        // but penalize it late when existing bins could absorb the item.
        score += 55.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 51..=60 zone
    // (hard to fill with items of size >= 10 in pairs).
    if post_residual >= 51 && post_residual <= 60 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Chain potential: next item leaves a still-usable remainder.
            let chain_res = post_residual - next_item_size;
            if chain_res <= 10 {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits now but not after this placement: mild penalty if we waste the chance.
            if next_item_size > post_residual && next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    } else {
        // Last item: any placement is fine, prefer filling existing bins.
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 35.0;
        // Fewer fitting bins => opening a new bin is less wasteful.
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        } else if fitting_bins_count == 1 {
            new_bin_cost -= 10.0;
        }
        // Large items are better in a fresh bin (avoid fragmenting partial bins).
        if item_size >= 60 {
            new_bin_cost -= 12.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost += 20.0 * progress;
        // If open bins have lots of slack, using them is cheap.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_cost += 15.0;
        }
        score += new_bin_cost;
    } else {
        // Existing bin: slight reward when it is one of few options (avoid stranding it).
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Penalize placing into bins whose residual deviates wildly from mean (keep balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Small global regularization: prefer using more of the stream's open bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space ratio.
    let waste = post_residual as f64 / cap;
    score += 40.0 * waste * waste * cap;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize bins whose residual after placement is too small for typical
    // future items but nonzero (dead space) — smooth cubic in waste.
    score += 15.0 * waste * waste * waste * cap;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins: penalize spreading across many bins.
    let spread = (open_bins_count as f64).ln().max(0.0);
    score += progress * spread * 8.0;

    // Interaction: if mean residual is high, favor bins below mean (tighter bins).
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev * dev / cap;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer opening a fresh bin early or when this bin's
    // post-residual would be very small (wasteful), otherwise discourage.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let new_penalty = 10.0 + 30.0 * (1.0 - waste) * (1.0 - progress);
        score += new_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "usable" vs "dead" space classes for integer item sizes.
    let r = post_residual % 10;
    let dead_penalty: f64 = match r {
        0 => -6.0,          // perfectly aligned residual: excellent
        1 | 9 => 1.5,       // nearly aligned, slight waste
        2 | 8 => 2.5,
        3 | 7 => 3.5,
        4 | 6 => 4.5,
        _ => 6.0,           // residue 5: worst half-class dead space
    };
    score += dead_penalty;

    // Integer-division thresholds: very small post_residual is great
    // (bin nearly full), but only if it's exactly zero or a class-0 residue.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    } else if post_residual >= 90 {
        // Bin left almost untouched: wasteful placement
        score += 12.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_class = next_item_size % 10;
            // Reward if post residual lies in a harmonic class that
            // can absorb the next item with zero or class-0 leftover.
            let combined = post_residual - next_item_size;
            if combined % 10 == 0 {
                score -= 10.0;
            } else if combined <= 5 {
                score -= 5.0;
            } else {
                score += (combined % 10) as f64 * 0.4;
            }
            if nxt_class == 0 {
                score -= 1.0; // next item is a "clean" size
            }
        } else {
            // Next item won't fit here regardless; mild penalty for
            // leaving medium dead space instead of near-zero.
            score += 3.0;
        }
    } else {
        // Last item: prefer exact fill strongly.
        score -= post_residual as f64 * 0.5;
    }

    // Capacity fraction coupling: reward tight fits relative to capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current
    // residual is unusable dead space for typical item sizes.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has full residual; make it attractive
        // only when open bins are fragmented (high mean residual spread)
        // or the item is large relative to typical residuals.
        let frag = (mean_residual - post_residual as f64).abs();
        score += 5.0 + frag * 0.2;
        if item_size >= 60 {
            score -= 8.0; // large items benefit from fresh space
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Encourage consolidation: more open bins -> prefer using existing.
        score += open_bins_count as f64 * 0.15;
    }

    // Stream progression: late in the stream, tighten packing more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mean residual anchoring: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps hard: dead space zones
    let dead = if post_residual > 0 && post_residual < 10 { 40.0 }
               else if post_residual >= 10 && post_residual < 20 { 12.0 }
               else { 0.0 };
    score += dead;

    // Reward near-perfect fills
    if post_residual == 0 { score -= 60.0; }

    // Perfect fit for the lookahead item: strong bonus
    if next_item_size > 0 && post_residual == next_item_size as f64 as u32 { score -= 30.0; }
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 8.0; // leaves a gap just below next item
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open
    let pressure = open_bins_count as f64 * 1.5;
    score -= pressure.min(25.0);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 35.0; }

    // New-bin candidate: penalize unless item is large relative to residual
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 80 { score -= 50.0; }
        if next_item_size > 0 && bin_residual - item_size >= next_item_size as u32 { score -= 10.0; }
    }

    // Slight preference for bins below mean residual (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after hypothetical next placement
            score += slack * 0.6;
            if slack < 10.0 {
                score -= 120.0; // near-perfect 2-step chain
            }
        } else {
            // next item cannot follow into this bin; penalize small post_residual (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - residual_f) * -0.3;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 3 {
        score += 15.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 60.0;
        }
        // discourage opening new bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 30.0;
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo_waste = post_residual - next_item_size;
        score -= 25.0 - 0.4 * combo_waste as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward small residuals
        // that neither fit the next item nor are likely useful.
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins lightly; encourage filling
    // bins below mean residual (i.e., fuller-than-average bins).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (bin_res_f - mean_residual) / mean_residual.max(1.0);
        score -= 6.0 * rel;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent
    // fitting bins exist or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 12.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 15.0 + 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // If item is large and residual space in system is fragmented, opening
        // a fresh bin is less bad.
        let large_item = item_size as f64 / bin_capacity as f64;
        new_bin_penalty -= 10.0 * large_item;
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for filling bins with smaller residuals overall
    // (best-fit flavor scaled by stream progress).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - bin_res_f / bin_capacity as f64);

    // Small penalty for very small unusable leftovers (fragmentation guard),
    // unless they exactly match plausible future small items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress
    let x = pr / cap; // normalized residual [0,1]
    let t = progress;
    let coupling = x * x * (1.0 - t) - x * x * x * t;
    score += 40.0 * coupling;

    // Penalize residuals that cannot fit the lookahead item (smoothly)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward exact/near-exact fit for the next item
        let fit = if pr >= next_item_size as f64 {
            1.0 - (pr - next_item_size as f64) / cap
        } else { 0.0 };
        score -= 15.0 * fit * fit * t;
    }

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += (open_bins_count as f64).ln() * x * 5.0;

    // Reward tight packing relative to current mean residual
    score -= (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "useful" residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Integer-division thresholds on post_residual
    if pr == 0 {
        score -= 60.0; // perfect fit is always excellent
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space negligible
    } else if pr <= 25 {
        score -= 8.0;
    } else if pr >= 50 {
        score += 10.0; // wasteful large leftover
    }

    // Modulo arithmetic: leftover divisible by small item sizes is reusable
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // Odd, prime-ish leftovers are dead space
        if pr % 10 != 0 && pr % 5 != 0 && pr > 30 {
            score += 5.0;
        }
    }

    // Coupling with lookahead item: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chain placement possible
            // Harmonic match: next item exactly consumes the leftover class
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item won't fit here -> bin likely closes
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a bin unless current
    // residuals are badly fragmented
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin mandatory
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big next item: fresh bin attractive
        }
    }

    // Mild pressure against bin sprawl
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps (10..=20) proportionally
    if post_residual >= 10 && post_residual <= 20 {
        score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward exact/near-exact fits strongly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    if bin_residual != bin_capacity {
        score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    } else {
        // New bin candidate: penalize unless open bins are crowded or fit is bad
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open new bin
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Mild stream-progression modulation: tighten packing late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to the item (tight fit relative to mean)
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * lookahead_gap;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: item + next item fill the bin exactly
        } else if post_residual < next_item_size {
            score -= 8.0; // dead space usable by nothing else; acceptable to seal bin
        }
        // Bonus scaled by how close post_residual is to any useful placement
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 5.0 * tightness;
    } else {
        // Last item: prefer fullest packing
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving residuals that are likely unusable (small odd gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Relative-to-mean coupling: bins below mean residual are already tight; prefer them
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless open bins are very full / scarce fits
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 30.0 - 5.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild stream-phase adaptation: later in stream, prefer consolidating (tighter fits)
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * phase * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let p = progress;
    let poly = pr * (1.0 - 0.5 * p) + 0.3 * pr * pr / bin_capacity as f64 * (0.5 + p);
    score = poly;

    // Reward tight fits: small post_residual relative to capacity
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * (10.0 + 20.0 * p);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (1.0 + 2.0 * p);
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for spreading across many bins late in stream
    score += 0.05 * open_bins_count as f64 * p;

    // Deviation from mean residual: prefer near-mean residuals
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable" residue classes are better.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows superlinearly for tiny residuals (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: post_residual divisible by common small sizes (5,10,20,25) is reusable.
    if post_residual % 5 == 0 && post_residual > 0 { score -= 6.0; }
    if post_residual % 10 == 0 && post_residual > 0 { score -= 6.0; }
    if post_residual % 20 == 0 && post_residual > 0 { score -= 4.0; }
    if post_residual % 25 == 0 && post_residual > 0 { score -= 4.0; }

    // Reward if next item exactly fits the post residual (harmonic match).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot fit into post residual but bin would be near-empty otherwise.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: strongly prefer filling it rather than leaving a lone open bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let base = cap * 0.55;
        score = base
            + (open_bins_count as f64) * 2.0
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size > item_size * 2 { -8.0 } else { 0.0 };
    }

    // Slight late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest possible item (1)
    // are pure waste; weight them nonlinearly.
    if post_residual > 0 {
        score += 8.0 / post_residual as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving gaps that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins with below-mean residual (tighter fits)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0 + open_bins_count as f64 * 2.0;
        // If current bin would leave a large unusable gap, new bin becomes better
        if post_residual > 0 && post_residual < next_item_size.max(1) && bin_residual != bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (low dead space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - pr / cap; // 0..1, high = tight fit
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: if the next item can fit exactly into the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let chain_waste = pr - nxt;
            if chain_waste == 0.0 {
                score -= 40.0;
            } else {
                score -= 20.0 * (1.0 - chain_waste / cap);
            }
        } else {
            // Next item cannot follow into this bin: penalize proportional to
            // how far off it is (dead-space risk).
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap;
        }
    } else {
        // Last item: minimize residual as much as possible.
        score -= 10.0 * tightness;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (consolidating space).
    if pr < mean_residual {
        score -= 5.0 * (mean_residual - pr) / cap;
    } else {
        score += 5.0 * (pr - mean_residual) / cap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        // But if next item won't fit here either, soften the bonus a bit.
        if next_item_size > post_residual && next_item_size > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / cap;
        // Prefer new bin for big items (they'd wreck open bins' flexibility),
        // penalize new bin for small items.
        score += 30.0 * (1.0 - fill_fraction);
        if fitting_bins_count > 0 {
            score += 8.0; // open bins exist that fit; bias toward them
        }
    }

    // Mild preference for filling bins as the stream progresses (fewer lingering bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the leftover relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Dead-space penalty: residual too small to ever fit the smallest item (1..100 interface).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0;
    }
    // Soft dead-space: leftover below half of the item's size is likely wasted.
    if post_residual < item_size / 2 {
        score += 0.6 * (item_size / 2 - post_residual) as f64;
    }

    // Lookahead: reward residuals that can still host the next item; penalize
    // residuals that almost-but-don't fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 1.5;
        } else if post_residual + next_item_size > bin_capacity {
            // next item cannot fit even in an empty bin region; neutral
        } else {
            // just misses next item: dead space risk
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64; // low mean residual => crowded bins
        // Penalize new bins generally, less so when open bins are nearly full.
        score += 3.0 + 6.0 * (1.0 - crowded) - 2.0 * progress;
        // If many bins can fit the item, definitely avoid opening a new one.
        if fitting_bins_count > 2 {
            score += 3.0 * (fitting_bins_count as f64 - 2.0);
        }
    } else {
        // Mild reward for consolidating into bins that are already partially filled
        // relative to the fleet average (reduce bin count pressure).
        if (bin_residual as f64) < mean_residual {
            score -= 0.5;
        }
        // Prefer using bins when few are open (avoid bin proliferation early).
        if open_bins_count < 4 {
            score -= 0.8;
        }
    }

    // Time-horizon modulation: late in the stream, prioritize closing out bins
    // tightly; early on, keep flexibility (slight penalty on very tight fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual < 10 && post_residual > 0 {
        score += 1.0; // keep some flexibility early
    } else if progress > 0.7 {
        score -= 0.5 * tightness; // squeeze harder late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 4.0 * norm_pr * (1.0 - progress) * (progress * (1.0 - progress) * 4.0);
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (2.0 + 6.0 * progress);
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 5.0 * progress;
    }
    // lookahead: penalize wasting space needed by next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 1.5 * ((nxt - pr) / cap);
        }
    }
    // new-bin candidate: prefer opening early when open bins are fragmented
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score += 4.0 * (mean_residual / cap) * (1.0 - progress);
        score -= 6.0 * progress * (1.0 - (mean_residual / cap));
        if fitting_bins_count <= 2 {
            score -= 2.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "usable slots"
    // for common small-item classes (multiples of 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 22.0; }
        else if pr % 25 == 0 { bonus += 14.0; }
        else if pr % 20 == 0 { bonus += 12.0; }
        else if pr % 10 == 0 { bonus += 8.0; }
        // small dead space is worse than large usable space
        if pr < 10 { bonus -= 18.0; }
        score -= bonus;

        // Integer-division thresholds: residual bucket quality
        let bucket = pr / 10; // 0..10
        score += (bucket as f64 - 5.0) * -0.5; // mildly favor mid/large residuals
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact or near-exact chaining is excellent
            if pr == next_item_size { score -= 45.0; }
            else if pr - next_item_size < 10 { score -= 25.0; }
            else { score -= 10.0; }
        } else {
            score += 8.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current item leaves awkward residue or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = if post_residual < 10 { 1.0 } else { 0.0 };
        score = 40.0 + 20.0 * progress + 25.0 * awkward - 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // fresh bin can chain large items
        }
    }

    // Fragmentation penalty relative to mean residual across open bins
    if bin_residual != bin_capacity {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range).
    // Gaps below 10 are almost certainly wasted; gaps below next_item_size are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0; // gap can't fit the known next item
    }

    // Reward tight fits (low post_residual relative to capacity) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus: exact closure of the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    // The new-bin candidate has bin_residual == bin_capacity, so penalize it via
    // a term proportional to open_bins_count applied to large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (10.0 + 2.0 * open_bins_count as f64 * (0.5 + progress));

    // Mild preference for bins below mean residual (spread load into emptier bins
    // when many are open, but only when fit quality is comparable).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Lookahead: if next item fits snugly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_ratio = next_item_size as f64 / post_residual as f64;
        if gap_ratio > 0.7 {
            score -= 12.0 * gap_ratio; // near-perfect chaining fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        // Perfect 2-step chain: item now + next item fills bin exactly
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residual too small for next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Bonus if post_residual can still hold next item (keeps bin useful)
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Relative to mean residual: bins already below mean residual are "tighter" — prefer filling them
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper; late, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If next item is large, a fresh bin is more valuable
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Many open bins: discourage spreading, prefer consolidation
    score += open_bins_count as f64 * 0.5;

    // Mild penalty for very small unusable post-residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

