    score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin, more so as stream progresses,
    // but allow it when mean residual of open bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * progress;
        if mean_residual < 20.0 {
            score -= 25.0; // open bins are nearly full; a fresh bin is fine
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let npr = pr / cap;
    let nis = item_size as f64 / cap;
    let nnext = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    score += 12.0 * npr * npr * (0.5 + progress) - 8.0 * npr * progress * (1.0 - progress);

    // Reward near-exact fits with a smooth quartic valley
    score -= 10.0 * (1.0 - npr).powi(4) * (0.5 + nis);

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let gap = (npr - nnext).abs();
        score -= 6.0 * (1.0 - gap) * (1.0 - gap) * nnext * (1.0 - progress);
        score += 4.0 * gap * gap * nnext;
    }

    // Last-chance bonus: smooth penalty when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0 * (1.0 - progress);
    }

    // Mean-residual divergence penalty (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild open-bin pressure
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * npr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect: dead space below min item size
    } else {
        // Penalize leftovers that no future item can cleanly use.
        // Items are 1..100; leftover divisible by common denominators is reusable.
        let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 20 == 0);
        if reusable {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Harmonic class via integer division thresholds on post_residual.
        let class = post_residual / 10; // 0..=9 harmonic class
        score += class as f64 * 1.5;
    }

    // Fraction of capacity consumed by this placement; reward high fill ratio.
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Lookahead coupling: if next item fits the post_residual exactly or well,
    // this placement is part of a good chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 18.0;
            } else {
                score -= (gap as f64).recip() * 10.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 4.0;
            // modulo-harmonic: leftover leaves a "bad class" for the next item
            if post_residual % next_item_size.max(1) > 0 && post_residual >= next_item_size {
                score += 2.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If many open bins already exist, discourage more.
        score += open_bins_count as f64 * 0.8;
    }

    // Mean-residual coupling: if this bin is far below average residual,
    // filling it harmonizes the pool; if far above, using it creates outliers.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 10.0;

    // Slight preference for bins with small residual overall (best-fit flavor).
    score += (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are never truly "dead", but gaps that can't hold
    // the lookahead item are wasted if the lookahead would otherwise fit.
    // Penalize small-but-nonzero gaps superlinearly (hard-to-fill slivers).
    let pr = post_residual as f64;
    if post_residual > 0 {
        let sliver = if post_residual < 10 { 3.0 } else if post_residual < 25 { 1.5 } else { 0.0 };
        score += sliver * (10.0 - (post_residual.min(10) as f64)) * 0.5;
    }

    // Reward tight fits: exact or near-exact fills.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 12.0;
    if post_residual == 0 {
        score -= 25.0; // perfect closure is always excellent
    }

    // If the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // lookahead still fits here
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0; // dead sliver that blocks the lookahead
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, mild pressure keeps options open
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: discourage scattering across many open bins,
    // but relax it late in the stream when closing bins out matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = 2.0 * (1.0 - 0.5 * progress);
    score += pressure * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is below the mean (consolidate fullness).
    score += 0.3 * (mean_residual - pr).max(-50.0).min(50.0);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by how crowded/filled
        // existing bins are and stream progress.
        let mut new_cost = 18.0 + 3.0 * open_bins_count as f64;
        if progress > 0.8 {
            new_cost -= 6.0; // late stream: fresh bins absorb tail waste
        }
        if next_item_size > 0 && next_item_size >= bin_residual.min(item_size + post_residual) && post_residual < next_item_size {
            new_cost -= 10.0; // current bin can't host the lookahead; fresh space helps
        }
        score += new_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let pr = post_residual as f64;
    score = pr * 1.0;

    // Strong reward for near-perfect fits.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() <= 1.0 {
            score -= 80.0; // chain: this bin will be perfectly filled next step
        } else if nxt <= pr {
            score -= 25.0; // next item still fits after this placement
        } else {
            // next item won't fit: residual becomes dead space unless tiny
            if pr > 20.0 {
                score += 15.0;
            }
        }
        // Relative lookahead vs mean residual: bin with residual matching next item
        // among low-mean-residual bins is extra attractive.
        if nxt <= pr && pr < mean_residual {
            score -= 10.0;
        }
    }

    // Penalize creating large dead space relative to mean residual.
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual - 20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, mildly penalize this bin if fit is loose.
        if post_residual > 15 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (post_residual would leave big dead space) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // A fresh bin has post_residual = capacity - item_size; make it unattractive
        // unless it would be a tight relative fill or no good open bin exists.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.85 {
            score -= 50.0; // large item: fresh bin is natural
        } else {
            score += 45.0 + 30.0 * (1.0 - progress); // discourage spreading early
        }
        // If next item is small and current item leaves lots of space, fresh bin
        // can be good for pairing.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size && fill_ratio > 0.5 {
            score -= 20.0;
        }
    }

    // Mild preference for consolidating into fewer bins.
    if open_bins_count > 3 && post_residual <= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
