    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / (bin_capacity as f64);
        // Prefer opening a new bin when existing residuals are very small (fragmented)
        if avg_waste < 0.15 {
