        }
        // Early in stream, opening new bins is cheaper; late, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // Many open bins: discourage opening more
        score += 1.5 * (open_bins_count as f64).sqrt();
    }

    // Penalize leaving residuals that are small but nonzero (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference to spread load when mean residual is large
    if (post_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
