    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0 * (0.5 + progress);
    // Reward tight fits: subtract if post_residual is small
    score -= 20.0 * (-post_residual as f64 / 15.0).exp();
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
