    match class {
        0 => score -= 30.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 6.0,
        4 | 5 => score += 3.0,
        6 => score += 8.0,
        7 | 8 => score += 18.0,
        _ => score += 26.0,
