    // Integer-division thresholds: residual that cannot hold next item is dead space.
    if next_item_size > 0 && pr < next_item_size {
        score += 10.0 + 0.2 * (next_item_size - pr) as f64;
    } else if next_item_size > 0 && pr >= next_item_size {
        // Residual can host the lookahead item: strong reward, scaled by leftover quality.
        let after_next = pr - next_item_size;
        score -= 8.0 + 0.1 * after_next as f64;
    }

    // Capacity fractions: penalize leaving more than half the bin as residual.
    let half = bin_capacity / 2;
    if pr > half {
        score += 0.15 * (pr - half) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

