        let poor_fit = if next_item_size > 0 {
            (item_size as f64 / bin_capacity as f64) < 0.35 && open_bins_count > 2
        } else {
            false
        };
        if poor_fit {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
