    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Medium gaps (10..=20) are only useful for small items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }
    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Reward tight fits relative to the bin (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac) * 15.0;

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open, to avoid fragmentation across the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement; if next item would leave this bin hopeless anyway, neutral.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the residual; residual becomes dead space.
            score += post_residual as f64 * 0.8;
        }
    }

    // New-bin candidate: baseline positioning. A fresh empty bin is attractive
    // only when the best existing fit is bad (large post_residual) or few bins open.
    if bin_residual == bin_capacity {
        // Penalty that grows with how well existing bins could fit is implicit:
        // existing bins with small post_residual already score low.
        score += 55.0 - mean_residual * 0.3;
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
        // Late in the stream, opening new bins is more costly.
        score += progress * 20.0;
    }

    // Mild pull toward bins with residual close to item (best-fit core).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.5;
            // Perfect chain: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here after placement; penalize wasted residual
            score += post_residual as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += post_residual as f64 * 0.2;
    }

    // Compare against mean residual: bins below mean residual are "denser" — prefer them
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, especially late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        // Allow new bin only if it enables a perfect chain with next item
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 45.0;
        }
    }

    // Prefer filling nearly-full bins as open bin count grows
    score += (open_bins_count as f64).ln().max(0.0) * tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * fill_ratio * fill_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is unusable.
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item,
    // reward residuals that can (chain placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if the leftover also leaves room for something after the next item.
            if post_residual >= next_item_size + 10 {
                score -= 6.0;
            }
        } else {
            // Waste proportional to how badly the next item misses this residual.
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive early when few bins
    // exist, cheaper later when many bins are open but residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual / (bin_capacity as f64)).min(1.0)
        } else {
            0.0
        };
        // Base cost of a fresh bin.
        let mut new_bin_cost = 30.0;
        // Early in the stream, prefer consolidating into open bins.
        new_bin_cost += 25.0 * (1.0 - progress);
        // If open bins are fragmented (low mean residual), a fresh bin is more attractive.
        new_bin_cost -= 20.0 * (1.0 - fragmentation);
        // If many bins are open but none fit well, allow opening.
        if open_bins_count > 3 && fragmentation < 0.25 {
            new_bin_cost -= 10.0;
        }
        // Never open a new bin when the item would fit almost exactly elsewhere.
        if fill_ratio > 0.9 {
            new_bin_cost += 100.0;
        }
        score += new_bin_cost;
    }

    // Slight penalty for spreading items across many bins when residuals are similar.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward small post_residual (tight fit) with non-linear shaping.
    let mut score = (x * (2.0 - x)).powf(1.5) * cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, tighter fits matter more (less room to recover).
    let coupling = x.powi(2) * (1.0 - x).powi(2);
    score += coupling * cap * (0.5 + 2.0 * progress);

    // Penalize dead space relative to mean residual of open bins (smooth).
    score += 0.3 * (pr - mean_residual).abs().powf(1.25) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space that still fits the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - slack.powi(2)) * 8.0;
    } else if next_item_size > post_residual {
        // penalize stranding the next item in this bin
        score += 3.0 + 5.0 * progress;
    }

    // Mild pressure against hoarding many open bins, smooth in progress.
    score += 0.05 * (open_bins_count as f64) * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - x.abs()) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions
    let frac = (item_size as f64) / (bin_capacity as f64);
    let item_class = (frac * 4.0).floor() as u32; // 0..3 harmonic class

    // Reward tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that no plausible item can fill: residuals in
    // awkward integer-division bands (1..9) are nearly unusable.
    if post_residual >= 1 && post_residual <= 9 {
        score += 15.0;
    }

    // Harmonic coupling: post_residual divisible by small integers is
    // more likely to be filled by future items -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        } else if post_residual % 3 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
        // If next item cannot fit here, mildly penalize (bin becomes dead-end)
        if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline;
    // only attractive when open bins are fragmented or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0;
        score -= 20.0 * frac; // large items justify new bins
        score -= 10.0 * fragmentation / bin_capacity as f64;
        score -= 15.0 * (1.0 - progress); // early stream: new bins cheap
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins whose residual is close to the item
    // (best-fit flavor), scaled by harmonic class.
    score -= 5.0 * item_class as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Avoid accumulating many nearly-empty bins when mean residual is high
    if (bin_residual as f64) > mean_residual + 20.0 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Penalize any post_residual that is too small to be useful later.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 * (1.0 - post_residual as f64 / min_useful as f64);
    }

    // Perfect fits are gold: strongly reward zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving exactly enough room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // The leftover gap cannot host the next item: penalize proportionally.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight-fit reward: the item fills most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or
        // the mean residual of open bins is very small (all nearly full).
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 15.0 + 2.0 * pressure as f64;
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 12.0; // all open bins nearly dead: open a fresh one
        }
        if progress > 0.9 && open_bins_count > 0 {
            score += 10.0 * progress; // late in stream, avoid sprawl
        }
    } else {
        // Existing bin: reward using bins, more so when many are open.
        score -= 1.5 * (open_bins_count as f64).sqrt();
        // Last-chance bin: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Prefer bins whose residual is below average (more filled bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 12.0 - gap.min(12.0); // next item still fits here
        } else {
            // next item won't fit: post_residual becomes potential dead space
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are worth filling
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.25;

    // Last-chance bonus: only bin that fits -> avoid opening new bin wastefully
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize new-bin candidate so it's chosen only when lookahead/fit logic favors it
    if bin_residual == bin_capacity {
        score += 15.0;
        // but allow new bin if no open bin chains well with next item
        if next_item_size > 0 && post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream pressure: consolidate into fewer bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Waste ratio: fraction of bin capacity left unused after placement
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Perfect fit bonus: reward near-zero post residual strongly
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot fit here; penalize proportionally to the gap
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: can afford to be picky, penalize mediocre fits
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0) * waste;
    }

    // Global state: if mean residual across open bins is large, we have slack
    // and can be selective; tighten scoring toward best fits.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, opening new bins is cheap-ish (future
    // items can fill them); late in the stream, consolidate aggressively.
    let new_bin_penalty = 10.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a decent existing fit,
        // but below a very poor fit.
        score += new_bin_penalty;
        // A new bin is attractive for large items that leave a usable remainder
        if item_size >= 50 {
            score -= 8.0;
        }
    }

    // Slight preference for filling bins that are already more full
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild open-bins pressure: many open bins -> favor compacting into them
    score += 0.3 * open_bins_count as f64 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let fill = it / cap;

    // base: waste after placement, damped non-linearly
    let mut score = norm_pr * norm_pr * cap * (1.0 + 2.0 * progress * (1.0 - progress) * 4.0);

    // reward tight fits: cubic coupling of fill ratio with progress
    score -= fill * fill * fill * cap * (0.5 + progress);

    // penalize dead space in mid-range residuals (unusable for typical items)
    let mid = (norm_pr - 0.3) * (norm_pr - 0.3);
    score += mid * cap * 0.6 * (1.0 - progress);

    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_quality = ni / pr.max(1.0);
            score -= 6.0 * fit_quality * (1.0 - fit_quality) * 4.0;
        } else {
            score += 2.0 * (ni - pr) / cap;
        }
    }

    // new-bin candidate: prefer opening a bin early/late depending on open bins pressure
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score = cap * 0.9 - 20.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // mild preference for bins below mean residual (balance residuals)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let fraction = post_f / cap_f; // in [0,1]

    // Dead-space penalty: tiny leftovers (< 10, unusable by smallest item class) are worst
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic classes: reward post_residuals that are "harmonic" with common item sizes
    // (multiples of 5 and 10 are more likely to be exactly filled later)
    let harmonic = (post_residual % 10 == 0) as i32 + (post_residual % 5 == 0) as i32;
    score -= harmonic as f64 * 6.0;

    // Quarter-class bonus: leftovers near capacity fractions 1/4, 1/2, 3/4 are useful targets
    let q = (post_residual as f64 * 4.0 / cap_f).round() as i32;
    let near_quarter = ((post_f - (q as f64) * cap_f / 4.0).abs() < 2.0) as i32;
    score -= near_quarter as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits with small slack: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap_f) * 8.0;
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize large unusable leftovers
        score += (post_f - cap_f * 0.5).max(0.0) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current bin
    // would leave a bad harmonic class or when bins are scarce
    if bin_residual == bin_capacity {
        let base = 15.0;
        // penalize opening new bin when current placement is good (post_residual harmonic)
        let penalty = harmonic as f64 * 10.0 + (post_residual == 0) as i32 as f64 * 20.0;
        // reward opening a new bin if the item is huge and would strand current bin
        let big_item = (item_size as f64 / cap_f > 0.7) as i32 as f64 * 12.0;
        score = base - penalty + big_item;
    }

    // Mild global pressure: as stream progresses, discourage proliferating open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64 - mean_residual / cap_f * 4.0).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for typical future items.
    let dead_threshold = 10.0f64; // gaps below smallest conceivable item are pure waste
    if (post_residual as f64) < dead_threshold {
        score += 25.0; // hard penalty for creating a fully dead gap
    }

    // Soft penalty: gaps in the awkward 1..=20 range are hard to fill later.
    if post_residual > 0 && post_residual <= 20 {
        score += (21 - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; if it cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            if next_item_size == post_residual {
                score -= 8.0; // perfect chain fit
            }
        } else {
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage scattering across many open bins,
    // but keep pressure moderate so bad fits are still avoided.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make opening a new bin costly by default so it only
    // wins when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is already small (tight packing).
        score += (bin_residual as f64) * 0.05;
    }

    // Mean-residual coupling: when open bins are generally loose, tighten selection.
    score += (mean_residual - post_residual as f64) * 0.1;

    // Slight progression term: later in the stream, be more conservative
    // about opening bins (fewer chances to consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let match_gap = (pr - nr).abs();
        if pr >= nr {
            // Next item fits perfectly -> strong reward.
            score -= 40.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize proportionally to wasted lookahead.
            score += 0.5 * match_gap;
        }
        // Coupling with mean residual: prefer bins whose post_residual deviates favorably.
        score += 0.3 * (pr - mean_residual);
    } else {
        // Last item: pure tightness packing.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize creating tiny dead space that nothing (min size 1..100) can use.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 0.8 * (item_size.min(50) - post_residual) as f64;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage opening new bins when decent fits exist,
    // but allow it if the current item is huge relative to residuals.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * mean_residual;
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Late-stream consolidation: tighten packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            if post_residual >= next_item_size { 0.0 } else { (post_residual - next_item_size).min(post_residual) as f64 }
        } else {
            post_residual as f64
        };
        score += 0.8 * dead;
    }

    // Lookahead coupling: reward bins whose residual can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins generally (best-fit flavor scaled by stream progress).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    // Penalize bins far from mean residual (keep residual profile homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the open-bin population is already fragmented.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score = 55.0
            + 2.0 * open_pressure
            - 30.0 / fit_pressure
            - 15.0 * progress
            + if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        // Discourage opening a new bin when next item could share this one's fresh space.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Mild fragmentation penalty for very small unusable residuals late in stream.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = 1.0 - (pr / cap); // how full the bin becomes

    // Reward tight fits with smooth polynomial coupling to stream progress
    let tightness = (fit_ratio * fit_ratio) * (1.0 + 3.0 * progress);
    score -= 18.0 * tightness;

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = nx - pr;
            score += 6.0 * (gap / cap) * (1.0 + 2.0 * progress * (1.0 - progress) * 4.0);
        } else {
            // reward bins that can also host the next item
            let slack = (pr - nx) / cap;
            score -= 4.0 * slack * (1.0 - slack) * (1.0 + progress);
        }
    }

    // Penalize leaving residuals in the awkward mid-range (unusable zone)
    let mid = pr / cap;
    score += 8.0 * (mid * (1.0 - mid) * 4.0 - 0.5).abs() * (1.0 - progress);

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer it early, penalize it when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) - 12.0 * progress;
    } else {
        // Mild preference for bins below mean residual (balance load)
        score += 0.05 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with dead-space penalty for tiny residuals (harmonic classes).
    if post_residual > 0 {
        let class = post_residual % 10; // modulo class of leftover
        score += match class {
            0 => -6.0,          // perfectly aligned leftover, reusable
            1..=3 => 8.0,       // near-dead space, hard to fill
            4..=6 => 2.0,
            _ => 0.0,
        };
    } else {
        score -= 12.0; // perfect closure is excellent
    }

    // Harmonic fraction of capacity used by the item (integer division thresholds).
    let usage_class = (item_size * 4) / bin_capacity; // 0..=4 quarters
    score -= 3.0 * usage_class as f64;

    // Lookahead coupling: reward bins whose post_residual matches next item size class.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 10.0 / (1.0 + diff as f64);
        if next_item_size <= post_residual {
            score -= 4.0; // chain placement possible
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 10.0; // an open bin already accommodates it well
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..~12)
    // are nearly unusable "dead space" — penalize them heavily.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus: strongly reward near-zero post residual.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Post residual can't fit next item: mild penalty scaled by gap size.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: when many bins are open, favor filling existing ones
    // (penalize opening new bins / spreading items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad.
    // Base penalty so a new bin only wins when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        // If mean residual across open bins is small (they're mostly full),
        // opening a new bin is more acceptable.
        if mean_residual < 15.0 {
            score -= 35.0;
        }
    }

    // Mild preference for bins with tighter current residual (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact chain fits (item then next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the chain fit is
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // penalize leftover that no typical item can use (small dead space)
            if slack > 0.0 && slack < 10.0 {
                score += 15.0;
            }
        } else {
            // next item cannot follow into this bin; penalize proportionally to shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 10.0 + shortfall * 0.3;
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 20.0;
    }

    // Prefer bins whose residual is tighter than average (good fits), punish loose fits.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 { post_residual < next_item_size } else { false };
        let pressure = if bad_fit { 1.0 } else { 0.0 };
        score = 100.0 - 80.0 * pressure + 0.5 * open_bins_count as f64 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score = 10.0; // no alternative, new bin fine
        }
    }

    // Mild preference to keep residual divisible-ish for future items (avoid tiny remainders).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared waste penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < 10 {
            // creates small dead space next item can't use
            score += 6.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when current bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // penalize new bin, discount penalty when few fitting bins or large item
        score += 40.0 - 10.0 * (fitting_bins_count as f64) - 0.05 * item_size as f64 - 5.0 * progress;
        let _ = crowding;
    }

    // Mild preference for keeping number of open bins low early on
    score += (open_bins_count as f64).sqrt() * 0.5 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with a mild convexity so
    // very small residuals are extra attractive.
    let mut score = post + 0.35 * (post * post) / cap;

    // Non-linear coupling of post_residual with stream progress: early on,
    // larger residuals are acceptable (bins can still be filled later); late
    // in the stream, dead space is increasingly costly.
    score += 0.9 * progress * (post / cap) * (1.0 - (post / cap));

    // Penalize residuals that cannot fit the lookahead item (smooth logistic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = post - nxt;
        let s = fit / (0.5 * cap);
        score += 6.0 * (1.0 - 1.0 / (1.0 + (-s).exp())) * (0.5 + 0.5 * progress);
        // Bonus if post_residual matches next item size closely (smooth).
        let closeness = (post - nxt).abs() / cap;
        score -= 2.0 * (1.0 - closeness.min(1.0)) * (1.0 - (closeness * 4.0).min(1.0));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Discard spreading across many open bins slightly; encourage consolidation
    // when mean residual is small relative to this bin's post residual.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);
    score -= 0.5 * ((mean_residual - post) / cap).max(0.0);

    // New-bin candidate: residual equals capacity. Penalize opening a new bin
    // smoothly, more so early in the stream; relax late when open bins are full.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).min(1.0);
        score += 12.0 * (1.0 - 0.5 * progress) * (1.0 - 0.6 * crowding);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "reusable"
    // residue classes (multiples of 10, small slivers) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly favored
    } else if pr % 10 == 0 {
        -12.0 // leftover is a round class, reusable by common item sizes
    } else if pr < 10 {
        8.0 // dead space sliver: penalize
    } else {
        0.0
    };
    score += class_bonus;

    // Modulo-5 secondary class: leftovers divisible by 5 are semi-reusable.
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // this placement chains perfectly; if next item cannot ever fit, leftover
    // is likely dead.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - 0.15 * slack;
            // harmonic class of chained leftover
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad
    // fit unless the fit is actually tight.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Tightness term: reward small post residuals non-linearly.
    score += 0.05 * (pr as f64).powi(2) / bin_capacity as f64;

    // New-bin candidate: only attractive when the item is large relative to
    // typical residuals or existing bins are highly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if item_size as f64 > mean_residual { 1.0 } else { 0.4 };
        score -= 20.0 * pressure * (0.5 + progress) - 0.1 * fragmentation;
        // Harmonic class of item itself: sizes near multiples of 25 pack
        // cleanly into fresh bins.
        if item_size % 25 == 0 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // worst for tiny gaps
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the smallest plausible item (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward bins whose post-residual can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // lookahead can't use the leftover either
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow spreading.
    let pressure = open_bins_count as f64 * 2.0;
    score += pressure;

    // New-bin candidate: residual == capacity. Only attractive when current bins
    // would create dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins open or fit is bad.
        score = (bin_capacity - item_size) as f64 + 30.0;
        if post_residual < 10 {
            score -= 20.0; // opening fresh avoids dead space
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if open_bins_count > 6 {
            score += 10.0; // too many open bins already
        }
    } else {
        // Reward good tightness relative to residual.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 20.0;
    }

    // Slight preference to use bins with below-average residual (denser bins).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for post-residual that exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Reward if next item fits into the post-residual at all.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else {
        // Dead space: post-residual too small for the next item.
        score += 8.0;
    }

    // Penalize large leftover dead space relative to mean residual.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.35 * (pr - mean_residual);
    } else {
        score -= 0.15 * mean_residual;
    }

    // Penalize tiny unusable post-residual (wasted space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative to capacity
    // or open bins are very full (mean residual low), so we don't fragment space.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0; // base cost of opening a new bin
        if item_frac > 0.7 || (next_item_size > 0 && (item_size + next_item_size) as f64 > 0.95 * bin_capacity as f64) {
            score -= 40.0; // opening fresh is worthwhile for big items / perfect pair
        }
        if mean_residual < item_size as f64 {
            score -= 15.0; // existing bins are too full anyway
        }
        score -= 0.05 * open_bins_count as f64;
    }

    // Slight late-stream tightening: prefer compacting into existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild penalty spread over many fitting bins to encourage consolidation.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is too small for next item, penalize dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.15 * slack; // leftover after chaining
        } else {
            // post_residual unusable for next item: dead space penalty
            let waste = post_residual as f64;
            score += 0.25 * waste;
        }
    }

    // Global state: prefer filling bins when many are open (consolidation pressure).
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 1.5 * pressure * fit_ratio;

    // Mean residual coupling: penalize bins whose residual deviates far below mean
    // (they are the "hardest to fill" — better to place here than leave stranded).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev;
    }

    // Time horizon: early in stream, keep bins flexible (mild penalty on very tight fills);
    // late in stream, pack aggressively (reward tight fills more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate: baseline score for opening a fresh bin; only chosen if
    // no open bin offers a decent fit. Scale with progress (later => cheaper to open).
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalize post-residual relative to capacity
    let r = pr / cap;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, larger residuals are acceptable; later, penalize them more steeply
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * (r * r * cap);

    // Reward tight fits (small post-residual) with a non-linear bonus
    score -= (1.0 - r) * (1.0 - r) * item_size as f64 * 0.3;

    // Penalize dead space that no typical item can use, smoothed by mean residual coupling
    let mean_r = mean_residual / cap;
    score += 2.0 * r * r * (1.0 - mean_r);

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt).abs();
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            score += 1.5 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * t;
    }

    // Many open bins: prefer filling existing ones over opening new ones
    score -= 0.05 * open_bins_count as f64 * (1.0 - r);

    // New-bin candidate: mildly penalize so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) are golden,
    // tiny residuals are dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score += 150.0;
    } else if post_residual <= 10 {
        score += 40.0;
    }

    // Modulo classes on post_residual: residuals divisible by common small
    // item sizes (5, 10, 20, 25) are reusable "harmonic" leftovers.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 5 == 0 { score -= 12.0; }
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 || pr % 25 == 0 { score -= 6.0; }
        // Prime-ish / awkward residuals are dead space.
        if pr % 5 != 0 && pr % 10 != 0 && pr % 3 != 0 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if the next item exactly fills post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Harmonic divisibility of leftover w.r.t. next item.
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
            let gap = post_residual - next_item_size;
            if gap <= 5 { score -= 15.0; }
        } else {
            // Next item cannot use this bin's leftover at all.
            score += 8.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a very awkward residual or bin count is low.
    if bin_residual == bin_capacity {
        score += 120.0;
        if post_residual % 10 == 0 { score -= 40.0; }
        if open_bins_count == 0 { score -= 300.0; }
    }

    // Fraction-of-capacity harmonic tiers on post_residual.
    let quarter = bin_capacity as f64 / 4.0;
    let prf = post_residual as f64;
    if prf > 0.0 && prf < quarter * 0.25 {
        score += 30.0; // sliver residual
    }

    // Progress-aware tightening: late in the stream, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // Slight preference to fill bins that are already relatively full.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10, min item size)
    // are pure waste -> heavy penalty. Larger leftovers are less wasteful.
    if post_residual < 10 {
        score += 60.0; // dead space, nothing can ever use it
    } else if post_residual <= 20 {
        score -= 8.0; // small gap likely usable by small items
    } else if post_residual <= 40 {
        score -= 4.0;
    } else {
        score -= 1.0; // big residual is flexible
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones
    // (consolidation); few open bins -> opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // New-bin candidate: baseline cost of opening a fresh bin, adjusted by
    // how poor the alternatives look. If existing bins leave large residuals
    // on average, opening fresh is more attractive.
    if bin_residual == bin_capacity {
        score = 45.0 + pressure - (mean_residual / bin_capacity as f64) * 20.0;
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (creates perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual is smaller than next item but next item is
    // small enough to fit elsewhere easily (mild nudge toward tight fits).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size <= 30 {
        score += 3.0;
    }

    // Prefer bins whose residual is closest to the item (classic best-fit
    // sharpening): tighter fit -> lower score.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 25.0 + post_residual as f64 * 0.5;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly matches
    // the post residual (perfect 2-chain), or when it fits well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect two-item fill of this bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of the chain.
            score -= 20.0 * (1.0 - (pr - nxt) / 100.0);
        } else {
            // Next item cannot fit here: penalize large leftovers that strand the next item.
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    } else {
        // Last item: reward tightest fill.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual is below the mean
    // (tighter bins), gently.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Discard spreading across many bins when few bins can fit the item.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // no open bin offers a good fit; penalize opening new bins mid-stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: bonus proportional to fill ratio.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 20.0 * fill * fill;

    // Penalize dead space: residual too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap; // next item won't fit here
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Global state: if mean residual is high, bins are loose; prefer reusing them.
    score -= 0.05 * mean_residual;

    // Time horizon: early in stream, be more willing to open new bins (flexibility);
    // late in stream, consolidate tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - t) * (post / cap);

    // New-bin candidate: make it competitive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin scores by its full residual; adjust with state.
        score = cap - 15.0 * (1.0 - t) - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit = pr - next_item_size as f64;

    // Base: prefer small post-residual, with non-linear tightening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear dead-space penalty: tiny residuals are nearly unusable
    score += 30.0 * (1.0 - pr_norm).exp() * pr_norm * pr_norm * (1.0 + progress);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if fit >= 0.0 {
            score -= 12.0 * (1.0 - (fit / cap)).min(1.0).max(0.0);
        } else {
            score += 8.0;
        }
        // smooth coupling: post-residual near next item size is ideal
        let diff = (pr - nxt).abs() / cap;
        score += 10.0 * diff * diff * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild pressure relative to mean residual state
    score -= 0.15 * (mean_residual - pr);

    // New-bin candidate: default preference grows late in the stream
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by large
    // powers-of-two / by 10 are more reusable; prime-ish residues are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongest reward
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr % 2 == 0 {
        -1.0
    } else {
        2.0 // odd residue: mildly penalize
    };
    score += harmonic_bonus;

    // Fractional capacity class of post residual (quarters of capacity).
    let q = (pr as f64 / (cap / 4.0)).floor();
    score -= q * 1.5;

    // Lookahead: reward if the next item fits exactly into the post residual
    // (a chained perfect fit), penalize if next item leaves a bad class.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let chain_residual = pr - next_item_size;
            if chain_residual % 10 == 0 {
                score -= 5.0;
            } else if chain_residual % 2 == 1 {
                score += 3.0;
            }
        } else {
            // next item cannot use this bin's remainder; larger residual is wasted
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate detection: empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when existing fits are poor
        // (high mean residual fragmentation) or this is a large item.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let item_frac = item_size as f64 / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 8.0 * fragmentation + 10.0 * (1.0 - item_frac) + 4.0 * progress;
        // If other bins can fit the item, make new bin slightly less attractive
        // unless item is big (would leave small residue elsewhere anyway).
        let others_fit = fitting_bins_count >= 1 && !is_new_bin;
        let _ = others_fit;
        score += cap - new_bin_bonus;
        // exact harmonic tweak: new bin with big item leaves small residue -> good
        if item_size % 10 == 0 {
            score -= 4.0;
        }
    }

    // Prefer filling bins that are already well-used (low residual relative to mean).
    if !is_new_bin {
        let rel = bin_residual as f64 / cap;
        score += rel * 5.0;
        // mild pressure to reduce number of open bins early in the stream
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residuals too small for the smallest item are wasted.
    let dead = (post_residual > 0 && post_residual < 10) as i32;
    score += 60.0 * dead as f64;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize when post_residual is nonzero but just barely below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new one.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // mildly encourage filling existing ones.
    if is_new_bin {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, new bins are more acceptable (avoid overstuffing).
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // A new bin leaves a full residual; that's neutral-ish, but penalize
        // slightly if the item is small (wasteful start).
        score += 0.2 * (bin_capacity - item_size) as f64;
    } else {
        // Favor bins whose residual is close to what we consume (tight packing).
        score -= 0.3 * (bin_residual - item_size) as f64;
    }

    // Global residual context: if this bin's residual is far below mean,
    // using it consolidates small bins (good).
    if !is_new_bin {
        score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect chain: this bin's leftover exactly fits the next item
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits in the leftover: mild reward proportional to tightness
        else if post_residual >= next_item_size {
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / 100.0);
        }
        // Next item does NOT fit: penalize dead space, worse when leftover is small
        else {
            let waste = nxt - post;
            score += 10.0 + 0.5 * waste.min(80.0);
        }

        // If leftover cannot fit next item AND leftover is below the minimum item
        // size (1), nothing more can ever go in: heavy penalty for tiny leftovers.
        if post_residual < 1 {
            score += 100.0;
        }
    } else {
        // Last item: just minimize leftover
        score = post_residual as f64 * 2.0;
    }

    // Relative-to-mean adjustment: bins with residual far below mean are already
    // well-filled; placing here is efficient. Bins above mean are wasteful targets.
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += (bin_residual as f64 - mean) * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_options = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual == bin_capacity as u32);
        // Base cost of opening a new bin
        score += 40.0;
        // But if the item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        if poor_options {
            score -= 50.0;
        }
        // Late in the stream, prefer reusing existing bins slightly more
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Slight penalty when many bins are open: encourage consolidation
    score += 0.3 * open_bins_count as f64;

    // Small tie-breaker favoring tighter fits
    score += (bin_residual - item_size) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below a
    // "useless threshold" is penalized more than proportionally.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly
    // prefer this bin (chained placement).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if ni <= pr {
            let leftover = pr - ni;
            score -= 12.0 * (1.0 - leftover / bin_capacity as f64);
            if leftover == 0.0 {
                score -= 15.0; // exact two-item chain
            }
        } else {
            // Next item cannot follow here: mild penalty proportional to gap.
            score += 4.0 * ((ni - pr) / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Fragmentation guard: penalize leaving residuals that few item sizes can
    // use (residual < 10 is nearly dead space given min item size 1..100, so
    // weight by how small it is).
    if post_residual > 0 && post_residual < item_size {
        score += 2.0;
    }

    // Prefer fuller bins relative to the mean residual: a bin below-mean
    // residual (i.e. already tight) should absorb the item.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // When many bins are open, consolidate into them; when few are open,
    // opening a new bin is cheaper.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Slight preference for the new-bin candidate only when the fit here is
    // very poor (post residual large relative to capacity) and we are early.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 8.0 - progress * 10.0 + waste_ratio * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: polynomial in progress modulating residual penalty
    let w = 0.6 * progress + 0.4 * progress * progress;
    score += 12.0 * w * norm_pr * norm_pr;

    // Dead-space penalty grows as bin gets tight relative to capacity
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strong bonus to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild preference for filling bins below average residual (balance avoidance)
    score += 1.5 * (pr - mean_residual) / cap;

    // New-bin candidate: keep neutral baseline, penalize slightly early, allow late
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: rewards residuals that are
    // "clean" multiples of common item classes (mod 10, mod 20, mod 25).
    let pr = post_residual;
    let harmonious = if pr == 0 {
        60.0 // perfect fit: huge reward
    } else if pr % 10 == 0 {
        25.0
    } else if pr % 20 == 0 || pr % 25 == 0 {
        18.0
    } else if pr % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonious;

    // Dead-space penalty for tiny unusable residues (below smallest class).
    if pr > 0 && pr < 10 {
        score += 30.0 + (10 - pr) as f64;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.7 {
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when the item is large and no
    // existing bin offers a decent harmonic fit.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let base_penalty = 40.0 + 0.25 * (open_bins_count as f64);
        let worth_it = item_size >= 50 && (bin_residual - item_size) % 10 == 0;
        score += if worth_it { base_penalty * 0.4 } else { base_penalty };
    } else {
        // Existing bins: slight preference for bins with smaller residual
        // (best-fit bias) modulated by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.1 * mean_residual * (1.0 - progress);
    }

    // Lookahead: penalize leaving a residue that neither fits the next item
    // nor lands on a harmonic class.
    if next_item_size > 0 && pr > 0 {
        if next_item_size > pr {
            // next item can't use this residue: dead space risk
            score += 8.0;
        } else if pr - next_item_size <= 10 && (pr - next_item_size) % 5 != 0 {
            score += 6.0; // would create a tiny non-harmonic leftover
        } else if pr - next_item_size == 0 {
            score -= 15.0; // sets up a perfect fit next step
        }
    }

    // Integer-division threshold: bins whose residual class index matches
    // the item class get a nudge (same decade family).
    if (bin_residual / 10) == (item_size / 10) + 1 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight-fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is excellent; encourage consolidation.
    score += (open_bins_count as f64) * 0.8 * (1.0 - fill_ratio);

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (best-fit style), penalize outliers.
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.15;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by a tiny dead gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit, or under bin pressure with a large item.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && fill_ratio >= 0.5;
        if decent_fit_exists {
            score += 35.0; // prefer existing bin with decent fit
        } else {
            score -= 5.0; // allow opening a new bin
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 10.0; // big items prefer a fresh bin when many bins open
        }
    }

    // Late-stream tightening: as the stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step chain: subtract heavily to reward
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits after placement: mild reward proportional to fill
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving large unusable gaps
            let gap = next_item_size - post_residual;
            if gap > 0 {
                score += 15.0 * (gap as f64 / bin_capacity as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (denser bins)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Penalize wasting a fresh empty bin when item is small
    if bin_residual == bin_capacity {
        score += 10.0 + item_size as f64 * 0.3;
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 / (1.0 + progress)) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 {
        score -= 6.0; // perfect or near-perfect closure is excellent
    } else if post_residual < 20 {
        score += 2.5; // awkward sliver
    }

    // Lookahead: prefer leaving exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect pairing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (-slack / 25.0).exp(); // leaving usable room for next item is good
        } else {
            // next item won't fit here regardless; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if post_residual >= 10 {
            score -= 8.0 * (1.0 - waste_ratio);
        } else {
            score -= 20.0; // even near-perfect: keep it
        }
    }

    // New-bin candidate handling: opening a bin is expensive; penalize unless
    // the item is large relative to the best available residual usage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_util = 1.0 - mean_residual / (bin_capacity as f64);
        // Favor new bins when existing bins are well packed (open bins are valuable)
        // and late in the stream (fewer future chances to fill leftovers).
        let open_cost = 30.0 + 25.0 * avg_open_util + 15.0 * progress;
        // Discount cost if item is huge (little to gain from squeezing it in).
        let size_relief = 0.35 * item_size as f64;
        score += open_cost - size_relief;
    } else {
        // Mild reward for using existing bins when many are open (consolidation).
        score -= 0.4 * open_bins_count as f64;
        // Prefer bins whose residual deviates productively from the mean:
        // placing into below-mean-residual bins preserves larger cavities elsewhere.
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Time horizon: late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // tight fits matter more as the stream matures.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight * (0.5 + progress);

    // Penalize large post residuals non-linearly (dead space quadratically).
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / (bin_capacity as f64);

    // Lookahead: reward residuals that can host the next item, smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = 1.0 - ((pr - ns) / bin_capacity as f64);
            score -= 6.0 * fit_quality * (0.5 + 0.5 * progress);
        } else {
            score += 3.0 * (ns - pr) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild pressure toward consolidation as open bins accumulate.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize slightly unless residuals across bins are tight.
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        let open_new_bonus = 4.0 * (1.0 - mean_tight) * (0.5 + progress);
        score += 2.0 - open_new_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let harmonic_class = (frac * 10.0).floor() as i64; // 0..10 decile of residual

    // Reward near-perfect fits strongly (post_residual small => low score already),
    // but add a non-linear bonus for exact "harmonic" residuals that other items may fill.
    let perfect = (post_residual == 0) as i64 as f64;
    score -= perfect * 50.0;

    // Harmonic class bonus: residuals that are exact multiples of common item classes
    // (10, 20, 25, 50) are more likely to be filled by future items.
    let harmonics = [10u32, 20, 25, 50];
    let mut harmonic_bonus = 0.0;
    for (i, &h) in harmonics.iter().enumerate() {
        if post_residual > 0 && post_residual % h == 0 {
            harmonic_bonus += 4.0 - i as f64;
        }
    }
    score -= harmonic_bonus;

    // Penalize awkward residuals: small but nonzero dead space (< 10) is unusable
    // since items are >= 1 but small fragments rarely match; penalize decile 1-2.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division threshold: if the bin is exactly half empty, it's a good
    // flexible state; reward it.
    if post_residual == bin_capacity / 2 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial credit if next item fits but leaves a harmonic residual.
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 6.0;
        }
        score += next_post as f64 * 0.3;
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize unless this is the last-chance bin.
        score += 2.0;
    }

    // Last chance: if only this bin can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual, which already
    // scores high; add extra penalty unless the stream is early or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Open a new bin only for very large items or when many bins are already open.
        if item_frac > 0.6 || open_bins_count > 8 || progress < 0.05 {
            score -= 5.0;
        } else {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (i.e., fuller bins) to keep tight packing.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= 2.0;
    } else if mean_residual > 0.0 {
        score += 1.0;
    }

    // Penalize very small leftover fragments modulo 10 (harmonic dead classes).
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fit: small post_residual is good.
    if post_residual > 0 {
        // Penalize "unusable" small gaps: gaps below typical small item threshold (<= 10)
        // are dead space; gaps that exactly fit the next item are valuable.
        if post_residual <= 10 {
            score += 25.0; // dead space penalty
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0; // perfect slot for the lookahead item
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // gap can still host the next item
        } else {
            score += 8.0; // gap cannot host next item: mild penalty
        }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 60.0;
    }

    // Reward filling bins deeply: relative fill fraction.
    let fill_fraction = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_fraction;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins open, slightly encourage using them rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual is tiny dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual <= 10 {
            score += 15.0; // still dead space, soften the bonus
        }
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // in existing bins is poor (large post_residual). Base cost for new bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If lookahead item is large and mean residual is small, opening fresh is fine.
        if next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // Late in the stream, opening a new bin is less costly than dead space.
        if progress > 0.8 && post_residual_would_be_dead(post_residual) {
            score -= 25.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps bin residuals balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

#[inline]
fn post_residual_would_be_dead(post_residual: u32) -> bool {
    post_residual > 0 && post_residual <= 10
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // chain of two perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Relative to mean residual: prefer bins that tighten the mean (best-fit bias).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize so we only open when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        // Opening a bin is attractive for huge items with no good home.
        if item_size > 60 && (fitting_bins_count == 0 || post_residual as f64 > mean_residual) {
            score -= 80.0;
        }
    }

    // Late-stream consolidation: favor existing bins more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize very small dead space that is hard to reuse (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or many bins open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when open bins score badly.
        score += 35.0;
        // Late in the stream, prefer compacting into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If several bins fit, discourage opening another.
        if fitting_bins_count > 2 {
            score += 15.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Large items (bad fit anywhere) justify a fresh bin.
        if item_size > 60 {
            score -= 20.0;
        }
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size < 30 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (use emptier bins).
        score += 0.15 * (mean_residual - bin_residual as f64);
        // Prefer using bins with small residual to consolidate.
        if bin_residual < 40 {
            score -= 5.0;
        }
        // Many open bins: consolidate aggressively.
        if open_bins_count > 8 {
            score -= 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening.
    let mut score = pr_norm * pr_norm * 120.0 + pr_norm * 40.0;

    // Smooth interaction: as stream progresses, penalize wasted residual more strongly.
    let progress_coupling = progress * pr_norm * pr_norm * 90.0;
    score += progress_coupling;

    // Reward tight fits (post_residual small) increasingly with item size.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (item_size as f64 / cap) * 60.0;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 55.0 + 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = (pr - nxt) / cap;
            score -= 30.0 * (1.0 - slack_after_next) * (1.0 - slack_after_next);
        } else {
            let overflow = (nxt - pr) / cap;
            score += 25.0 * overflow * overflow;
        }
    }

    // Mean residual context: penalize bins far below mean residual (fragmenting).
    let dev = (mean_residual - pr) / cap;
    score += dev.abs() * dev.abs() * 15.0;

    // Mild preference for consolidating into fewer bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tightness;

    // Slight bias against opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" a slot it leaves.
    // Residuals that are exact multiples of common item sizes (or near multiples)
    // are reusable; odd fragments are dead space.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable_bonus = 0.0f64;
        for &s in &[10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if pr >= s {
                let r = pr % s;
                if r == 0 {
                    reusable_bonus += 6.0;
                } else if r <= 5 {
                    reusable_bonus += 3.0;
                }
            }
        }
        score -= reusable_bonus;
    } else {
        // Perfect fill: strongest reward.
        score -= 30.0;
    }

    // Integer-division threshold: penalize leaving a fragment that is too small
    // for the smallest plausible item (dead space) relative to capacity fraction.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.10 {
        score += 15.0 * (0.10 - frac) / 0.10;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 12.0;
            } else {
                score -= 8.0 / (1.0 + gap as f64 / 20.0);
            }
        } else {
            // next item won't fit here; slight penalty scaled by overflow
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Best-fit pressure among many candidates handled by base score;
        // mild extra differentiation by tightness of fit.
        score += (bin_residual - item_size) as f64 * 0.02;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // residuals are all poor (mean residual small) or stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 22.0 - 10.0 * (1.0 - mean_residual / cap).min(1.0);
        if progress < 0.2 {
            score -= 6.0; // early stream: opening bins is cheap
        }
    }

    // Mean-residual context: when open bins are collectively roomy, prefer
    // consolidation into them (penalize new bins implicitly via above).
    if mean_residual > 0.5 * cap && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Modulo-16 harmonic nudge on post residual for tie-breaking diversity.
    score += (pr % 16) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold
    // typical items (<= 10) are nearly worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward tight fits (post_residual near zero) with a nonlinear bonus.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Perfect-fill lookahead: if the next item exactly consumes the
    // remaining post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        let nxt_waste = post_residual - next_item_size;
        if nxt_waste < 10 {
            score += 8.0; // next item would leave a dead gap here
        } else {
            score -= 10.0; // next item keeps this residual productive
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer packing into
    // existing bins over opening new ones.
    score += 3.0 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin has bin_residual == capacity.
    // Only allow opening a new bin when existing residuals are all poor
    // fits (item leaves large dead space everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_everywhere = mean_residual < item_size as f64 * 1.15;
        if poor_fit_everywhere || open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 45.0 + 20.0 * progress; // opening a new bin is good
        } else {
            score += 55.0; // discourage wasting a fresh bin on a decent fit
        }
    }

    // Mild preference for bins with residuals close to the mean
    // (keeps bin states homogeneous, easier to combine later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual can still host the next item: strong reward, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.25;
    }
    // Post-residual too small for next item: dead space penalty, worse if very small.
    else if next_item_size > 0 && post_residual > 0 {
        let deadness = 1.0 - (post_residual as f64 / next_item_size as f64).min(1.0);
        score += 15.0 * deadness;
    }

    // Reward tight fits overall (small post residual relative to bin capacity).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strong penalty for opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins below mean residual (keeps large residuals available).
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item is huge and nothing fits well, opening fresh is fine.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            score -= 8.0;
        }
    }

    // Late in stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight packing: the fuller the bin after placement, the better.
    score -= (1.0 - post / cap) * 20.0;

    // Penalize tiny unusable dead space (worse than a perfectly full or roomy bin).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 0.6;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead (k=2): reward leaving room for the next item, penalize stranding it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0;
        } else if post > 0.0 {
            score += (nxt - post) * 0.3;
        }
    }

    // New-bin candidate: base penalty so we only open when justified.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no open bin truly fits, opening is the right call.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items are hard to place later; give them fresh bins more readily.
        if item > cap * 0.5 {
            score -= 10.0;
        }
        // Early in the stream we can afford more bins (exploration).
        score -= (1.0 - t) * 10.0;
        // If mean residual is large, existing bins have plenty of room; discourage new bins.
        score += (mean_residual / cap) * 15.0;
    }

    // Mild best-fit pressure: prefer bins whose residual is close to the item.
    score += (residual - item).max(0.0) * 0.05;

    // Prefer bins tighter than the average open bin.
    if residual < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
