    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 30.0 * poly * (0.5 + progress);
    // penalize dead space that is too small for typical future items
    score += 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 6.0;
        }
    }
    // mild preference for concentrating fills when many bins are open
    score += 0.5 * (mean_residual - pr) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue relative to capacity fractions.
    let cap_frac = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead space classes: post_residual in (0,10) is nearly unusable (min item 10).
    if post_residual > 0 && post_residual < 10 {
