    }
    // Perfect fit: no residual left.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Integer division thresholds: which "harmonic" band does post_residual fall in?
    let band = post_residual / 10; // 0..10 bands
    match band {
        0 => score += 25.0,           // 0-9: mostly dead
        1 => score += 8.0,            // 10-19: only tiny items fit
        2 | 3 => score -= 3.0,        // 20-39: moderate utility
        4 | 5 => score -= 10.0,       // 40-59: good
        6 | 7 => score -= 14.0,       // 60-79: very reusable
        _ => score -= 6.0,            // 80+: nearly empty bin
    }

    // Modulo coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how tight
            let slack = (post_residual - next_item_size as u32) as f64;
            score -= 20.0 - slack * 0.3;
            if (post_residual as u32 % next_item_size.max(1)) == 0 {
                score -= 8.0; // exact harmonic subdivision
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score = 0.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size >= 60 && post_residual == bin_capacity as u32 {
            score -= 10.0; // big next item: fresh bin attractive
        }
    }

    // Progress modulation: tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual * 0.15);

    // Prefer bins with residuals far from mean (keeps diversity of classes).
    score += (post - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

