    if next_item_size > post_residual && post_residual < next_item_size.min(10) && post_residual > 0 {
        score += 20.0;
    }

    // Stream progression: later in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
