    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead-space penalty: small leftover that most items can't use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual as f64 - nxt;
        score -= 15.0 - 0.3 * chain;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would need another bin anyway; mild penalty for wasting space
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Scarcity pressure: fewer fitting bins -> favor this one
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state coupling: if mean residual is high, prefer bins below mean (balance)
    if bin_residual < bin_capacity {
        let dev = (mean_residual - resid) / cap;
        score -= 5.0 * dev;
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post / cap);

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 3.0 * crowding;
        // If item is large and few bins fit it, opening fresh is more acceptable
        if item / cap > 0.6 {
            score -= 10.0;
        }
        // If next item is small, new bin keeps flexibility
        if nxt > 0.0 && nxt < 20.0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: tight fit is good (low post_residual => low score)
    let mut score = norm_pr;

    // Smooth non-linear coupling with stream progress:
    // early on, waste matters more (bins last long); later, tightness dominates
    let waste_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += waste_penalty;

    // Reward near-perfect fits with a smooth bump around zero residual
    let perfect = (-norm_pr * 8.0).exp();
    score -= 1.5 * perfect * (0.5 + progress);

    // Lookahead: bonus if next item fits the post residual (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (1.0 - (nxt - pr).abs() / cap).max(0.0);
        let fits_exactly = ((pr - nxt) as f64 == 0.0) as u8 as f64;
        score -= 0.8 * fits_exactly + 0.4 * fits_next * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0 * (1.0 + progress);
    }

    // Scarcity of fitting bins: mild smooth reward
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 0.3 * scarcity;

    // New-bin candidate: penalize mildly unless current bin would leave large waste
    if bin_residual == bin_capacity {
        let threshold_bonus = (norm_pr - 0.0).max(0.0);
        score = 0.6 + threshold_bonus - 0.5 * progress * (1.0 - (pr / cap - 0.2).abs().min(1.0));
    }

    // Mean residual coupling: if open bins are on average roomy, prefer filling this one
    score -= 0.2 * (mean_residual / cap) * (1.0 - norm_pr);

    // Many open bins: encourage consolidation
    score += 0.05 * (open_bins_count as f64).sqrt() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: massive reward (subtract heavily)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space quality classes.
    // Residuals divisible by 10 are "reusable" (typical item granularity),
    // prime/small residuals are dead space.
    let pr = post_residual;
    let pr_mod10 = (pr % 10) as f64;
    if pr_mod10 == 0.0 {
        score -= 15.0; // residual aligns with item granularity
    } else if pr_mod10 >= 7.0 {
        score += 8.0; // awkward residual
    }

    // Integer-division thresholds: how many more "typical" items (<=10) fit
    let slots = pr / 10;
    score -= slots as f64 * 2.0;

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item also fits here: chain placement, reward
            let next_mod = (next_item_size % 10) as f64;
            score -= 10.0 + next_mod * 0.5;
            // bonus if post_residual - next is also harmonic (divisible by 10)
            if (pr - next_item_size) % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit: this bin becomes dead space for the future
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fit among many candidates
        score += 0.5 * fitting_bins_count as f64;
    }

    // Waste fraction coupling: penalize residual relative to capacity
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * 20.0;

    // Mean residual context: if this bin is far below mean residual, it's
    // already fragmented; mild penalty to prefer larger-residual bins.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: empty bin should only win when no open bin
    // gives a decent fit (post_residual close to capacity = bad reuse).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap * 0.6;
        // if the current item is large, opening fresh is often fine
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // if only one fitting bin exists, prefer using it instead
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 15.0;
    }

    // Small tie-breaker on exact-fill class via integer division of capacity
    let half = (bin_capacity / 2) as f64;
    if item_size as f64 > half && post_residual < 20 {
        score -= 5.0; // big item snugly placed
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Penalize medium-small gaps proportionally (quadratic coupling):
    // gaps that only fit tiny items are semi-dead.
    if post_residual >= 10 && post_residual < 25 {
        score += 0.8 * (25.0 - post_residual as f64) * (25.0 - post_residual as f64) / 10.0;
    }

    // Reward bins whose residual was already fragmented (high mean residual
    // spread) being consolidated: prefer filling bins with large residuals
    // when the fit is decent.
    if post_residual as f64 > mean_residual {
        score -= 5.0;
    } else if (post_residual as f64 - mean_residual).abs() < 2.0 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual < 10 {
            score -= 20.0; // still worth it, even if it creates dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward creating that gap; penalize if it blocks the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Tightness bonus: the smaller the waste relative to the item, the better.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item exactly fills the leftover space (perfect 2-step match)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snug the fit is
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * miss;
        }
        // Extra coupling: prefer bins whose post-residual stays near the mean residual
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Penalize tiny dead space that nothing (min size 1) can use efficiently
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 150.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Discard new empty bins unless current open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.5 {
            score += 200.0; // keep using open bins when they still have room
        } else {
            score -= 50.0; // open bins are nearly full; new bin is fine
        }
    }

    // Mild pressure to consolidate as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: low post_residual is already good,
    // add a superlinear bonus for near-perfect packing.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so when many
    // bins are open (fragmentation) or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 0.4 * open_bins_count as f64 + 6.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (consolidating space).
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Mild time-horizon shaping: late in the stream, be greedier about
    // filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear penalty for awkward residual sizes (dead space)
    let awkward = 4.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 12.0 * awkward * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 20.0 * (1.0 - fit_frac) * (1.0 - pr_norm) * (0.4 + 0.6 * progress);

    // Last-chance bin bonus (only one fitting bin)
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: prefer bins whose post-residual can host next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let next_fit = next_item_size as f64 / cap;
        score -= 10.0 * next_fit * (1.0 - pr_norm);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Penalize spreading across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * progress;

    // New-bin candidate: mildly encourage consolidation early, allow opening late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "dead zones"
    // (residuals that few item sizes can fill) should be penalized.
    let pr = post_residual;
    let dead = if pr == 0 {
        0.0 // perfect fit, ideal
    } else if pr < 10 {
        40.0 // tiny sliver, almost unusable
    } else {
        // number of item sizes (1..=100) that fit exactly into pr is 1;
        // approximate fillability by how many size classes fit
        let fillable = pr.min(100) as f64 / 10.0; // count of 10-wide classes fitting
        30.0 / (1.0 + fillable)
    };
    score += dead;

    // Modulo-10 harmonic class: residuals that are multiples of 10 are more
    // likely reusable by future items drawn from wide distributions.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0 + 0.1 * next_item_size as f64;
            // exact harmonic match: post_residual == next_item_size
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            // this bin becomes dead after placement while next item needs a bin
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be a tiny sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if pr > 0 && pr < 10 {
            score += 15.0; // but not if it creates an unusable sliver
        }
    }

    // New-bin candidate handling: an empty bin has full residual; only prefer it
    // when current item is large relative to capacity or mean residual is high.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 20.0 - 15.0 * frac; // penalty that shrinks for big items
        if mean_residual > 0.5 * cap {
            score -= 10.0; // open bins are congested; new bin attractive
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // pairing large items in fresh bins
        }
    }

    // Progress-aware tightness: as the stream advances, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr as f64) * 0.3;

    // Prefer bins with residual close to item (tight fit) via integer division threshold
    if bin_residual / item_size.max(1) == 1 {
        score -= 10.0; // item occupies more than half the bin: efficient
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_gap = next_item_size.min(10).max(1);
    if post_residual < min_gap {
        // Dead space: penalize heavily, proportional to how close the gap is to being useless.
        score += 60.0 * (1.0 - post_residual as f64 / min_gap as f64);
    } else {
        // Reward tight fits: smaller post_residual relative to capacity is better.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powf(2.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> allow flexibility.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below mean (consolidating waste).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item could exactly fill the resulting gap, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if no open bin
    // fits well (large dead-space risk) or the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64
            + 20.0 * desperation
            - 30.0 * (1.0 - progress)
            + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 40.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item still fits here; prefer tighter chains.
            score -= (post_residual as f64 - next_item_size as f64).min(30.0) * 0.3;
        } else {
            // Next item cannot follow in this bin; penalize wasted chain potential.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Penalize dead space relative to mean residual (fragmentation avoidance).
    let frag = post_residual as f64 - mean_residual;
    if frag > 0.0 {
        score += frag * 0.5;
    } else {
        score += frag * 0.1; // mild reward for below-average residual (tighter bin)
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (post_residual as f64).min(20.0) * 0.25;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and would leave awkward residue in any existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins generally; relax penalty slightly as stream progresses
        // and when the item is large relative to capacity.
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 20.0 * largeness - 5.0 * progress;
        // If the leftover after placement in a fresh bin is small, it is a good
        // anchor for future small items: soften the penalty.
        if post_residual <= 20 {
            score -= 8.0;
        }
    }

    // Slight preference for bins whose residual is already small (best-fit core).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            // next item won't fit here; slight penalty for wasted potential
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Discourage opening new bins when good open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If no open bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Prefer bins with below-average residual (concentrate filling).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Tight-fit reward: quadratic bonus for small post-residual, stronger late in stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 30.0 * (0.5 + progress);
    // Penalize large dead space non-linearly
    score += norm_post * norm_post * 25.0;
    // Exact fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }
    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 6.0 * progress;
    }
    // Last-chance bin reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: penalize opening a new bin when fit is decent
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - norm_item) + 10.0 * progress;
    }
    // Mean residual coupling: prefer bins deviating favorably from mean
    score += (mean_residual - post_residual as f64) * 0.3;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = post_f / cap_f;

    // Penalize dead space in low classes: post_residual in (0, 10] is nearly unusable
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - frac);
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Integer division thresholds: how many small items (<=10) fit in the leftover
    let small_slots = post_residual / 10;
    score -= 6.0 * small_slots as f64;

    // Modulo arithmetic: leftover congruent to common item sizes is more reusable
    let r = post_residual % 100;
    if r == 0 {
        score -= 30.0; // perfectly empty or full
    } else if r % 10 == 0 {
        score -= 10.0; // aligned with decade grid
    } else if r % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0; // awkward remainder
    }

    // Lookahead coupling: reward if next item fits exactly or near-exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - next_waste as f64 / cap_f);
        } else {
            // next item cannot fit here: slight penalty proportional to overflow
            score += 2.0 * ((next_item_size - post_residual) as f64 / 10.0).min(5.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a great fit
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral base, penalize slightly so good fits win
        score += 15.0;
        // But if current bin would leave tiny unusable residue, new bin is attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
        // Late in stream with many open bins, avoid opening more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (open_bins_count as f64 / 20.0).min(2.0);
    } else {
        // Reward tight fits into existing bins
        score -= 10.0 * (1.0 - frac);
        // Prefer bins with below-mean residual (keeps large residual bins flexible)
        if post_f < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any item
    // (items >= 1, but realistically small gaps < 10 are unusable for most).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize leaving a gap just below the next item's size (blocks lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward exact or near-exact fit for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to item need over bloated mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong bonus
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this dead space: penalize small post_residuals
            score += (post_residual as f64).min(50.0) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer when only one bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Prefer opening a new bin when current bin is very full and item is small
    if bin_residual == bin_capacity {
        // new empty bin candidate: penalize unless item is large or many bins open
        score += 50.0 + (bin_capacity as f64 - item_size as f64) * 0.5;
        if open_bins_count > 5 {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);
    score -= 10.0 * pressure * tightness;

    // Mean residual deviation: prefer bins below mean residual (filler bins).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0 - 14.0 * progress;
        // Open a new bin early if item is huge and nothing fits well.
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth interaction: residual waste penalized more strongly as stream progresses
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 2.0 * pr_norm * pr_norm * (1.0 + progress_coupling);

    // Reward tight fits with a cubic falloff on post_residual
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness * (1.0 + 0.5 * progress);

    // Penalize leaving a residual that is small but nonzero (dead space)
    if pr > 0 {
        let dead = pr_norm * (1.0 - pr_norm);
        score += 3.0 * dead * (0.5 + progress);
    }

    // Lookahead coupling: favor bins whose post_residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: only fitting bin should be strongly favored
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mean residual context: penalize bins far below mean residual (fragmented)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Mild preference to fill existing bins rather than open new ones
    score -= 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: residues that are "useless" (too small
    // to host anything meaningful) get a strong penalty; perfect fits get reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // modulo classes on post_residual
        let m = pr % 10;
        match m {
            0 => score -= 12.0,          // round residual, highly reusable
            1 | 2 | 3 => score += 15.0,  // sliver: near-dead space
            4 | 5 | 6 => score += 5.0,   // mediocre
            _ => score -= 3.0,           // 7..9 decent
        }
        // Integer-division thresholds: how many "small items" (<=10) still fit
        let slots = pr / 10;
        score -= 4.0 * slots as f64;
        if slots == 0 {
            score += 20.0; // residual unusable for min-size item
        }
    }

    // Capacity-fraction coupling: residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    score += 10.0 * (frac * frac); // penalize large leftover quadratically
    score -= 8.0 * (1.0 - frac);   // reward tight fits

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - gap as f64 / cap);
        }
        // harmonic class match: next item size mod 10 vs residual mod 10
        if (next_item_size % 10) == (pr % 10) && pr >= next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item cannot use this residual -> dead-space risk
        score += 10.0 + 0.15 * (next_item_size - pr) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Crowding bonus: many open bins -> consolidation pressure
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: keep it attractive when current residual is hopeless
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 0.0 - 0.0;
        if post_residual == bin_capacity {
            // only prefer new bin if item is large and no tight fit exists
            score = 70.0 - 0.5 * item_size as f64;
            if fitting_bins_count <= 1 {
                score -= 30.0;
            }
        }
    }

    // Stream progression: late in stream, be greedier about filling
    let prog = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * prog * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<=10) are nearly worthless dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately small gaps (10..25) are risky: many item sizes won't fit.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual can host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if post_residual cannot fit the lookahead item but bin_residual could
    // (we are burning a bin that could have served the next item).
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (subtract more for tight fits when bins are plentiful).
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * (bin_residual - post_residual) as f64 * 0.15;

    // Early in the stream, allow opening bins more freely; later, consolidate.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            // New-bin candidate: penalize more as stream progresses.
            score += 5.0 + 45.0 * progress;
        } else {
            score -= 10.0 * progress;
        }
    }

    // Prefer bins below the mean residual (filling emptier bins keeps
    // well-filled bins flexible)? Invert: prefer bins ABOVE mean residual
    // (tighter bins get closed out, looser bins absorb items).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 8.0 + 10.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        // Perfect chain: post_residual exactly equals next item size.
        if leftover_after_next == 0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot serve the next item.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual above mean are more reusable.
    score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual >= next_item_size;
        score += 25.0;
        if good_fit_exists {
            score += 20.0;
        }
        // Late in stream, discourage opening bins for few remaining items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Early stream: new bins are cheap, slight discount.
        score -= 8.0 * (1.0 - progress);
        // If many bins are open already, prefer consolidation.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for filling nearly-full bins harder as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residuals (dead space) unless near-zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits harder.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: later in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> discourage new-bin-ish behavior,
    // reward placements that reduce fragmentation.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.5 * residual_gap.max(0.0);

    // New-bin candidate calibration: empty bin should only win when fit is poor
    // or no good alternatives exist.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * progress;
    }

    // Mild preference for filling bins with more total content already.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Coupling: large items early should prefer fresh bins less; small items late
    // should pack into leftovers.
    if item_size < 20 && progress > 0.5 {
        score -= 12.0;
    }
    if item_size > 60 && open_bins_count > 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Non-linear waste penalty: dead space grows quadratically/cubically in relative residual
    let rel_post = post / cap;
    score += 40.0 * rel_post * rel_post;
    score += 25.0 * rel_post * rel_post * rel_post;

    // Reward near-perfect fits (small post_residual) with a smooth exponential bonus
    score -= 30.0 * (-post / 8.0).exp();

    // Stream-progress coupling: as stream advances, prefer tighter packing more strongly
    score *= 1.0 + 0.8 * progress * rel_post;

    // Penalize bins whose residual is far from the mean (fragmentation pressure)
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item can use the post residual, reward leaving usable space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: neutral residual (== capacity) should only win when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "useful" classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: residual is a near-perfect complement (tiny dead space) -> strong reward.
    if post_residual <= 5 {
        score -= 40.0 + (6 - post_residual) as f64 * 4.0;
    }
    // Class B: residual in the "recyclable" band 10..=30 (fits typical small items).
    else if post_residual >= 10 && post_residual <= 30 {
        score -= 12.0 + (30 - post_residual) as f64 * 0.4;
    }
    // Class C: dead zone 31..=49 -> hard to fill, penalize via modulo classes.
    else if post_residual >= 31 && post_residual <= 49 {
        let m = post_residual % 10;
        score += 15.0 + m as f64 * 1.5;
    }
    // Class D: residual 50..=99 -> still flexible but worse than B.
    else if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.3;
    }

    // Harmonic coupling with lookahead: if next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - slack * 0.5;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize proportional to wasted complementarity.
        score += ((next_item_size - post_residual) as f64) * 0.25;
    }

    // Exact division harmonics: residual divisible by common item sizes is valuable.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: prefer consolidating into tight fits.
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Early stream: keep bins tight to build good complements later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 10.0 };
        score += pressure - progress * 5.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 5.0; // fresh bin leaves full capacity anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1) is fine,
    // but gaps just above tiny item sizes that no future item likely fills are bad.
    // Treat gaps in (0, 10] as near-dead, and gaps that cannot fit the lookahead item.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 6.0; // nearly dead space, but near-full is somewhat good
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.5; // gap cannot host the next item: likely dead
        }
        // Non-linear penalty for mid-size dead zones: gaps in (10, 30) are awkward
        let pr = post_residual as f64;
        if post_residual > 10 && post_residual < 30 {
            score += (30.0 - pr) * 0.35;
        }
        // Reward leaving a gap that exactly fits the lookahead item (perfect pairing)
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0;
        }
        // Reward zero residual (perfect fit) strongly
        if post_residual == 0 {
            score -= 12.0;
        }
    }

    // Tightness reward: fraction of bin utilized by this placement
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 5.0;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize placements that keep many bins alive with scattered residuals).
    let obp = open_bins_count as f64;
    score += (obp / (obp + 4.0)) * (mean_residual.max(0.0)) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it only
    // when existing bins would leave large dead space. Penalize the new bin mildly
    // so it is chosen only when genuinely better.
    if bin_residual == bin_capacity {
        score += 4.0 + obp * 0.3;
        // If nothing fits well elsewhere (large mean residual wasted), opening
        // a new bin becomes relatively attractive.
        if mean_residual > 25.0 {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference for bins with larger residuals when item is small
    // (keep small items in emptier bins, preserving tight bins? inverse: keep
    // tight bins for small items). Encourage placing into bins whose residual
    // is close to item size (best-fit coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack * 0.15);
    }
    // Next item does NOT fit the residual: penalize proportionally to wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Reward tight fits (small post residual) nonlinearly.
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // Penalize residuals far below mean residual (fragmented bin relative to fleet).
    score += (mean_residual - post_residual as f64).abs() * 0.12;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Early in stream: be more conservative, keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use,
        // scaled by how close we are to the end of the stream.
        let horizon = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - horizon) * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer filling bins with below-average residual (consolidate waste).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // New-bin candidate: open a fresh bin only when no open bin fits well
    // or the item is large relative to available residuals.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64) // post_residual == residual - item for new bin = capacity - item
        };
        let _ = poor_fit;
        // Base cost of opening a new bin; cheaper early, costlier late.
        let horizon = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 120.0 + 40.0 * horizon + 2.0 * crowded;
        // Large items leave little residual in a new bin; that's efficient packing.
        new_bin_score -= 0.5 * item_size as f64;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            new_bin_score += 50.0;
        }
        // If the next item is huge, a fresh bin may serve it better.
        if next_item_size > 60 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized post-residual.
    let post_norm = post / cap;
    score += 18.0 * post_norm * post_norm * cap;

    // Reward tight fits (small post residual) with a smooth cubic bonus.
    score -= 12.0 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 - post_norm) * cap;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Scarcity coupling: when many bins open but few fit, prefer existing bins.
    let scarcity = (open_bins_count as f64) / (fitting_bins_count.max(1) as f64);
    score -= 4.0 * scarcity.ln().max(0.0);

    // Lookahead: penalize leaving residual slightly below next item (dead space),
    // reward residual that accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            let gap = (nxt - post) / cap;
            score += 10.0 * gap * gap * cap;
        }
    }

    // Mean-residual coupling: prefer bins whose residual diverges from the mean
    // when the mean is high (consolidate fragmented space).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly early, less as stream progresses;
    // but if it's a poor fit everywhere (many bins, none tight), allow it.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 * (1.0 - 0.5 * progress);
        let relief = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        score += base_penalty - relief;
        // Favor opening new bins when open bins are mostly full (low mean residual).
        score -= 5.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // Smooth stream-progress drift: later in stream, tolerate less waste.
    score += 8.0 * progress * post_norm * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let mut score = pr as f64;

    // Perfect fit: strongly favored
    if pr == 0 {
        score -= 200.0;
    } else {
        // Harmonic class of the leftover space (modulo 10):
        // tiny awkward leftovers (1..9) are dead space -> penalize by class
        let m = pr % 10;
        score += m as f64 * 1.5;
        // Round residuals (multiples of 10) are reusable by common item classes
        if m == 0 {
            score -= 12.0;
        }
        // Half-capacity harmonic class is highly reusable
        if pr % 50 == 0 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= next_item_size as f64 * 0.6;
            // exact pairing: item + next == residual -> ideal
            if next_item_size == pr {
                score -= 40.0;
            }
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        // Default: prefer existing bins
        score += 45.0 + item_size as f64 * 0.3;
        // No open bin can fit -> must open new bin
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Large items fragment less if given a fresh bin
        if item_size >= 50 {
            score -= 35.0;
        }
    } else {
        // Last-chance bin: if this is the only fitting bin, use it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses
    let t = step_index as f64 / total_items.max(1) as f64;
    score += t * 3.0 - mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Strict dead-space avoidance: leftover that cannot host the lookahead item
    // is unusable dead space -> penalize proportionally to how far short it falls.
    if post_residual > 0 {
        if next_item_size == 0 {
            // No lookahead: mild penalty grows toward stream end (gaps won't be filled).
            score += 6.0 * progress;
        } else if (post_residual as f64) < next_item_size as f64 {
            let shortfall = next_item_size as f64 - post_residual as f64;
            score += 5.0 + 0.6 * shortfall;
        }
    }

    // Prefer bins tighter than the current average residual (consolidation).
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= 0.25 * tightness;
    } else {
        score += 0.15 * (-tightness);
    }

    // Last-chance bonus: this is the only open bin that fits -> use it
    // rather than fragmenting capacity into a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin, scaled by open-bin pressure.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64 + 5.0 * (1.0 - progress);
        // But if the new bin would be tighter than average open bins, soften slightly.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: leaving no dead space is ideal.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize small unusable residuals (dead space below typical minimum item size).
        let min_item = 1.0;
        if (post_residual as f64) < min_item * 2.0 {
            score += 100.0;
        }
        // Exponential penalty for tiny-but-nonzero dead space.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += (1.0 - tightness) * 30.0;
    }

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can also fit here: strong reward for chained placement.
            let chain_fit = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 120.0 + 80.0 * chain_fit;
            // Extra reward if the chain nearly exhausts the bin.
            if post_residual - next_item_size <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit after this placement; mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            // If the next item could fit in mean residual, prefer bins keeping that option.
            if mean_residual >= next_item_size as f64 && post_residual < next_item_size {
                score += 25.0;
            }
        }
        // If the current bin could have chained but we'd waste a large residual, penalize.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 40.0 * (1.0 - progress);
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score -= 200.0;
    }

    // ---- Relative-to-mean coupling ----
    // Bins with residual below mean are already tight; placing here (good fit) is favored.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin if fit is decent.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 90.0;
        } else {
            score -= 30.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is worthwhile when existing fits are poor (large post_residual
        // spread across fitting bins) or the item is small relative to residual.
        let poor_fits = if fitting_bins_count > 0 {
            let avg_post = mean_residual - item_size as f64;
            avg_post > 40.0
        } else {
            true
        };
        if poor_fits {
            score -= 60.0;
        } else {
            // Prefer reusing open bins early; allow new bins later when they enable chains.
            if next_item_size > 0 && next_item_size <= bin_capacity - item_size && progress > 0.5 {
                score -= 40.0;
            } else {
                score += 80.0 * (1.0 - progress) + 20.0;
            }
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if next_item_size > 0 && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Small regularization against bin count explosion late in stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already low).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is excellent; if next item would fit only in a fresh bin,
    // slight penalty for consuming too much.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        }
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 3.0; // next item could have gone here too; competition
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer fuller ones (less post_residual
        // relative to mean residual).
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize it moderately so decent fits win.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        // Late in stream, opening bins is less costly (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Time horizon: early on, keep bins flexible (avoid extreme tight fits
    // that strand space); later, pack tight aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferation of open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // base: minimize wasted residual, with non-linear polynomial shaping
    let mut score = pr_norm.powf(1.0 + 0.5 * progress) * cap;

    // quadratic coupling: dead space penalized more as stream progresses
    score += 4.0 * progress * pr_norm * pr_norm * cap;

    // interaction with mean residual: prefer bins deviating below mean residual
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap - 1.5 * dev * cap * (0.5 + progress);

    // lookahead: reward residual that can fit next item (smooth coupling)
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 3.0 * (1.0 - fit_gap) * next_norm * (1.0 - progress);
    }

    // last-chance bin gets strong reward
    if fitting_bins_count == 1 {
        score -= 2.0 + 3.0 * item_norm;
    }

    // new-bin candidate: mild penalty unless post_residual unusable
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that align with common item-size classes
    // (multiples of 5 and 10 are frequent; small dead space is wasted).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit is ideal
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // chainable residual
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic class of the leftover gap
            if gap % 10 == 0 { score -= 8.0; }
            else if gap % 5 == 0 { score -= 4.0; }
            else { score += (gap as f64) * 0.15; }
        } else {
            // next item cannot fit here; residual likely dead space
            score += (pr as f64) * 0.1;
        }
    } else {
        // last item: only the empty-fill matters
        score -= 5.0;
    }

    // Integer-division threshold on post_residual: residuals < 10 are near-dead
    if pr > 0 && pr < 10 {
        score += 14.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current residual is truly bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (pr as f64) > mean_residual * 0.9; // would leave worse residual than average
        let mut penalty = 10.0 + 25.0 * progress;
        if bad_fit { penalty += 15.0; }
        if fitting_bins_count == 0 { penalty = 0.0; }
        score += penalty;
    }

    // Slight preference for bins with tighter current fit (less wasted capacity overall)
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= tightness * 3.0;

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are unusable.
