        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to lookahead
    }

    // New-bin candidate: only attractive when current item would leave a bad gap
    // or when open-bin fits are scarce.
    if bin_residual == bin_capacity {
        score = 100.0 - 20.0 * fill;
        if post_residual < min_item.max(next_item_size.min(80)) && post_residual > 0 {
            score -= 35.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        score += 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

