        } else {
            (post_residual as f64).max(0.0)
        };
        score += 45.0 - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the larger next item too
        }
        let _ = waste_existing;
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

