    // Harmonic classes on post_residual (modulo arithmetic):
    // residuals divisible by 10 are "harmonic" with capacity 100 -> reusable
    let m = post_residual % 10;
    score -= match m {
        0 => 7.0,
        1 | 2 | 3 => 4.0,
        4 | 5 | 6 => 1.5,
        _ => 0.0,
    };

    // Integer-division thresholds: post_residual / 10 class
    let class = post_residual / 10;
    score -= match class {
