        1 => 6.0,           // 10..19
        2 => 3.0,           // 20..29
        3 => 1.0,           // 30..39
        _ => 0.0,           // large leftover space: weak
    };

    // Reward when the lookahead item also fits into the leftover space
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let slack_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 9.0 * (1.0 - slack_ratio);
    } else if next_item_size > 0 && post_residual < 10 {
        // dead space: next item can't use it, residual too small for anything
        score += 12.0;
    }

    // Item-size coupling: larger items deserve tighter fits
    score -= (item_size as f64 / cap) * 12.0;

    // Progress coupling: late in the stream, be greedier about tight fits
    score -= progress * 4.0;

    // Mean-residual context: when open bins are collectively full,
    // preserving tight fits matters less; when loose, avoid waste
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Default: discourage opening a new bin when open bins can fit
        score += 28.0;
        // But if this bin is effectively the only fitting option, embrace it
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Large items fragment bins; better in a fresh bin
        if item_size >= 50 {
            score -= 12.0;
        }
        // Mid-stream, prefer consolidation; early, fresh bins are cheap
        score -= (1.0 - progress) * 8.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it before opening a new one
        score -= 22.0;
    }

    score
}

