    // mean residual (tightening the average), penalize inflating the mean.
    let pr = post_residual as f64;
    score += 0.5 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it over opening a new bin (unless post residual would be huge).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - pr / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // this item is large and no open bin gives a tight fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally, less so for large items early on.
        score += 30.0 - 20.0 * tightness * (1.0 - progress);
    } else {
        // Reward placing into existing bins, more for tight fits.
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * fill;
    }

    // Mild penalty for fragmenting when many bins are already open.
    score += 0.5 * (post_residual as f64).powf(1.3) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let frac_used = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * frac_used * frac_used;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving small unusable dead space (post_residual < min item size 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving large residuals late in stream.
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += 4.0 * t * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer any bin, penalize new bins heavily.
        if bin_residual == bin_capacity {
            score += 1000.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so we prefer existing bins when reasonably tight fits exist.
        score += 20.0;
        // Late in the stream with many open bins, opening new bins is wasteful.
        score += 15.0 * t + 0.5 * open_bins_count as f64;
        // If mean residual is large, open bins have room: penalize new bin more.
        score += 0.3 * mean_residual;
        // If no other bin fits (fitting_bins_count counts only open bins; new bin call
        // sees same count), and this is the sole fitting option, the last-chance logic
        // above doesn't apply, so soften the penalty via post_residual (== capacity).
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Prefer fuller bins among open ones (mild best-fit tiebreak already via post_residual).
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight fit preferred)
    let mut score = pr;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, dead space matters more; early, keep bins flexible.
    let dead_space_penalty = norm_pr * norm_pr * cap * (0.5 + 1.5 * progress * progress);
    score += dead_space_penalty;

    // Smooth reward for near-perfect fits (post_residual small relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let fit_next = (next_item_size as f64) <= pr;
        let margin = (pr - next_item_size as f64).abs();
        if fit_next {
            score -= 8.0 * (1.0 - margin / cap) * (0.3 + 0.7 * progress);
        } else {
            score += 4.0 * (margin / cap) * norm_pr;
        }
    }

    // Last-chance bin: strongly favor using it when it's the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balanced usage)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // New-bin candidate: prefer keeping it closed early; allow opening late smoothly
    if bin_residual == bin_capacity {
        let openness = progress * progress;
        score += 20.0 * (1.0 - openness) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "useful" small classes, penalize awkward mid-range dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (tiny residual) -> strong reward.
    if post_residual <= 5 {
        score -= 30.0 + (5.0 - pr) * 5.0;
    }
    // Class B: residual divisible into common item sizes (harmonic buckets 10..80)
    else {
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 40, 50, 80] {
            if post_residual % d == 0 && post_residual > 0 {
                harmonic_bonus += 6.0;
            }
        }
        score -= harmonic_bonus;
        // Penalize unusable mid-range dead space (residual too small for
        // typical items but too large to be "full").
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // dead space below minimum item size
        }
    }

    // Integer-division threshold: residual / item ratio classes.
    let ratio = pr / (item_size as f64).max(1.0);
    if ratio < 0.25 {
        score -= 8.0; // bin nearly saturated, good
    } else if ratio > 2.0 {
        score += 4.0; // leaving a lot relative to item, mild penalty
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize more if the wasted residual is large
        score += pr * 0.05;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that must be
    // beaten by genuinely good fits, but beats poor fits.
    if bin_residual == bin_capacity {
        // Neutral-ish anchor; slightly worse than a good existing fit,
        // better than scattering into many bins.
        score += 15.0;
        // Early in stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 10.0 * (1.0 - progress);
        // If next item is large and current item small, a fresh bin is attractive.
        if next_item_size > 60 && item_size < 30 {
            score -= 10.0;
        }
    }

    // Prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Mean residual coupling: bins deviating below mean residual are tighter,
    // favor them slightly.
    score += (mean_residual - pr) * 0.1;

    // Progress-based tie-breaking: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation as open bins accumulate.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a better future fit
    // (large lookahead item) or open bins are already congested/tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / bin_capacity as f64;
        let lookahead_bonus = if next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.5 { 0.0 } else { 15.0 };
        score = score - 10.0 * (1.0 - congestion) + progress * 5.0 + lookahead_bonus + (open_bins_count as f64) * 0.5;
        // Penalize new bin if current bin leaves a very usable gap.
        if post_residual >= 40 {
            score += 20.0;
        }
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a soft quadratic penalty.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward residuals that exactly match the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect chain match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 20.0 - 3.0 * diff;
        } else {
            // Penalize residuals that are awkwardly larger than the next item (dead space).
            score += 0.15 * diff;
        }
        // If this bin can't host the next item but another could, slight bonus for compacting here.
        if post_residual < next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // filling them is good if fit is tight, bad if it leaves scraps.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            // Fresh bin leaves room for the next item too — mild appeal.
            score -= 12.0;
        } else {
            // Penalize opening a new bin: prefer existing bins unless forced.
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else if fitting_bins_count == 0 {
        // Should not happen for open bins, but guard.
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are usually dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild penalty spread when many bins compete, keeps ordering stable
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 20.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting the residual
            score += 6.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins
    // rather than fragmenting; when low, be pickier.
    score -= 0.15 * mean_residual;

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // New-bin candidate handling: an empty bin gets a neutral-ish base but must not
    // win unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 - 8.0 * tightness;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for upcoming large items
        }
        if fitting_bins_count == 1 {
            score += 50.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Slight penalty for accumulating many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // residual as fraction of capacity

    // Penalize residuals that are "wasted" — too small to fit typical items (>=10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }

    // Harmonic band rewards: residuals near useful class boundaries are good.
    // Classes: [0], (0..10], (10..25], (25..50], (50..100]
    if post_residual == 0 {
        score -= 120.0; // perfect fit — strongly favored
    } else if post_residual >= 50 {
        score -= 15.0 * frac; // large residual still usable
    } else if post_residual >= 25 {
        score -= 5.0;
    } else if post_residual >= 10 {
        score += 8.0; // small but usable residual — mild penalty
    }

    // Integer-division harmonic class on post_residual (mod arithmetic).
    let class = post_residual / 10;
    score += match class {
        0 => 40.0,
        1 => 10.0,
        2 => 2.0,
        3 => -4.0,
        _ => -10.0,
    } as f64;

    // Lookahead coupling: reward leaving space exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0; // next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 45.0; // next item nearly fills bin — great
            } else {
                score -= (slack as f64).sqrt() * 3.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // new bins when open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.85 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        // Prefer new bin if all fits would leave tiny unusable residuals.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight drift with stream progression: tighten packing later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (1.0 - frac);

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // good "garbage collector" bin; if far above, deprioritize.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1..~10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Tight-fit reward: fraction of bin used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Penalize leaving a gap that next item could still use but only barely
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // residual remains useful for lookahead
        } else if post_residual > 0 {
            score += 6.0; // residual too small for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to item size (best-fit style)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Early in stream, be more liberal with opening bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    // Reward strongly when the NEXT item exactly fills the post_residual (perfect chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match (gap 0) gets a big bonus; decays quadratically with gap.
        let match_bonus = 60.0 * (1.0 - gap / post_residual as f64).powi(2);
        score -= match_bonus;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize, more so for large wasted tails.
        let dead = post_residual as f64;
        let next_fits_elsewhere_hint = (next_item_size as f64) / bin_capacity as f64;
        score += 8.0 * dead * (0.5 + 0.5 * next_fits_elsewhere_hint) * (1.0 + progress);
    }

    // Penalize tiny unusable residuals (< 10, minimum item size) harder as stream progresses.
    if post_residual < 10 {
        score += 25.0 + 20.0 * progress;
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 6.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: discourage opening yet another bin; encourage consolidation.
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate: keep it attractive only when no open bin offers a good fit
    // (i.e., post_residual of this fresh bin is large and next item may chain into it).
    if bin_residual == bin_capacity {
        let fresh_bonus = 20.0
            + (next_item_size as f64) * 0.15
            + 15.0 * progress
            + if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 };
        score -= fresh_bonus;
        // But if a last-chance bin exists, prefer using it instead of a fresh bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        // Small post-residual is likely dead space for items >= 10.
        score += 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // enabling a two-item chain; penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin when decent fits exist,
    // but allow it when open bins would leave large dead space or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Opening a new bin is attractive when the item is large (few will stack anyway)
        // or when open bins are congested (low mean residual) and many exist.
        score = 45.0
            - 30.0 * pressure
            - 10.0 * progress
            + 0.8 * mean_residual
            - 2.0 * open_bins_count as f64;
        // A large item that leaves a reusable gap (~50) is fine in a fresh bin.
        if post_residual >= 50 {
            score -= 15.0;
        }
    }

    // Mild global congestion coupling: when many bins are open and mean residual is low,
    // prefer consolidating into existing bins (already reflected); when mean residual is high,
    // slightly discourage wasting it on small items.
    if bin_residual != bin_capacity {
        score += 0.05 * mean_residual * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling: dead-space penalty grows quadratically with progress
    score += 6.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Next-item lookahead: penalize if next item fits into post_residual (keeps chain alive),
    // reward slightly if next item would be wasted here
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 4.0 * (1.0 - post / (nx + 1.0)) * (0.5 + progress);
        } else {
            let waste = (nx - post) / cap;
            score += 3.0 * waste * waste;
        }
    }

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer bins where item fills proportionally more
        score += 2.0 * (1.0 - item_size as f64 / (bin_residual as f64 + 1.0));
    }

    // Mean residual context: prefer bins below mean residual (denser bins first)
    score += 0.05 * (post - mean_residual);

    // New-bin candidate: mild penalty so it's chosen only when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact small classes are valuable.
    let post = post_residual as u32;
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= 5 {
        score -= 25.0;
    } else if post <= 10 {
        score -= 12.0;
    } else if post <= 20 {
        score -= 4.0;
    } else {
        // dead-space penalty grows for large unusable residuals
        score += (post as f64 - 20.0) * 0.35;
    }

    // Modulo classes: residuals that are multiples of common small sizes
    // (e.g. 10, 20, 25, 50) are more reusable.
    let reusable = (post % 10 == 0) || (post % 20 == 0) || (post % 25 == 0) || (post % 50 == 0);
    if reusable && post >= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            // next item fits; reward proportional to how well it fills
            let fill_after = (post - next_item_size) as f64;
            score -= 18.0 - fill_after * 0.3;
        } else {
            // next item won't fit here; slightly penalize leaving medium gaps
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Fractional capacity coupling: prefer bins whose post_residual is a
    // small fraction of capacity.
    let frac = post as f64 / cap;
    score += frac * frac * 30.0;

    // Integer-division threshold on item size: big items should go into
    // tight bins to avoid fragmentation.
    if item_size > bin_capacity / 2 {
        score -= 6.0;
    }

    // Early in the stream, allow slightly looser fits (exploration);
    // later, tighten up.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Mild preference for closing out bins when many are open.
    if open_bins_count > 4 && post <= 15 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small post_residual gaps are "unusable" if smaller
    // than the smallest plausible item (1..100 unknown dist -> treat <20 as dead).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 * 2.0;
    score += open_pressure * 0.5;

    // Lookahead: if next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would NOT fit here, slight penalty (this bin is a dead end).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: bins with residual near mean are neutral;
    // prefer placing into bins with larger residual (keep small-residual bins tight).
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = 70.0 + 10.0 * (fitting_bins_count as f64).recip();
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect two-item pairing bonus: post_residual exactly consumed next step.
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 12.0 + 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize larger leftover dead space.
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // pair large items together in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize large unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 4.0; // forces a new bin for the next item anyway
        }
        // Extra reward if next item fills this bin exactly after current item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 30.0 * tightness;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * (open_bins_count as f64).ln() * (1.0 - tightness);

    // Global residual pressure: if mean residual is high, encourage using fullest bins.
    if mean_residual > post_residual as f64 {
        score += 0.5 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.5 * (post_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let fallback_bias = 12.0 + 20.0 * (1.0 - (item_size as f64 / bin_capacity as f64));
        score += fallback_bias;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Late in the stream, avoid opening new bins for small items.
        if progress > 0.5 && item_size < 40 {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap to fix later; late, waste is permanent.
    let waste_penalty = post * post / cap * (0.4 + 1.6 * progress * progress);
    score += waste_penalty;

    // Reward near-perfect fits more than linearly (smooth cubic term).
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * tightness * 6.0;

    // Lookahead: if next item fits into post_residual, big reward (smooth).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            let miss = (nx - post) / cap;
            score += 3.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 + 3.0 * progress;
    }

    // New-bin candidate: penalize opening bins when decent fits exist,
    // more strongly as stream progresses; but allow it if open bins are very full.
    if bin_residual == bin_capacity {
        let avg_open_fill = cap - mean_residual;
        let desperation = (avg_open_fill / cap).powf(2.0);
        score += 8.0 + 6.0 * progress - 10.0 * desperation;
    }

    // Mild preference for filling bins below mean residual (balance smoothing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 - progress);

    // Slight penalty for many open bins to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: small dead space is bad, but
        // residual that is a multiple of common item classes is reusable.
        let pr = post_residual;
        // Penalize awkward residuals (not divisible by 10, in "dead zones")
        if pr % 10 == 0 {
            score -= 8.0; // aligned residuals pair well with 10-multiples
        }
        if pr % 20 == 0 {
            score -= 4.0; // even better alignment
        }
        // Dead-zone penalty: residuals that almost nothing fits into
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        } else if pr < 30 {
            score += 5.0;
        }
        // Integer division thresholds: residual / 10 class
        let class = pr / 10;
        score -= class as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // next item can't use this residual; slight penalty scaled by waste
        score += 3.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter competition resolution via residual
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin should be chosen only when
    // open bins have poor fits. Baseline score for empty bin ~ capacity.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly above good fits, below bad fits.
        score = bin_capacity as f64 * 0.75 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits elsewhere; new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // stacking large items together
        }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Prefer filling bins below mean residual (above-average fullness).
    score += 0.1 * (mean_residual - post_residual as f64);

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible item (>=1, but realistically small items)
    // can use it well; the smaller the leftover, the worse the waste ratio.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            // Unusable sliver: strong penalty proportional to how tiny it is.
            score += (10 - post_residual) as f64 * 4.0;
        } else if post_residual <= 20 {
            // Marginal gap: moderate penalty scaled by waste ratio.
            score += 20.0 * waste_ratio;
        }
    } else {
        // Perfect fill: big reward.
        score -= 60.0;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_fraction = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_fraction;

    // Lookahead: if the next item fits exactly in the post_residual, reward;
    // if next item is blocked by post_residual but would fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // Next item fits current bin but not after placing here.
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that grows with open bins,
        // relaxed only if existing residuals are large and fragmented.
        score += 30.0 + bin_pressure;
        if mean_residual > 40.0 {
            score -= 15.0; // plenty of room exists; new bin unattractive
        }
    } else {
        // Existing bin: mild reward to consolidate, stronger when many bins open.
        score -= 2.0 + 0.3 * bin_pressure;
        // Prefer bins with below-mean residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Slight early-stream caution: keep bins flexible early on.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional stream progress (0..1), time horizon term.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness reward: strongly favor small post_residual (perfect fits).
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * fit_quality * fit_quality;

    // Penalize dead space that is too small to be useful later (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if post-residual is slightly too small for the next item,
    // mild penalty for stranding it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // exact two-item chain fill
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins -> discourage opening new ones, encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate score. Open a new bin only when:
        //  - item is large relative to capacity, or
        //  - few bins fit the item and open-bin residuals are small on average.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 45.0
            + 40.0 * pressure
            + 25.0 * mean_tightness
            - 35.0 * item_frac
            - 20.0 * (fitting_bins_count as f64).recip().min(1.0)
            - 10.0 * progress;
        // Late in the stream, prefer filling existing bins even imperfectly.
        if progress > 0.7 {
            score += 20.0 * (progress - 0.7) / 0.3;
        }
    } else {
        // Existing bin: mild penalty proportional to bin count to prefer fewer bins overall.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;
    }

    // Coupling with mean residual: bins far below mean residual are "loose";
    // filling a loose bin is cheap, filling a tight bin wastes scarce space.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.08 * residual_gap;

    // Small noise-free tie-breaker by index progression for deterministic stability.
    score += 0.001 * (step_index as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared normalized fill
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Penalize large dead space non-linearly
    let dead = post_residual as f64 / cap;
    score += 20.0 * dead * dead;

    // Smooth interaction: dead space penalty grows with stream progress
    score += 25.0 * progress * dead * dead * cap * 0.5;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when other bins fit
    if bin_residual == bin_capacity {
        let waste_if_open = post_residual as f64; // = capacity, full residual
        score += 15.0 + 60.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64).sqrt();
        // But if existing bins would leave big dead space, soften penalty
        let mean_dead = mean_residual / cap;
        score -= 25.0 * mean_dead * mean_dead;
        // Lookahead: if next item fits the new bin's residual nicely, soften
        if next_item_size > 0 && next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit * next_fit;
        }
    }

    // Lookahead: penalize placing item here if it blocks the next item
    if next_item_size > 0 && next_item_size > post_residual && bin_residual != bin_capacity {
        score += 8.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fill;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins)
    score -= 5.0 * ((mean_residual - bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Penalize post-residuals that are not "usable" harmonic classes.
    // Small leftovers (1..9) are dead space; multiples of 10 are more reusable.
    if pr > 0 {
        score += (10.0 - class) * 0.6; // residue 9 (worst class) penalized most
        if pr < 10 {
            score += 12.0; // tiny dead space
        }
    } else {
        score -= 25.0; // perfect fit, heavily reward
    }

    // Next-item lookahead: reward if next item fits exactly in post_residual (chain fit)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect chain
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // harmonic class match between next item and post residual
            if (pr % 10) == (next_item_size % 10) {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let over = (next_item_size - pr) % 10;
            score += over as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open fewer new bins early; allow more later when open bins are fragmented
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 100.0 + 50.0 * fragmentation - 30.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 20.0; // next item needs a fresh bin anyway
        }
        if pr == 0 {
            score -= 10.0; // item exactly fills a fresh bin
        }
    }

    // Slight preference for fuller bins (smaller residual before placement)
    score += (bin_residual as f64 / cap) * 2.0;

    // Many open bins: prefer consolidating into existing ones
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Penalize "hard" dead space: residuals too small to be useful for typical items.
    // Treat residuals below 10 as near-dead (soft penalty), scaled by how close to dead.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits strongly (small post_residual is good, but perfect fits best).
    if post_residual == 0 {
        score -= 120.0;
    } else {
        // Non-linear reward: quadratic tightness bonus.
        let tight = (bin_residual - post_residual) as f64 / bin_capacity as f64;
        score -= tight * tight * 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty in crowded choice to sharpen discrimination between bins.
        score += 5.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + open_bins_count as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, reduced late in the stream.
        score += 55.0 + 45.0 * pressure - 15.0 * progress;
        // If no open bin fits at all, new bin is necessary: reduce its cost.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Existing bin: reward using open bins, more so when many are open.
        score -= 10.0 * pressure;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus;
    // if post residual is smaller than next item but nonzero, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin portfolio balanced), avoid outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly favor bins that become nearly full.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // 2-step lookahead: reward if the next item exactly fills the new residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain: item + next item fill the bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it fits after
            let chain_residual = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (chain_residual as f64) / (bin_capacity as f64));
        } else {
            // next item does NOT fit in this bin: penalize wasted residual
            let waste = (post_residual as f64) - (next_item_size as f64);
            score += waste.clamp(0.0, 60.0) * 0.8;
        }
    } else {
        // Last item: maximize packing tightness.
        score -= 20.0 * (1.0 - tightness);
    }

    // Relative-to-mean adjustment: bins with residual far below mean are precious
    // small-capacity bins; penalize dumping large items there unless tight fit.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score -= dev * 0.15; // below-mean residual bins slightly favored
    } else {
        score += dev * 0.05;
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    // heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when item is large or
    // current open bins are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base penalty for opening a new bin (amortization), softened by progress.
        let mut new_bin_score = 45.0 + open_pressure * 2.0 - progress * 15.0;
        // If the item is huge relative to capacity, a fresh bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            new_bin_score -= 25.0;
        }
        // If many bins can fit, discourage opening a new one.
        if fitting_bins_count > 2 {
            new_bin_score += 20.0;
        }
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 20 {
            new_bin_score -= 10.0;
        }
        score += new_bin_score;
    }

    score
}
